// ============================================================
// CODE - VALIDAR PERGUNTA
// Agente SQL Financeiro DuckLake
// v2.2.12-lab-contexto-contabil-expandido
//
// Objetivo:
// - Validar segurança básica da pergunta.
// - Preservar pergunta e options.
// - Bloquear comandos destrutivos ou pedidos fora do domínio.
// - Reconhecer contexto financeiro/contábil de forma mais ampla.
// ============================================================

const bodyInput = $json.body || {};
const optionsInput = $json.options || bodyInput.options || {};
const pergunta = bodyInput.pergunta || $json.pergunta || "";

if (!pergunta || !String(pergunta).trim()) {
  throw new Error("Pergunta não informada.");
}

function normalizarPergunta(texto) {
  return String(texto || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[?!.;,:\"'`´]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

const perguntaNormalizada = normalizarPergunta(pergunta);
const perguntaLower = perguntaNormalizada;

function testAny(patterns, value) {
  return patterns.some((pattern) => pattern.test(value));
}

// ============================================================
// Contexto contábil/financeiro permitido
// ============================================================
// Esta flag é observacional para os próximos nodes.
// Ela não deve ser estreita demais, porque o usuário pode perguntar:
// - contas maiores e menores
// - gastos com pessoal
// - orçamento vs realizado
// - grupo DRE
// - OPEX por centro de custo
// - faturamento por marca
// ============================================================

const contextoContabilPermitido = testAny(
  [
    /\bconta contabil\b/i,
    /\bcontas contabeis\b/i,
    /\bcontas que tiveram\b/i,
    /\bcontas com\b/i,
    /\bcontas de dre\b/i,
    /\bcontas maiores\b/i,
    /\bcontas menores\b/i,
    /\bmaiores e menores\b/i,
    /\bcontas maiores e menores\b/i,

    /\bdre\b/i,
    /\bgrupo dre\b/i,
    /\bgrupos dre\b/i,
    /\blinha dre\b/i,
    /\blinhas dre\b/i,
    /\bresultado\b/i,
    /\bresultado liquido\b/i,
    /\bresultado líquido\b/i,

    /\borcamento\b/i,
    /\borçamento\b/i,
    /\borcado\b/i,
    /\borçado\b/i,
    /\brealizado\b/i,
    /\bvariacao\b/i,
    /\bvariação\b/i,
    /\bvariancia\b/i,
    /\bvariância\b/i,
    /\bdiferenca\b/i,
    /\bdiferença\b/i,

    /\bestouro de orcamento\b/i,
    /\bestouro de orçamento\b/i,
    /\bestouros de orcamento\b/i,
    /\bestouros de orçamento\b/i,
    /\bmaiores estouros\b/i,
    /\bacima do orcamento\b/i,
    /\bacima do orçamento\b/i,
    /\babaixo do orcamento\b/i,
    /\babaixo do orçamento\b/i,

    /\bopex\b/i,
    /\bgastos com pessoal\b/i,
    /\bgastos gerais\b/i,
    /\bdespesas gerais\b/i,
    /\bdespesas operacionais\b/i,
    /\bgastos operacionais\b/i,
    /\bcmv\b/i,
    /\brol\b/i,
    /\bfaturamento\b/i,
    /\breceita\b/i,

    /\bcentro de custo\b/i,
    /\bcentros de custo\b/i,
    /\bsetor\b/i,
    /\bsetores\b/i,
    /\barea\b/i,
    /\bareas\b/i,
    /\bdepartamento\b/i,
    /\bdepartamentos\b/i,

    /\bmarca\b/i,
    /\bmarcas\b/i,
    /\brivatti\b/i,
    /\brenna\b/i,
    /\bpix\b/i,
    /\bmetalfox\b/i,
    /\bmonobox\b/i,
    /\bsolar\b/i,
    /\btrie\b/i
  ],
  perguntaLower
);

// ============================================================
// Bloqueios de comandos destrutivos ou mutação
// ============================================================

const termosProibidos = [
  "apague",
  "apagar",
  "delete",
  "deletar",
  "excluir",
  "remover",
  "drop",
  "truncate",
  "alter",
  "update",
  "insert",
  "upsert",
  "merge",
  "replace",
  "create",
  "criar tabela",
  "alterar tabela",
  "excluir tabela",
  "dropar",
  "limpar tabela",
  "renomear tabela",
  "criar view",
  "criar indice",
  "criar index",
  "grant",
  "revoke",
  "vacuum",
  "analyze",
  "execute",
  "call",
  "copy",
  "refresh materialized",
  "set role",
  "reset role",
  "drop table",
  "delete from",
  "update set",
  "insert into",
  "truncate table",
  "alter table"
];

if (termosProibidos.some((termo) => perguntaLower.includes(termo))) {
  throw new Error("Solicitação bloqueada por segurança antes da geração de SQL.");
}

// ============================================================
// Bloqueios de objetos sensíveis ou metadados do banco/app
// ============================================================

const padroesObjetosSensiveis = [
  /\bauth\.users\b/i,
  /\bauth users\b/i,
  /\bstorage\.objects\b/i,
  /\bpg_catalog\b/i,
  /\binformation_schema\b/i,
  /\bsupabase\b/i,
  /\bvault\b/i,
  /\bextensions\b/i,
  /\busuarios do sistema\b/i,
  /\busuarios cadastrados\b/i,
  /\bcontas de usuario\b/i,
  /\bcredenciais\b/i,
  /\bsenhas\b/i,
  /\btokens\b/i,
  /\bchaves de api\b/i,
  /\bapi keys\b/i,
  /\btabelas do banco\b/i,
  /\btodas as tabelas\b/i,
  /\blistar tabelas\b/i,
  /\bschema do banco\b/i,
  /\bestrutura do banco\b/i
];

for (const padrao of padroesObjetosSensiveis) {
  if (padrao.test(perguntaLower)) {
    throw new Error("Solicitação incompatível com as políticas de consulta.");
  }
}

// Evita falsa interpretação de "contas" como contas de usuário.
if (!contextoContabilPermitido) {
  const padroesContasNaoContabeis = [
    /\bcontas de usuario\b/i,
    /\bcontas cadastradas\b/i,
    /\bcontas do sistema\b/i,
    /\blogins\b/i,
    /\busuarios\b/i
  ];

  for (const padrao of padroesContasNaoContabeis) {
    if (padrao.test(perguntaLower)) {
      throw new Error("Solicitação incompatível com as políticas de consulta.");
    }
  }
}

// ============================================================
// Bloqueios de extração massiva
// ============================================================

const padroesExtracaoMassiva = [
  /\bsem limite\b/i,
  /\bsem limit\b/i,
  /\btodos os registros\b/i,
  /\btodas as linhas\b/i,
  /\btodos os lancamentos\b/i,
  /\btodos os dados\b/i,
  /\btoda a base\b/i,
  /\bbase inteira\b/i,
  /\bretorne tudo\b/i,
  /\bdump\b/i,
  /\bbackup\b/i
];

for (const padrao of padroesExtracaoMassiva) {
  if (padrao.test(perguntaLower)) {
    throw new Error(
      "Solicitação incompatível com as regras de segurança: extração massiva de dados não é permitida."
    );
  }
}

const quantidadeMatch = perguntaLower.match(
  /\b(?:mostre|mostrar|liste|listar|retorne|retornar|traga|exiba|exibir|busque|buscar)\s+(\d+)\s+(?:registros|linhas|lancamentos|itens|dados|contas)\b/i
);

if (quantidadeMatch) {
  const quantidadeSolicitada = Number(quantidadeMatch[1]);

  if (Number.isFinite(quantidadeSolicitada) && quantidadeSolicitada > 100) {
    throw new Error(
      "Solicitação incompatível com as regras de segurança: o limite máximo permitido é 100 registros."
    );
  }
}

// ============================================================
// Retorno
// ============================================================

return [
  {
    json: {
      pergunta,
      pergunta_normalizada: perguntaNormalizada,
      contexto_contabil_permitido: contextoContabilPermitido,
      options: optionsInput,
      body: {
        pergunta,
        options: optionsInput
      }
    }
  }
];

// ============================================================
// CODE - CLASSIFICAR INTENÇÃO DUCKLAKE
// Agente SQL Financeiro v2.0.6.2-comparativo-marcas-fix
// Objetivo:
// Classificar a intenção da pergunta do cliente para orientar
// a geração de SQL DuckDB/DuckLake.
//
// Ajustes v2.0.1:
// - Grupo DRE + orçamento => orcado_vs_realizado
// - Centro de custo + orçamento/estouro/economia => estouro_orcamento ou opex_por_centro_custo
// - Mantém regras de fallback refinadas
//
// Ajustes v2.0.6.2:
// - Detectar comparativo entre marcas antes de OPEX por marca.
// - Reconhecer padrões como: compare X entre Rivatti e Renna.
// - Expor marcas_detectadas para facilitar auditoria.
// ============================================================

const perguntaNode = $('Code - Validar Pergunta').first().json || {};

const pergunta = perguntaNode.pergunta || '';
const perguntaNormalizada = perguntaNode.pergunta_normalizada || '';

const options = perguntaNode.options || perguntaNode.body?.options || {};

const contextoDuckLake = $json;

// Normaliza texto: minúsculo, sem acento e com espaços uniformes
function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

const texto = normalizeText(perguntaNormalizada || pergunta);

const hasAny = (terms) => {
  return terms.some(term => texto.includes(normalizeText(term)));
};

function uniqueArray(arr) {
  return [...new Set((arr || []).filter(Boolean))];
}

function detectMarcas(text) {
  const normalized = normalizeText(text);

  const aliases = [
    { alias: 'rivatti', marca: 'Rivatti' },
    { alias: 'renna', marca: 'Renna' },
    { alias: 'pix iluminacao', marca: 'Pix Iluminação' },
    { alias: 'pix iluminação', marca: 'Pix Iluminação' },
    { alias: 'pix revestimentos', marca: 'Pix Revestimentos' },
    { alias: 'metalfox', marca: 'MetalFox' },
    { alias: 'metal fox', marca: 'MetalFox' },
    { alias: 'monobox', marca: 'Monobox' },
    { alias: 'uv-pro', marca: 'UV-PRO' },
    { alias: 'uv pro', marca: 'UV-PRO' },
    { alias: 'mdl', marca: 'MDL' },
    { alias: 'hk', marca: 'HK' },
    { alias: 'solar', marca: 'Solar' },
    { alias: 'trie', marca: 'Trie' }
  ];

  const found = [];

  for (const item of aliases) {
    const alias = normalizeText(item.alias);

    // Para aliases curtos, evita falso positivo dentro de outras palavras.
    if (alias.length <= 3) {
      const regex = new RegExp(`(^|\\s|[^a-z0-9])${alias}($|\\s|[^a-z0-9])`, 'i');
      if (regex.test(normalized)) {
        found.push(item.marca);
      }
      continue;
    }

    if (normalized.includes(alias)) {
      found.push(item.marca);
    }
  }

  // Se a pergunta falar apenas Pix, sem especificar Iluminação/Revestimentos, registra Pix genérico.
  if (/(^|\s|[^a-z0-9])pix($|\s|[^a-z0-9])/.test(normalized) && !found.some(m => m.startsWith('Pix '))) {
    found.push('Pix');
  }

  return uniqueArray(found);
}

let detectedIntent = 'consulta_geral';
let confidence = 0.5;
let reasons = [];

// ============================================================
// Grupos de termos
// ============================================================

const marcas = [
  'marca',
  'marcas',
  'renna',
  'rivatti',
  'pix',
  'pix iluminacao',
  'pix iluminação',
  'pix revestimentos',
  'pix+',
  'pix +',
  'metalfox',
  'uv-pro',
  'uv pro',
  'monobox',
  'mdl',
  'hk',
  'solar',
  'trie'
];

const termosCentroCusto = [
  'centro de custo',
  'centros de custo',
  'cc',
  'setor',
  'setores',
  'area',
  'areas',
  'área',
  'áreas',
  'departamento',
  'departamentos',
  'gestor',
  'gestores'
];

const termosOpex = [
  'opex',
  'despesa operacional',
  'despesas operacionais',
  'gastos operacionais',
  'gasto operacional',
  'custo operacional',
  'custos operacionais',
  'estrutura',
  'despesas'
];

const termosOrcamento = [
  'orcamento',
  'orçamento',
  'orcado',
  'orçado',
  'orçada',
  'orçadas',
  'orcados',
  'orçados',
  'planejado',
  'planejada',
  'budget',
  'previsto',
  'prevista',
  'previsao',
  'previsão'
];

const termosConsumoOrcamento = [
  'consumiram menos orcamento',
  'consumiram menos orçamento',
  'consumiu menos orcamento',
  'consumiu menos orçamento',
  'consumo de orcamento',
  'consumo de orçamento',
  'menor consumo de orcamento',
  'menor consumo de orçamento',
  'menos consumo de orcamento',
  'menos consumo de orçamento',
  'orcamento consumido',
  'orçamento consumido',
  'percentual consumido',
  'consumiu do orcamento',
  'consumiu do orçamento',
  'consumiram do orcamento',
  'consumiram do orçamento'
];

const termosEstouro = [
  'estouro',
  'estourou',
  'estouraram',
  'acima do orcamento',
  'acima do orçamento',
  'maior gasto',
  'gastou mais',
  'gasto acima',
  'despesa acima',
  'excedeu',
  'ultrapassou',
  'ficaram acima',
  'ficou acima'
];

const termosEconomia = [
  'economia',
  'economizaram',
  'economizou',
  'menor gasto',
  'gastou menos',
  'abaixo do orcamento',
  'abaixo do orçamento',
  'sobrou orçamento',
  'sobrou orcamento',
  'sobra de orçamento',
  'sobra de orcamento',
  'ficaram abaixo',
  'ficou abaixo',
  'menor consumo'
];

const termosOrcadoRealizado = [
  'orcado',
  'orçado',
  'realizado',
  'variacao',
  'variação',
  'variancia',
  'variância',
  'desvio',
  'diferenca',
  'diferença',
  'comparar orcado',
  'comparar orçado',
  'versus realizado',
  'vs realizado',
  'orçado e realizado',
  'orcado e realizado'
];

const termosResultado = [
  'resultado liquido',
  'resultado líquido',
  'resultado por marca',
  'melhor resultado',
  'pior resultado',
  'resultado negativo',
  'resultado percentual',
  'percentual sobre rol',
  'sobre rol',
  'rol',
  'receita liquida',
  'receita líquida',
  'receita operacional liquida',
  'receita operacional líquida'
];

const termosDre = [
  'dre',
  'grupo dre',
  'grupos dre',
  'grupo de dre',
  'grupos de dre',
  'linha dre',
  'linhas dre',
  'linha da dre',
  'linhas da dre',
  'nivel dre',
  'nível dre',
  'grupo contabil',
  'grupo contábil',
  'demonstrativo',
  'resultado do mes',
  'resultado do mês',
  'mensal'
];

const termosImpactoNegativoDre = [
  'impactaram negativamente',
  'impactou negativamente',
  'impacto negativo',
  'impactos negativos',
  'afetaram negativamente',
  'afetou negativamente',
  'pioraram o resultado',
  'piorou o resultado',
  'prejudicaram o resultado',
  'prejudicou o resultado',
  'mais impactaram negativamente',
  'maior impacto negativo',
  'maiores impactos negativos',
  'variação desfavorável',
  'variacao desfavoravel',
  'desvio negativo',
  'desvios negativos'
];

const termosComparacao = [
  'compare',
  'comparar',
  'comparativo',
  'comparacao',
  'comparação',
  'comparando',
  ' versus ',
  ' vs ',
  ' entre ',
  'melhor desempenho',
  'pior desempenho'
];

const termosImpactoSetor = [
  'impacto',
  'representatividade',
  'pesam',
  'pesa',
  'maior custo',
  'maiores custos',
  'mais pesam',
  'representa mais',
  'maior representatividade'
];

// ============================================================
// Flags úteis
// ============================================================

const falaMarca = hasAny(marcas);
const falaCentroCusto = hasAny(termosCentroCusto);
const falaOpex = hasAny(termosOpex);
const falaOrcamento = hasAny(termosOrcamento);
const falaConsumoOrcamento = hasAny(termosConsumoOrcamento);
const falaEstouro = hasAny(termosEstouro);
const falaEconomia = hasAny(termosEconomia);
const falaOrcadoRealizado = hasAny(termosOrcadoRealizado);
const falaResultado = hasAny(termosResultado);
const falaDre = hasAny(termosDre);
const falaImpactoNegativoDre = hasAny(termosImpactoNegativoDre);
const falaComparacao = hasAny(termosComparacao);
const falaImpactoSetor = hasAny(termosImpactoSetor);
const marcasDetectadas = detectMarcas(perguntaNormalizada || pergunta);
const qtdMarcasDetectadas = marcasDetectadas.length;
const falaComparativoEntreMarcas = (falaComparacao || texto.includes(' entre ')) && qtdMarcasDetectadas >= 2;

// ============================================================
// Ordem de classificação
// A ordem é importante:
// 1. Casos específicos primeiro
// 2. Casos genéricos depois
// ============================================================

// 0. Comparativo explícito entre marcas
// Exemplo: "Compare OPEX sobre ROL entre Rivatti e Renna."
// Esta regra precisa vir antes de OPEX por marca para preservar intent_esperada do benchmark.
if (
  falaComparativoEntreMarcas
) {
  detectedIntent = 'comparativo_marcas';
  confidence = 0.97;
  reasons.push(`Pergunta solicita comparação explícita entre marcas detectadas: ${marcasDetectadas.join(', ')}.`);
}

// 1. Orçamento por grupo DRE
// Exemplos:
// "Quais grupos DRE tiveram maior economia frente ao orçamento?"
// "Quais grupos DRE tiveram maior estouro de orçamento?"
// "Mostre a variação entre orçado e realizado por grupo DRE."
else if (
  falaDre &&
  (falaOrcamento || falaOrcadoRealizado || falaEstouro || falaEconomia) &&
  !falaCentroCusto
) {
  detectedIntent = 'orcado_vs_realizado';
  confidence = 0.96;
  reasons.push('Pergunta menciona orçamento/orçado/realizado por grupo DRE. Deve ser classificada como orcado_vs_realizado, não como estouro_orcamento.');
}

// 1. Consumo de orçamento por centro de custo / setor
// Exemplo: "Quais centros de custo consumiram menos orçamento?"
else if (
  falaConsumoOrcamento &&
  falaCentroCusto
) {
  detectedIntent = 'opex_por_centro_custo';
  confidence = 0.95;
  reasons.push('Pergunta menciona consumo de orçamento por centro de custo/setor. Deve comparar OPEX realizado vs OPEX orçado.');
}

// 2. Impacto negativo por grupo DRE
// Exemplo: "Quais grupos DRE mais impactaram negativamente o resultado?"
else if (
  falaDre &&
  falaImpactoNegativoDre
) {
  detectedIntent = 'orcado_vs_realizado';
  confidence = 0.92;
  reasons.push('Pergunta menciona grupos DRE com impacto negativo no resultado. Deve comparar realizado vs orçado por grupo DRE.');
}

// 3. Estouro/economia por centro de custo, setor, área ou gestor
else if (
  (falaEstouro || falaEconomia) &&
  falaOrcamento &&
  falaCentroCusto
) {
  detectedIntent = 'estouro_orcamento';
  confidence = 0.94;
  reasons.push('Pergunta menciona estouro/economia orçamentária por centro de custo, setor, área ou gestor.');
}

// 4. Estouro de orçamento genérico
else if (
  falaEstouro
) {
  detectedIntent = 'estouro_orcamento';
  confidence = 0.93;
  reasons.push('Pergunta menciona estouro orçamentário, gasto acima do planejado ou orçamento excedido.');
}

// 5. Economia frente ao orçamento genérica
else if (
  falaEconomia &&
  falaOrcamento
) {
  detectedIntent = 'estouro_orcamento';
  confidence = 0.88;
  reasons.push('Pergunta menciona economia frente ao orçamento. Usa a mesma família de análise orçado vs realizado/estouro, porém buscando variação favorável.');
}

// 6. Comparativo entre marcas
else if (
  falaComparacao &&
  falaMarca
) {
  detectedIntent = 'comparativo_marcas';
  confidence = 0.9;
  reasons.push('Pergunta solicita comparação entre marcas.');
}

// 7. Impacto de setor/centro de custo por marca
// Exemplo: "Quais setores mais pesam no OPEX da Renna?"
else if (
  falaCentroCusto &&
  falaMarca &&
  (
    falaOpex ||
    falaImpactoSetor
  )
) {
  detectedIntent = 'impacto_setor_marca';
  confidence = 0.92;
  reasons.push('Pergunta menciona setor/área/departamento com impacto, representatividade ou OPEX por marca.');
}

// 8. OPEX por centro de custo / setor
else if (
  falaCentroCusto &&
  (
    falaOpex ||
    falaOrcamento ||
    falaOrcadoRealizado
  )
) {
  detectedIntent = 'opex_por_centro_custo';
  confidence = 0.9;
  reasons.push('Pergunta menciona OPEX, orçamento ou realizado por centro de custo/setor/área/departamento.');
}

// 9. OPEX por marca
else if (
  falaOpex &&
  falaMarca
) {
  detectedIntent = 'opex_por_marca';
  confidence = 0.9;
  reasons.push('Pergunta menciona OPEX/despesa operacional por marca ou sobre ROL.');
}

// 10. Orçado vs realizado geral
else if (
  falaOrcadoRealizado ||
  (
    falaOrcamento &&
    !falaCentroCusto
  )
) {
  detectedIntent = 'orcado_vs_realizado';
  confidence = 0.85;
  reasons.push('Pergunta menciona comparação entre orçado e realizado, variação, desvio ou orçamento.');
}

// 11. DRE mensal
else if (
  falaDre &&
  (
    hasAny(['mes', 'mês', 'mensal']) ||
