      'gi'
    );

    out = out.replace(aliasDefRegex, (match, keyword, objectName) => {
      return `${keyword} ${objectName} ${aliasSeguro}`;
    });

    const aliasRefRegex = new RegExp(`\\b${aliasReservado}\\.`, 'gi');
    out = out.replace(aliasRefRegex, `${aliasSeguro}.`);
  }

  return out;
}

// ============================================================
// Regra determinística v2.0.6.8 — Estouro sem Receita
// ============================================================
// Mantida porque já existia no cleaner e protege uma regra de negócio
// específica do modelo de estouro de orçamento.
// ============================================================

function isModeloEstouroOrcamentoContaContabil() {
  const modelo = String(modeloQueryPlanejado || planoQuery?.modelo_query || '').toLowerCase();
  const intent = String(detectedIntent || '').toLowerCase();

  return (
    modelo === 'estouro_orcamento_conta_contabil' ||
    intent === 'estouro_orcamento_conta_contabil' ||
    (
      intent === 'estouro_orcamento' &&
      modelo.includes('estouro_orcamento')
    )
  );
}

function contemFiltroReceitaExcluida(sqlText) {
  const texto = String(sqlText || '');

  // Normalização apenas para detecção. Não altera a SQL original.
  const compacto = texto
    .replace(/\s+/g, ' ')
    .trim();

  // Aceita:
  // - grupo_dre NOT LIKE '01 -%'
  // - alias.grupo_dre NOT LIKE '01 -%'
  // - COALESCE(...grupo_dre...) NOT LIKE '01 -%'
  // - pc.nivel_1_bi NOT LIKE '01 -%'
  // - NOT (grupo_dre LIKE '01 -%')
  // - NOT (pc.nivel_1_bi LIKE '01 -%')
  // - filtros equivalentes já aplicados no grão de DRE.
  const filtroGrupoDreNotLike =
    /(?:^|[\s(])(?:[a-zA-Z_][a-zA-Z0-9_]*\.)?grupo_dre\s+NOT\s+LIKE\s+'01\s*-\s*%'/i
      .test(compacto);

  const filtroNivel1NotLike =
    /(?:^|[\s(])(?:[a-zA-Z_][a-zA-Z0-9_]*\.)?nivel_1_bi\s+NOT\s+LIKE\s+'01\s*-\s*%'/i
      .test(compacto);

  const filtroCoalesceGrupoDre =
    /COALESCE\s*\([^)]*grupo_dre[^)]*\)\s+NOT\s+LIKE\s+'01\s*-\s*%'/i
      .test(compacto);

  const filtroCoalesceNivel1 =
    /COALESCE\s*\([^)]*nivel_1_bi[^)]*\)\s+NOT\s+LIKE\s+'01\s*-\s*%'/i
      .test(compacto);

  const filtroNotGrupoDreLike =
    /NOT\s*\(\s*(?:[a-zA-Z_][a-zA-Z0-9_]*\.)?grupo_dre\s+LIKE\s+'01\s*-\s*%'\s*\)/i
      .test(compacto);

  const filtroNotNivel1Like =
    /NOT\s*\(\s*(?:[a-zA-Z_][a-zA-Z0-9_]*\.)?nivel_1_bi\s+LIKE\s+'01\s*-\s*%'\s*\)/i
      .test(compacto);

  const filtroGenericoSeguroGrupoDre =
    /grupo_dre[\s\S]{0,160}NOT\s+LIKE\s+'01\s*-\s*%'/i
      .test(compacto);

  const filtroGenericoSeguroNivel1 =
    /nivel_1_bi[\s\S]{0,160}NOT\s+LIKE\s+'01\s*-\s*%'/i
      .test(compacto);

  return (
    filtroGrupoDreNotLike ||
    filtroNivel1NotLike ||
    filtroCoalesceGrupoDre ||
    filtroCoalesceNivel1 ||
    filtroNotGrupoDreLike ||
    filtroNotNivel1Like ||
    filtroGenericoSeguroGrupoDre ||
    filtroGenericoSeguroNivel1
  );
}

function aplicarRegraEstouroSemReceita(sqlText) {
  if (!isModeloEstouroOrcamentoContaContabil()) {
    return sqlText;
  }

  let out = String(sqlText || '');

  // Remove classificação antiga de receita dentro do CASE.
  // Estouro de orçamento não deve classificar Receita abaixo do orçamento
  // como tipo de estouro.
  out = out.replace(
    /\n?\s*WHEN\s+(?:[a-zA-Z_][a-zA-Z0-9_]*\.)?grupo_dre\s+LIKE\s+'01\s*-\s*%'\s+THEN\s+'Receita abaixo do orçamento'\s*/gi,
    '\n'
  );

  if (contemFiltroReceitaExcluida(out)) {
    return out;
  }

  let filtroInserido = false;

  // Caso 1:
  // FROM base_variancias
  // WHERE variancia_rs < 0
  out = out.replace(
    /(\bFROM\s+base_variancias\s+WHERE\s+)(variancia_rs\s*<\s*0)/i,
    (match, prefixo, condicao) => {
      filtroInserido = true;
      return `${prefixo}${condicao}\nAND grupo_dre NOT LIKE '01 -%'`;
    }
  );

  // Caso 2:
  // FROM base_variancias
  // WHERE ...
  if (!filtroInserido) {
    out = out.replace(
      /(\bFROM\s+base_variancias\s+WHERE\s+)/i,
      (match, prefixo) => {
        filtroInserido = true;
        return `${prefixo}grupo_dre NOT LIKE '01 -%'\nAND `;
      }
    );
  }

  // Caso 3:
  // FROM base_variancias
  // sem WHERE no SELECT/CTE seguinte.
  if (!filtroInserido) {
    out = out.replace(
      /(\bFROM\s+base_variancias\b)(?!\s+WHERE\b)/i,
      (match, prefixo) => {
        filtroInserido = true;
        return `${prefixo}\nWHERE grupo_dre NOT LIKE '01 -%'`;
      }
    );
  }

  // Caso 4:
  // FROM calculo_final
  // WHERE variancia_rs < 0
  //
  // Esse é o caso que não era coberto. Quando o Gemini filtra
  // somente no SELECT final a partir de calculo_final, a regra antiga
  // não inseria a exclusão e o cleaner quebrava na validação.
  if (!filtroInserido) {
    out = out.replace(
      /(\bFROM\s+calculo_final\s+WHERE\s+)(variancia_rs\s*<\s*0)/i,
      (match, prefixo, condicao) => {
        filtroInserido = true;
        return `${prefixo}${condicao}\nAND grupo_dre NOT LIKE '01 -%'`;
      }
    );
  }

  // Caso 5:
  // FROM calculo_final
  // WHERE ...
  if (!filtroInserido) {
    out = out.replace(
      /(\bFROM\s+calculo_final\s+WHERE\s+)/i,
      (match, prefixo) => {
        filtroInserido = true;
        return `${prefixo}grupo_dre NOT LIKE '01 -%'\nAND `;
      }
    );
  }

  // Caso 6:
  // SELECT final com WHERE variancia_rs < 0 sem padrão de FROM conhecido.
  // Mantém a correção genérica e deixa o Engine Preflight validar escopo.
  if (!filtroInserido) {
    out = out.replace(
      /(\bWHERE\s+)(variancia_rs\s*<\s*0)/i,
      (match, prefixo, condicao) => {
        filtroInserido = true;
        return `${prefixo}${condicao}\nAND grupo_dre NOT LIKE '01 -%'`;
      }
    );
  }

  return out;
}

function validarRegraEstouroSemReceita(sqlText) {
  if (!isModeloEstouroOrcamentoContaContabil()) {
    return;
  }

  const texto = String(sqlText || '');

  if (/Receita abaixo do orçamento/i.test(texto)) {
    throw new Error(
      'Regra de negócio violada: consulta de estouro de orçamento não pode classificar Receita abaixo do orçamento.'
    );
  }

  if (/WHEN\s+(?:[a-zA-Z_][a-zA-Z0-9_]*\.)?grupo_dre\s+LIKE\s+'01\s*-\s*%'/i.test(texto)) {
    throw new Error(
      "Regra de negócio violada: consulta de estouro de orçamento não pode conter CASE para grupo_dre LIKE '01 -%'."
    );
  }

  if (!contemFiltroReceitaExcluida(texto)) {
    throw new Error(
      "Regra de negócio violada: consulta de estouro de orçamento deve excluir Receita de Vendas com grupo_dre NOT LIKE '01 -%'."
    );
  }

  if (/ranking_no_tipo/i.test(texto) || /PARTITION\s+BY\s+tipo_impacto/i.test(texto)) {
    throw new Error(
      'Regra de negócio violada: consulta de estouro de orçamento deve usar ranking global, sem ranking_no_tipo e sem PARTITION BY tipo_impacto.'
    );
  }
}

sql = normalizarAliasReservado(sql);
sql = aplicarRegraEstouroSemReceita(sql);

// Remove espaços desnecessários por linha
sql = sql
  .split('\n')
  .map(l => l.trim())
  .filter(Boolean)
  .join('\n');

if (!sql) {
  throw new Error('A consulta SQL ficou vazia após a limpeza.');
}

validarRegraEstouroSemReceita(sql);

// ============================================================
// 0. Política de LIMIT SQL
// ============================================================
// O cleaner NÃO adiciona LIMIT.
// O cleaner NÃO exige LIMIT.
// O cleaner apenas identifica se já existe LIMIT na SQL.
// Se existir LIMIT, valida somente limites absurdos de segurança.
// ============================================================

let sqlLower = sql.toLowerCase();

const limitMatches = [
  ...sql.matchAll(/\blimit\s+(\d+)\b/gi)
];

const temLimit = limitMatches.length > 0;

const limitValues = limitMatches
  .map((match) => Number(match[1]))
  .filter((value) => Number.isFinite(value));

const limitFinal = limitValues.length
  ? limitValues[limitValues.length - 1]
  : null;

const limitAdicionadoPeloCleaner = false;

const limiteMaximoSeguranca =
  modeloQueryPlanejado === 'dre_mensal_analitica'
    ? 5000
    : 5000;

// Se a SQL já veio com LIMIT, não removemos aqui.
// Apenas bloqueamos valores absurdos de segurança.
if (temLimit) {
  if (!Number.isFinite(limitFinal) || limitFinal < 1) {
    throw new Error('LIMIT inválido.');
  }

  if (limitFinal > limiteMaximoSeguranca) {
    throw new Error(
      `LIMIT acima do limite máximo de segurança (${limiteMaximoSeguranca}).`
    );
  }
}

// Recalcula depois das validações
sqlLower = sql.toLowerCase();

// ============================================================
// 1. Somente SELECT ou WITH
// ============================================================

if (!sqlLower.startsWith('select') && !sqlLower.startsWith('with')) {
  throw new Error('Somente consultas SELECT ou WITH são permitidas.');
}

// ============================================================
// 2. Bloqueio de múltiplos comandos
// ============================================================

if (sql.includes(';')) {
  throw new Error('Múltiplos comandos SQL não são permitidos.');
}

// ============================================================
// 3. Comandos proibidos
// ============================================================

const comandosProibidos = [
  'insert',
  'update',
  'delete',
  'drop',
  'truncate',
  'alter',
  'create',
  'grant',
  'revoke',
  'comment',
  'vacuum',
  'analyze',
  'execute',
  'call',
  'copy',
  'merge',
  'replace',
  'upsert',
  'refresh',
  'materialized',
  'set',
  'reset',
  'show',
  'describe',
  'explain',
  'attach',
  'detach'
];

for (const comando of comandosProibidos) {
  const regex = new RegExp(`\\b${comando}\\b`, 'i');

  if (regex.test(sql)) {
    throw new Error(`Comando SQL bloqueado por segurança: ${comando}`);
  }
}

// ============================================================
// 4. Termos e objetos proibidos
// ============================================================

const proibidos = [
  'public.',
  'information_schema',
  'pg_catalog',
  'auth.',
  'storage.',
  'vault.',
  'extensions.',
  'supabase_',
  'ai_marca_unidade',
  'vw_',
  'unidade mg',
  'unidade sp',
  'unidade rs',
  '{{ducklake_alias}}'
];

for (const termo of proibidos) {
  if (sqlLower.includes(termo.toLowerCase())) {
    throw new Error(`Objeto, termo ou padrão proibido detectado: ${termo}`);
  }
}

// ============================================================
// 5. Padrão obrigatório de tabela v2.0.2
// ============================================================

if (!sqlLower.includes('dev_lakehouse.main_gold.')) {
  throw new Error('A SQL deve usar o padrão dev_lakehouse.main_gold.nome_tabela.');
}

// ============================================================
// 6. Tabelas Gold permitidas
// ============================================================

const tabelasPermitidas = [
  'gold_lancamentos_contabeis',
  'gold_rateios_lancamentos_contabeis',
  'gold_orcamento',
  'gold_rateios_orcamentos',
  'gold_unidade_negocio',
  'gold_centro_custo',
  'gold_plano_contas',
  'gold_mascaras_demonstrativos'
];

const tables = [
  ...sqlLower.matchAll(/\bdev_lakehouse\.main_gold\.([a-z0-9_]+)/gi)
].map(m => m[1]);

if (tables.length === 0) {
  throw new Error('Nenhuma tabela Gold foi identificada na SQL.');
}

const tabelasUnicas = [...new Set(tables)];

for (const tabela of tabelasUnicas) {
  if (!tabelasPermitidas.includes(tabela)) {
    throw new Error(`Tabela não autorizada ou desconhecida: ${tabela}`);
  }
}

// ============================================================
// 7. Divisão segura
// ============================================================

const pareceTerDivisao = /\/\s*[a-z0-9_\(\.]/i.test(sql);

if (pareceTerDivisao && !sqlLower.includes('nullif')) {
  throw new Error('A SQL contém divisão, mas não usa NULLIF para evitar divisão por zero.');
}

// ============================================================
// 8. Retorno
// ============================================================

return [
  {
    json: {
      ...respostaGemini,

      options: respostaGemini.options || promptNode.options || planoNode.options || {},
      cache: respostaGemini.cache || promptNode.cache || planoNode.cache || {
