      rules_version: respostaGemini.rules_version || promptNode.rules_version || planoNode.rules_version,
      schema_version_cache: respostaGemini.schema_version_cache || promptNode.schema_version_cache || planoNode.schema_version_cache || promptNode.schema_version || planoNode.schema_version,
      prompt_version: respostaGemini.prompt_version || promptNode.prompt_version || planoNode.prompt_version,
      validation_version: respostaGemini.validation_version || promptNode.validation_version || planoNode.validation_version,

      sql,
      cleaned_sql: sql,

      tables_used: tabelasUnicas,

      detected_intent: detectedIntent,
