      plano_query: planoQuery,

      limit_final: limitFinal,
      limit_planejado: null,
      limit_adicionado_pelo_cleaner: limitAdicionadoPeloCleaner,
      limit_policy: 'cleaner_does_not_add_or_require_limit',
      limit_source: temLimit ? 'generated_sql' : 'none',

      regra_estouro_sem_receita_aplicada: isModeloEstouroOrcamentoContaContabil(),
