];

// ============================================================
// CODE - VALIDAR SQL DUCKLAKE OFFLINE
// Agente SQL Financeiro DuckLake
// v2.2.34-clean-validation-preflight-payload-safe
//
// Papel deste node:
// - Security Gate: bloquear apenas riscos claros antes de qualquer chamada ao motor.
// - Contract Gate: validar aderência mínima ao plano/pergunta.
// - NÃO exigir LIMIT.
// - NÃO adicionar LIMIT.
// - NÃO usar limite de interface/PDF/Markdown/CSV como regra SQL.
// - NÃO tentar fazer bind de colunas/aliases.
// - NÃO tentar ser parser SQL.
// - Erros técnicos de compilação devem ser detectados pelo Engine Preflight Watson.
//
// Correção v2.2.34:
// - Sanitiza campos auxiliares antes do preflight.
// - Não repassa parâmetros técnicos indevidos como top-level para tool/motor.
// - Mantém SQL canônico em sql, cleaned_sql e sql_tentativa.
// - Cria engine_preflight_payload com SOMENTE { sql }.
// - Correção genérica: independente de cliente, pergunta, benchmark ou marca.
// ============================================================

let input = {};
let sql = '';
let validationErrors = [];
let validationWarnings = [];

function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function compactSql(value) {
  return String(value || '')
    .replace(/```sql/gi, '')
    .replace(/```/g, '')
    .replace(/;\s*$/g, '')
    .trim();
}

function pushError(code, message, details = {}, category = 'contract') {
  validationErrors.push({ code, message, details, category });
}

function pushWarning(code, message, details = {}) {
  validationWarnings.push({ code, message, details });
}

function uniqueArray(values) {
  return [...new Set((values || []).filter(Boolean))];
}

function getSql(data) {
  return compactSql(
    data.sql_tentativa ||
    data.cleaned_sql ||
    data.sql ||
    data.sql_query ||
    data.query ||
    data.candidates?.[0]?.content?.parts?.[0]?.text ||
    ''
  );
}

function sanitizeTopLevelForEngine(data) {
  const sanitized = { ...(data || {}) };

  // Campos auxiliares de workflow que não devem ser enviados como parâmetros
  // para uma tool/motor SQL com contrato estrito.
  delete sanitized.limit;
  delete sanitized.sql_query;
  delete sanitized.sqlQuery;
  delete sanitized.query_limit;
  delete sanitized.sql_limit;
  delete sanitized.max_rows;
  delete sanitized.row_limit;
  delete sanitized.preview_limit;
  delete sanitized.interface_limit;
  delete sanitized.pdf_limit;
  delete sanitized.markdown_limit;
  delete sanitized.csv_limit;
  delete sanitized.table_limit;

  return sanitized;
}

function extractReferencedTables(sqlText) {
  const tables = [];
  const re = /\b(?:from|join)\s+([`"a-zA-Z0-9_\.\-]+)/gi;

  let match;

  while ((match = re.exec(sqlText)) !== null) {
    const raw = String(match[1] || '')
      .replace(/[`"]/g, '')
      .trim();

    if (!raw || raw === '(') continue;

    tables.push(raw);
  }

  return uniqueArray(tables);
}

function classifyTableRef(tableName) {
  const t = String(tableName || '')
    .replace(/[`"]/g, '')
    .trim();

  if (!t) {
    return {
      kind: 'empty',
      allowed: true
    };
  }

  // CTEs e aliases normalmente não possuem ponto.
  // Esses nomes não são tabelas físicas.
  if (!t.includes('.')) {
    return {
      kind: 'cte_or_alias',
      allowed: true
    };
  }

  const allowedPrefix = 'dev_lakehouse.main_gold.';

  if (!t.startsWith(allowedPrefix)) {
    return {
      kind: 'physical_table',
      allowed: false,
      reason: 'Tabela física fora do schema autorizado.',
      expected_prefix: allowedPrefix,
      table: t
    };
  }

  const allowedTables = new Set([
    'dev_lakehouse.main_gold.gold_lancamentos_contabeis',
    'dev_lakehouse.main_gold.gold_rateios_lancamentos_contabeis',
    'dev_lakehouse.main_gold.gold_orcamento',
    'dev_lakehouse.main_gold.gold_rateios_orcamentos',
    'dev_lakehouse.main_gold.gold_plano_contas',
    'dev_lakehouse.main_gold.gold_centro_custo',
    'dev_lakehouse.main_gold.gold_unidade_negocio',
    'dev_lakehouse.main_gold.gold_mascaras_demonstrativos'
  ]);

  if (!allowedTables.has(t)) {
    return {
      kind: 'physical_table',
      allowed: false,
      reason: 'Tabela física não está na lista de tabelas Gold permitidas para a POC.',
      table: t
    };
  }

  return {
    kind: 'physical_table',
    allowed: true
  };
}

function hasExplicitTopN(value) {
  const text = normalizeText(value);

  return (
    /\btop\s+\d+\b/.test(text) ||
    /\bprimeir[oa]s?\s+\d+\b/.test(text) ||
    /\b\d+\s+(maiores|menores|melhores|piores|principais)\b/.test(text) ||
    /\bmaiores\s+\d+\b/.test(text) ||
    /\bmenores\s+\d+\b/.test(text) ||
    /\bmelhores\s+\d+\b/.test(text) ||
    /\bpiores\s+\d+\b/.test(text)
  );
}

try {
  input = $json || {};
  sql = getSql(input);

  const safeInput = sanitizeTopLevelForEngine(input);

  const sqlLower = normalizeText(sql);

  const pergunta = String(
    input.pergunta ||
    input.question ||
    input.pergunta_original ||
    input.question_original ||
    ''
  ).trim();

  const perguntaNorm = normalizeText(
    input.pergunta_normalizada ||
    input.question_normalized ||
    pergunta
  );

  const detectedIntent = normalizeText(
    input.detected_intent ||
    input.intencao ||
    input.intent ||
    ''
  );

  // ------------------------------------------------------------
  // 1. Security Gate: bloqueios objetivos e não negociáveis.
  // ------------------------------------------------------------

  if (!sql) {
    pushError(
      'SQL_AUSENTE',
      'A SQL está vazia após limpeza.',
      {},
      'security'
    );
  }

  if (sql && !/^\s*(with|select)\b/i.test(sql)) {
    pushError(
      'SQL_DEVE_INICIAR_COM_SELECT_OU_WITH',
      'A SQL precisa iniciar com SELECT ou WITH.',
      {},
      'security'
    );
  }

  const forbidden = [
    'insert',
    'update',
    'delete',
    'drop',
    'alter',
    'truncate',
    'merge',
    'create',
    'grant',
    'revoke',
    'vacuum',
    'copy',
    'call',
    'execute'
  ];

  for (const word of forbidden) {
    const re = new RegExp('\\b' + word + '\\b', 'i');

    if (re.test(sql)) {
      pushError(
        'COMANDO_SQL_PROIBIDO',
        `Comando proibido encontrado: ${word.toUpperCase()}.`,
        { comando: word.toUpperCase() },
        'security'
      );
    }
  }

  if (/\{\{|\}\}|<\s*sql|<\s*query|todo|placeholder/i.test(sql)) {
    pushError(
      'PLACEHOLDER_NAO_RESOLVIDO',
      'A SQL contém placeholder ou marcação não resolvida.',
      {},
      'security'
    );
  }

  // ------------------------------------------------------------
  // 1.1. Política de LIMIT
  // ------------------------------------------------------------
  // Ausência de LIMIT NÃO é erro.
  // Este gate não adiciona LIMIT e não exige LIMIT.
  // Se a SQL já vier com LIMIT, validamos apenas valor absurdo/risco.
  // Limite de interface/PDF/CSV/Markdown não pertence à SQL.
  // ------------------------------------------------------------

  const limitMatches = [
    ...sql.matchAll(/\blimit\s+(\d+)\b/gi)
  ].map((m) => Number(m[1]));

  if (limitMatches.length > 0) {
    const finalLimit = limitMatches[limitMatches.length - 1];

    if (!Number.isFinite(finalLimit) || finalLimit < 1) {
      pushError(
        'LIMIT_INVALIDO',
        'O LIMIT informado na SQL é inválido.',
        { limit: finalLimit },
        'security'
      );
    }

    if (finalLimit > 5000) {
      pushError(
        'LIMIT_ACIMA_DO_LIMITE_SEGURANCA',
        'O LIMIT informado na SQL está acima do limite máximo de segurança.',
        {
          limit: finalLimit,
          limite_maximo_seguranca: 5000
        },
        'security'
      );
    }

    pushWarning(
      'LIMIT_PRESENTE_NA_SQL',
      'A SQL contém LIMIT explícito. Isso é permitido apenas quando fizer sentido semanticamente, por exemplo Top N solicitado pelo usuário.',
      {
        limit: finalLimit,
        explicit_top_n_detected: hasExplicitTopN(perguntaNorm)
      }
    );
  } else {
    pushWarning(
      'SQL_SEM_LIMIT_EXPLICITO',
      'A SQL não contém LIMIT explícito. Isso é permitido; limites de visualização devem ser tratados pela interface/PDF/CSV/Markdown.',
      {
        limit_required: false
      }
    );
  }

  const tables = extractReferencedTables(sql);
  const tableDiagnostics = tables.map((table) => classifyTableRef(table));

  for (const diag of tableDiagnostics) {
    if (!diag.allowed) {
      pushError(
        'TABELA_NAO_AUTORIZADA',
        diag.reason || 'Tabela não autorizada.',
        diag,
        'security'
      );
    }
  }

  // ------------------------------------------------------------
  // 2. Contract Gate: aderência mínima à intenção/plano.
  // Este gate não valida colunas/aliases. Isso fica para o preflight.
  // ------------------------------------------------------------

  const asksConta =
    /\bconta(s)?\b|contabil/.test(perguntaNorm);

  if (
    asksConta &&
    !/\b(nk_conta_contabil|conta_contabil|nivel_2_bi)\b/i.test(sql)
  ) {
    pushError(
      'DIMENSAO_CONTA_AUSENTE',
      'A pergunta pede análise por conta, mas a SQL não expõe dimensão de conta.',
      { pergunta },
      'contract'
    );
  }

  const asksBudget =
    /orcamento|orcado|orcada|budget/.test(`${perguntaNorm} ${detectedIntent}`);

  const asksRealized =
    /realizado|comparad|versus|vs|variacao/.test(`${perguntaNorm} ${detectedIntent}`);

  if (asksBudget && asksRealized) {
    const required = [
      'realizado_rs',
      'orcado_rs',
      'variancia_rs'
    ];

    const missing = required.filter((token) => !sqlLower.includes(token));

    if (missing.length > 0) {
      pushError(
        'METRICAS_COMPARATIVAS_AUSENTES',
        'A pergunta pede comparação orçamento/realizado, mas a SQL não expõe todas as métricas mínimas.',
        {
          missing,
          required
        },
        'contract'
      );
    }
  }

  const asksPreviousPeriod =
    /2025|ano anterior|periodo anterior|periodo passado|mes anterior/.test(perguntaNorm);

  if (
    asksPreviousPeriod &&
    !/(realizado_anterior|anterior_rs|2025)/i.test(sql)
  ) {
    pushError(
      'COMPARACAO_PERIODO_ANTERIOR_AUSENTE',
      'A pergunta pede comparação com período anterior, mas a SQL não apresenta métrica/período anterior.',
      { pergunta },
      'contract'
    );
  }

  const asksDualRanking =
    /maiores?.*menores?|menores?.*maiores?|top.*bottom|melhores?.*piores?|piores?.*melhores?/.test(perguntaNorm);

  if (asksDualRanking) {
    const hasDualRank =
      /ranking_maiores/i.test(sql) &&
      /ranking_menores/i.test(sql);

    const hasTipoRanking =
      /tipo_ranking/i.test(sql);

    if (!hasDualRank && !hasTipoRanking) {
      pushError(
        'DUAL_RANKING_AUSENTE',
        'A pergunta pede maiores e menores, mas a SQL não expõe ranking dual ou tipo_ranking.',
        { asksDualRanking: true },
        'contract'
      );
    }

    if (
      /\bunion\s+all\b[\s\S]*\border\s+by\b/i.test(sql) &&
      /tipo_ranking/i.test(sql)
    ) {
      pushWarning(
        'DUAL_RANKING_COM_UNION_ALL_DE_APRESENTACAO',
        'A SQL usa UNION ALL com tipo_ranking. O padrão preferencial é saída única com ranking_maiores/ranking_menores.',
        {}
      );
    }
  }

  // Token de grupo numérico explicitamente citado na pergunta, ex.: "09 - ...".
  // Regra genérica: se a pergunta cita um código DRE literal, a SQL deve conter esse código.
  const dreCodeMatch = pergunta.match(/\b(\d{2})\s*-/);

  if (dreCodeMatch) {
    const code = dreCodeMatch[1];

    if (!new RegExp(`['"]?${code}\\s*-`).test(sql)) {
      pushError(
        'FILTRO_DRE_EXPLICITO_AUSENTE',
        'A pergunta cita um grupo DRE explícito, mas esse código não aparece na SQL.',
        { dre_code: code },
        'contract'
      );
    }
  }

  const normalizedContractDetected =
    /\bfatos_normalizados\b/i.test(sql) &&
    /\btipo_metrica\b/i.test(sql) &&
    /\bsum\s*\(\s*case\s+when\s+tipo_metrica\b/i.test(sql);

  if (normalizedContractDetected) {
    pushWarning(
      'CONTRATO_FATOS_NORMALIZADOS_DETECTADO',
      'A SQL usa o contrato fatos_normalizados + agregação condicional.',
      { normalized_contract_detected: true }
    );
  }

  // ------------------------------------------------------------
  // 3. Resultado do gate
  // ------------------------------------------------------------

  const success = validationErrors.length === 0;

  const codes = uniqueArray(
    validationErrors.map((err) => err.code || 'VALIDATION_ERROR_SEM_CODIGO')
  );

  const securityErrors = validationErrors.filter((err) => err.category === 'security');
  const contractErrors = validationErrors.filter((err) => err.category === 'contract');

  return [
    {
      json: {
        ...safeInput,

        sql,
        cleaned_sql: sql,
        sql_tentativa: sql,

        engine_preflight_payload: {
          sql
        },

        success,
        is_valid: success,
        sql_aprovada: success,

        validation_status: success
          ? 'aprovado_security_contract_pending_preflight'
          : 'reprovado',

        validation_stage: 'security_contract_gate',
        validation_errors: validationErrors,
        validation_warnings: validationWarnings,
        validation_error_codes: codes,
        first_validation_error: validationErrors[0] || null,

        security_gate: {
          status: securityErrors.length === 0 ? 'aprovado' : 'reprovado',
          errors: securityErrors
        },

        contract_gate: {
          status: contractErrors.length === 0 ? 'aprovado' : 'reprovado',
          errors: contractErrors,
          normalized_fact_contract_detected: normalizedContractDetected
        },

        engine_preflight_required: success,

        status_operacional: success
          ? 'sql_aprovada_security_contract_aguardando_preflight'
          : 'erro_security_contract_gate',

        observacao: success
          ? 'Security Gate e Contract Gate aprovados. A aprovação final depende do Engine Preflight.'
          : 'A SQL não passou no Security/Contract Gate. O erro deve seguir para loop de reparo ou fallback conforme política.',

        validator_version: 'v2.2.34-clean-validation-preflight-payload-safe',
        limit_policy: 'limit_nao_obrigatorio_interface_controla_visualizacao',
        preflight_payload_policy: 'engine_preflight_payload_contem_somente_sql'
      }
    }
  ];
} catch (error) {
  const err = {
    code: 'VALIDADOR_SQL_EXCEPTION_NO_THROW',
    message: 'A exceção foi convertida em payload normal para permitir roteamento pelo loop de reparo.',
    details: {
      error_message: error?.message || String(error),
      error_stack: error?.stack || null
    },
    category: 'validator_exception'
  };

  const safeInput = sanitizeTopLevelForEngine(input || {});

  return [
    {
      json: {
        ...safeInput,

        sql,
        cleaned_sql: sql,
        sql_tentativa: sql,

        engine_preflight_payload: {
          sql
        },

        success: false,
        is_valid: false,
        sql_aprovada: false,

        validation_status: 'erro',
        validation_stage: 'security_contract_gate',
        validation_errors: [err],
        validation_warnings: validationWarnings,
        validation_error_codes: [err.code],
        first_validation_error: err,

        security_gate: {
          status: 'erro',
          errors: [err]
        },

        contract_gate: {
          status: 'nao_avaliado',
          errors: []
        },

        engine_preflight_required: false,
        status_operacional: 'erro_exception_validador_sql',
        observacao: 'O validador offline encontrou exceção interna; o erro foi convertido em payload estruturado.',

        validator_version: 'v2.2.34-clean-validation-preflight-payload-safe',
        limit_policy: 'limit_nao_obrigatorio_interface_controla_visualizacao',
        preflight_payload_policy: 'engine_preflight_payload_contem_somente_sql'
      }
    }
  ];
}

// ============================================================
// CODE - RESPOSTA ERRO SQL DUCKLAKE
// Agente SQL Financeiro DuckLake
// v2.2.27-generic-preflight-error-repair-routing
//
// Objetivo:
// - Não alterar SQL, prompt, planner, repair ou regras de negócio.
// - Consolidar o diagnóstico real de validação em uma resposta final.
// - Expor validation_errors, validation_error_codes, repair status,
//   node provável de origem e rastreio dos nodes relevantes.
// - Evitar novo ciclo de correção por hipótese sem saber o erro real.
// ============================================================

const input = $json || {};

function getFromNode(nodeName) {
  try {
    return $(nodeName).first().json || {};
  } catch (e) {
    return {};
  }
}

function isPlainObject(value) {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

function tryParseJson(value) {
  if (typeof value !== 'string') return null;
  const text = value.trim();
  if (!text || (!text.startsWith('{') && !text.startsWith('['))) return null;
  try {
    return JSON.parse(text);
  } catch (e) {
    return null;
  }
}

function toArray(value) {
  if (!value) return [];
  if (Array.isArray(value)) return value;
  if (typeof value === 'string') {
    const parsed = tryParseJson(value);
    return Array.isArray(parsed) ? parsed : [];
  }
  return [];
}

function toObject(value) {
  if (isPlainObject(value)) return value;
  if (typeof value === 'string') {
    const parsed = tryParseJson(value);
    return isPlainObject(parsed) ? parsed : {};
  }
  return {};
}

function uniqueArray(values) {
  return [...new Set((values || []).filter((v) => v !== undefined && v !== null && v !== ''))];
}

function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function compactSql(value) {
  return String(value || '')
    .replace(/```sql/gi, '')
    .replace(/```/g, '')
    .replace(/;\s*$/g, '')
    .trim();
}

function getSqlCandidate(...sources) {
  for (const source of sources) {
    if (!source) continue;
    const sql =
      source.sql_tentativa ||
      source.cleaned_sql ||
      source.sql ||
      source.query ||
      source.sql_original_reprovada ||
      source.candidates?.[0]?.content?.parts?.[0]?.text ||
      '';
    if (String(sql || '').trim()) return compactSql(sql);
  }
  return '';
}

function getRawErrorObject(value) {
  if (!value) return {};
  if (isPlainObject(value.error)) return value.error;
  if (isPlainObject(value.cause)) return value.cause;
  if (isPlainObject(value.executionError)) return value.executionError;
  if (isPlainObject(value)) return value;
  return {};
}

function extractMessage(value) {
  if (!value) return '';
  if (typeof value === 'string') return value;
  if (isPlainObject(value)) {
    return String(
      value.message ||
      value.error_message ||
      value.errorMessage ||
      value.description ||
      value.error ||
      value.cause?.message ||
      ''
    );
  }
  return String(value || '');
}

function extractParsedErrorPayload(...sources) {
  for (const source of sources) {
    if (!source) continue;
    if (isPlainObject(source) && Array.isArray(source.validation_errors)) return source;
    const candidates = [
      source.message,
      source.error_message,
      source.errorMessage,
      source.detalhe,
      source.resposta,
      source.error?.message,
      source.cause?.message
    ];
    for (const candidate of candidates) {
      const parsed = tryParseJson(candidate);
      if (parsed) return parsed;
    }
  }
  return {};
}

function collectValidationErrors(...sources) {
  const errors = [];
  for (const source of sources) {
    if (!source) continue;
    errors.push(...toArray(source.validation_errors));
    errors.push(...toArray(source.validacao_offline?.errors));
    errors.push(...toArray(source.sql_repair?.validation_errors));
    errors.push(...toArray(source.original_validation_errors));
    errors.push(...toArray(source.diagnostico_validacao?.validation_errors));
  }

  // Deduplica por code + message + details.
  const seen = new Set();
  const out = [];
  for (const err of errors) {
    const normalized = isPlainObject(err)
      ? {
          code: err.code || err.error_code || 'VALIDATION_ERROR_SEM_CODIGO',
          message: err.message || err.error_message || String(err.error || 'Erro de validação sem mensagem.'),
          details: err.details || err.detalhes || null
        }
      : {
          code: 'VALIDATION_ERROR_TEXTO',
          message: String(err),
          details: null
        };
    const key = JSON.stringify(normalized);
    if (!seen.has(key)) {
      seen.add(key);
      out.push(normalized);
    }
  }
  return out;
}

function collectValidationWarnings(...sources) {
  const warnings = [];
  for (const source of sources) {
    if (!source) continue;
    warnings.push(...toArray(source.validation_warnings));
    warnings.push(...toArray(source.validacao_offline?.warnings));
    warnings.push(...toArray(source.sql_repair?.validation_warnings));
    warnings.push(...toArray(source.original_validation_warnings));
  }
  return warnings;
}

function summarizeNode(nodeName, nodeJson) {
  const errors = collectValidationErrors(nodeJson);
  const warnings = collectValidationWarnings(nodeJson);
  return {
    node: nodeName,
    has_output: Boolean(nodeJson && Object.keys(nodeJson).length),
    success: nodeJson.success ?? nodeJson.is_valid ?? nodeJson.sql_aprovada ?? null,
    validation_status: nodeJson.validation_status || nodeJson.validacao_offline?.status || null,
    status_operacional: nodeJson.status_operacional || null,
    error_codes: uniqueArray(errors.map((e) => e.code)),
    error_count: errors.length,
    warning_count: warnings.length,
    repair_should_run: nodeJson.deve_reparar_sql ?? nodeJson.sql_repair?.should_repair ?? null,
    repair_attempt: nodeJson.sql_repair_attempt ?? nodeJson.sql_repair?.attempt ?? null,
    repair_no_structural_change: nodeJson.sql_repair_no_structural_change ?? nodeJson.sql_repair?.repair_no_structural_change ?? null
  };
}

// ============================================================
// Nodes relevantes para diagnóstico
// ============================================================

const perguntaNode = getFromNode('Code - Validar Pergunta');
const intentNode = getFromNode('Code - Classificar Intenção DuckLake');
const planoNode = getFromNode('Code - Montar Plano Query DuckLake');
const promptNode = getFromNode('Code - Montar Prompt SQL DuckLake Offline');
const limparNode = getFromNode('Code - Limpar SQL DuckLake');
const validarNode = getFromNode('Code - Validar SQL DuckLake Offline');
const avaliarReparoNode = getFromNode('Code - Avaliar Reparo SQL');
const montarBodyReparoNode = getFromNode('Code - Montar Body Reparo SQL');
const prepararReparoNode = getFromNode('Code - Preparar SQL Reparada Para Cleaner');

const rawErrorObject = getRawErrorObject(input);
const parsedErrorPayload = extractParsedErrorPayload(input, rawErrorObject, validarNode, avaliarReparoNode, montarBodyReparoNode, prepararReparoNode);

const validationErrors = collectValidationErrors(
  input,
  parsedErrorPayload,
  validarNode,
  avaliarReparoNode,
  montarBodyReparoNode,
  prepararReparoNode
);

const validationWarnings = collectValidationWarnings(
  input,
  parsedErrorPayload,
  validarNode,
  avaliarReparoNode,
  montarBodyReparoNode,
  prepararReparoNode
);

const validationErrorCodes = uniqueArray(validationErrors.map((e) => e.code));
const firstValidationError = validationErrors[0] || null;

const pergunta =
  parsedErrorPayload.pergunta ||
  input.pergunta ||
  perguntaNode.pergunta ||
  promptNode.pergunta ||
  planoNode.pergunta ||
  '';

const perguntaNormalizada =
  input.pergunta_normalizada ||
  perguntaNode.pergunta_normalizada ||
  promptNode.pergunta_normalizada ||
  planoNode.pergunta_normalizada ||
  normalizeText(pergunta);

const intencaoDetectada =
  input.detected_intent ||
  input.intencao_detectada ||
  input.intencao ||
  intentNode.detected_intent ||
  promptNode.detected_intent ||
  planoNode.detected_intent ||
  null;

const planoQuery =
  input.plano_query ||
  parsedErrorPayload.plano_query ||
  limparNode.plano_query ||
  promptNode.plano_query ||
  planoNode.plano_query ||
  null;

const modeloQueryPlanejado =
  input.modelo_query_planejado ||
  input.modelo_query ||
  planoQuery?.modelo_query ||
  planoNode.modelo_query_planejado ||
  planoNode.modelo_query ||
  null;

const planoQueryResumo =
  input.plano_query_resumo ||
  parsedErrorPayload.plano_query_resumo ||
  {
    modelo_query: planoQuery?.modelo_query || null,
    subtipo: planoQuery?.subtipo || null,
    estrategia_comparativa: planoQuery?.estrategia_comparativa || null,
    ranking_strategy: planoQuery?.ranking_strategy || null,
    modelo_saida_ranking: planoQuery?.modelo_saida_ranking || null,
    grain_contract: planoQuery?.grain_contract || null,
    normalized_fact_contract: planoQuery?.normalized_fact_contract || null,
    granularidade: planoQuery?.granularidade || null,
    dimensoes: planoQuery?.dimensoes || null,
    metricas: planoQuery?.metricas || null,
    sql_limit_planejado: null
  };

const sqlTentativa = getSqlCandidate(input, prepararReparoNode, avaliarReparoNode, validarNode, limparNode);
const sqlOriginalReprovada =
  input.sql_original_reprovada ||
  prepararReparoNode.sql_original_reprovada ||
  avaliarReparoNode.sql_original_reprovada ||
  null;

const repairInfo = {
  attempted: Boolean(
    input.sql_repair_applied ||
    prepararReparoNode.sql_repair_applied ||
    avaliarReparoNode.sql_repair?.attempt ||
    input.sql_repair_attempt
  ),
  applied: input.sql_repair_applied ?? prepararReparoNode.sql_repair_applied ?? false,
  source: input.sql_repair_source || prepararReparoNode.sql_repair_source || null,
  attempt: input.sql_repair_attempt ?? prepararReparoNode.sql_repair_attempt ?? avaliarReparoNode.sql_repair_attempt ?? null,
  max_attempts: input.sql_repair_max_attempts ?? avaliarReparoNode.sql_repair_max_attempts ?? null,
  should_repair: input.deve_reparar_sql ?? avaliarReparoNode.deve_reparar_sql ?? avaliarReparoNode.sql_repair?.should_repair ?? null,
  no_structural_change:
    input.sql_repair_no_structural_change ??
    prepararReparoNode.sql_repair_no_structural_change ??
    avaliarReparoNode.sql_repair?.repair_no_structural_change ??
    false,
  no_structural_change_reason:
    input.sql_repair_no_structural_change_reason ||
    prepararReparoNode.sql_repair_no_structural_change_reason ||
    null,
  deterministic_fix_applied:
    input.sql_repair_deterministic_fix_applied ??
    prepararReparoNode.sql_repair_deterministic_fix_applied ??
    false,
  deterministic_fixes:
    input.sql_repair_deterministic_fixes ||
    prepararReparoNode.sql_repair_deterministic_fixes ||
    []
};

const trace = [
  summarizeNode('Code - Validar SQL DuckLake Offline', validarNode),
  summarizeNode('Code - Avaliar Reparo SQL', avaliarReparoNode),
  summarizeNode('Code - Montar Body Reparo SQL', montarBodyReparoNode),
  summarizeNode('Code - Preparar SQL Reparada Para Cleaner', prepararReparoNode),
  summarizeNode('Entrada atual do node de erro', input)
];

const rawErrorMessage =
  extractMessage(rawErrorObject) ||
  extractMessage(input) ||
  firstValidationError?.message ||
  'Erro de validação SQL não identificado.';

let diagnostico = 'erro_validacao_sql_nao_classificado';

if (repairInfo.no_structural_change) {
  diagnostico = 'repair_sem_alteracao_estrutural';
} else if (validationErrorCodes.includes('VALIDADOR_SQL_EXCEPTION_NO_THROW')) {
  diagnostico = 'excecao_no_validador_convertida_em_payload';
} else if (validationErrorCodes.includes('SQL_COMPOUND_ORDER_BY_COLUNA_FORA_DO_SELECT')) {
  diagnostico = 'order_by_composto_com_coluna_fora_do_select';
} else if (validationErrorCodes.includes('FACT_UNION_ALL_JOIN_SEM_AGREGACAO_PREVIA')) {
  diagnostico = 'join_entre_fatos_sem_agregacao_previa';
} else if (validationErrorCodes.includes('COLUNA_INEXISTENTE_NO_SCHEMA_REAL')) {
  diagnostico = 'coluna_inexistente_no_schema_real';
} else if (validationErrorCodes.length) {
  diagnostico = `erro_validacao_${normalizeText(validationErrorCodes[0]).replace(/[^a-z0-9]+/g, '_')}`;
}

const validationStatus =
  input.validation_status ||
  validarNode.validation_status ||
  parsedErrorPayload.validation_status ||
  (validationErrors.length ? 'reprovado' : 'erro_sem_validation_errors');

return [
  {
    json: {
      success: false,

      tipo_entrega: 'erro_validacao_sql_ducklake',
      agent_version: 'v2.2.27-generic-preflight-error-repair-routing',
      agent_version_base: 'v2.2.23-normalized-fact-contract',
      modo_entrega: 'watson_orchestration_copy_paste',

      pergunta,
      pergunta_normalizada: perguntaNormalizada,

      intencao: intencaoDetectada,
      intencao_detectada: intencaoDetectada,

      modelo_query_planejado: modeloQueryPlanejado,
      plano_query_resumo: planoQueryResumo,

      resposta: 'Não foi possível aprovar a query DuckLake gerada.',
      detalhe:
        firstValidationError?.message ||
        rawErrorMessage ||
        'A query foi reprovada, mas nenhum validation_error estruturado foi encontrado.',

      error_node:
        rawErrorObject.node?.name ||
        rawErrorObject.nodeName ||
        input.error_node ||
        'diagnostico_consolidado',
      error_message: rawErrorMessage,
      error_description:
        rawErrorObject.description ||
        rawErrorObject.cause?.description ||
        input.error_description ||
        null,

      diagnostico,

      validation_status: validationStatus,
      validation_errors: validationErrors,
      validation_warnings: validationWarnings,
      validation_error_codes: validationErrorCodes,
      first_validation_error: firstValidationError,

      validacao_offline: {
        status: validationStatus,
        errors: validationErrors,
        warnings: validationWarnings,
        error_codes: validationErrorCodes,
        first_error: firstValidationError
      },

      repair_diagnostics: repairInfo,
      validation_diagnostic_trace: trace,

      sql: sqlTentativa,
      sql_tentativa: sqlTentativa,
      sql_original_reprovada: sqlOriginalReprovada,
      sql_reparada_preview: input.sql_reparada_preview || prepararReparoNode.sql_reparada_preview || null,

      usa_dev_lakehouse: /\bdev_lakehouse\.main_gold\./i.test(sqlTentativa),
      usa_placeholder: /\{\{\s*ducklake_alias\s*\}\}/i.test(sqlTentativa),
      normalizacoes_aplicadas:
        input.normalizacoes_aplicadas ||
