// ============================================================
// CODE - MONTAR PLANO QUERY DUCKLAKE
// Agente SQL Financeiro DuckLake
// v2.2.32-planner-sem-limit-sql-padrao-interface-controla
//
// Objetivo:
// - Montar plano_query para orientar a geração SQL.
// - Não gerar SQL fixa.
// - Não reconhecer perguntas por texto literal.
// - Usar contexto dinâmico carregado do Postgres:
//   regras, catálogo, padrões SQL, aliases e mapeamento DRE.
// - Preservar arquitetura:
//   fatos_normalizados -> agregação condicional -> cálculos -> ranking.
// - Não enviar limit nem operational_limit para geração SQL por padrão.
// ============================================================

const input = $json || {};

// ============================================================
// Helpers gerais
// ============================================================

function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function uniqueArray(values) {
  return [...new Set((values || []).filter(Boolean))];
}

function toArray(value) {
  if (!value) return [];

  if (Array.isArray(value)) {
    return value;
  }

  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [];
    } catch (error) {
      return [];
    }
  }

  return [];
}

function toObject(value) {
  if (!value) return {};

  if (typeof value === 'object' && !Array.isArray(value)) {
    return value;
  }

  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      return parsed && typeof parsed === 'object' && !Array.isArray(parsed)
        ? parsed
        : {};
    } catch (error) {
      return {};
    }
  }

  return {};
}

function hasAny(text, terms) {
  const normalized = normalizeText(text);

  return (terms || []).some((term) => {
    return normalized.includes(normalizeText(term));
  });
}

function getInputValue(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null && value !== '') {
      return value;
    }
  }

  return null;
}

function safeJson(value) {
  try {
    return JSON.stringify(value);
  } catch (error) {
    return '';
  }
}

function hasOwn(object, key) {
  return Object.prototype.hasOwnProperty.call(object || {}, key);
}

// ============================================================
// Entrada
// ============================================================

const pergunta = String(
  getInputValue(input.pergunta, input.body?.pergunta, '') || ''
);

const perguntaNormalizada = String(
  getInputValue(input.pergunta_normalizada, normalizeText(pergunta)) || ''
);

const textoPergunta = normalizeText(perguntaNormalizada || pergunta);

const detectedIntent = String(
  getInputValue(
    input.detected_intent,
    input.intencao_detectada,
    input.intencao,
    'consulta_geral'
  )
);

const intentConfidence = Number(
  getInputValue(input.intent_confidence, 0.5)
);

const intentReasons = Array.isArray(input.intent_reasons)
  ? input.intent_reasons
  : [];

const entidadesDetectadas = input.entidades_detectadas || [];
const contextoDuckLake = input.contexto_ducklake || {};
const contextoTexto = input.contexto_texto || '';
const padraoSql = input.padrao_sql || null;

const regras = toArray(contextoDuckLake.regras);
const dre = toArray(contextoDuckLake.dre);
const catalogo = toArray(contextoDuckLake.catalogo);
const padroes = toArray(contextoDuckLake.padroes);
const entidades = toArray(contextoDuckLake.entidades);

// ============================================================
// Acesso ao contexto dinâmico
// ============================================================

function findRuleByNameOrGroup(searchTerms) {
  const terms = (searchTerms || []).map(normalizeText);

  return regras.find((rule) => {
    const text = normalizeText([
      rule.rule_group,
      rule.rule_name,
      rule.rule_content,
      rule.validation_hint,
      safeJson(rule.applies_to_intents)
    ].join(' '));

    return terms.some((term) => text.includes(term));
  }) || null;
}

function findPatternByIntent(intentName) {
  return padroes.find((pattern) => {
    return normalizeText(pattern.intent_name) === normalizeText(intentName);
  }) || null;
}

function findCatalogTable(tableName) {
  return catalogo.find((table) => {
    return normalizeText(table.table_name) === normalizeText(tableName);
  }) || null;
}

function tableAllowedNames() {
  return catalogo
    .map((table) => table.table_name)
    .filter(Boolean);
}

function tableFullNames() {
  return catalogo
    .map((table) => {
      const schema = table.schema_name || 'main_gold';
      const name = table.table_name;

      if (!name) return null;

      return `dev_lakehouse.${schema}.${name}`;
    })
    .filter(Boolean);
}

function dreItemsByPredicate(predicate) {
  return dre.filter((item) => {
    try {
      return predicate(item);
    } catch (error) {
      return false;
    }
  });
}

function dreFilterHintsByPredicate(predicate) {
  return dreItemsByPredicate(predicate)
    .map((item) => item.sql_filter_hint)
    .filter(Boolean);
}

function dreLikeFiltersByPredicate(predicate) {
  return dreItemsByPredicate(predicate)
    .map((item) => {
      if (item.sql_filter_hint) {
        return item.sql_filter_hint;
      }

      if (item.dre_code) {
        return `pc.nivel_1_bi LIKE '${item.dre_code} -%'`;
      }

      return null;
    })
    .filter(Boolean);
}

function dreExclusionFiltersByPredicate(predicate) {
  return dreItemsByPredicate(predicate)
    .map((item) => {
      if (item.dre_code) {
        return `pc.nivel_1_bi NOT LIKE '${item.dre_code} -%'`;
      }

      return null;
    })
    .filter(Boolean);
}

function categoryOf(item) {
  return normalizeText(item.category || item.categoria || '');
}

function signOf(item) {
  return normalizeText(item.sign_convention || item.sinal || '');
}

function isRevenue(item) {
  const category = categoryOf(item);
  const sign = signOf(item);

  return (
    category.includes('receita') ||
    item.is_revenue === true ||
    sign === 'positivo'
  );
}

function isDeduction(item) {
  const category = categoryOf(item);

  return (
    category.includes('deducao') ||
    category.includes('dedução') ||
    item.is_deduction === true
  );
}

function isCostOrExpenseForBudgetOverrun(item) {
  return !isRevenue(item) && !isDeduction(item);
}

function isOpex(item) {
  const category = categoryOf(item);

  return (
    category.includes('opex') ||
    item.is_opex === true
  );
}

function isRol(item) {
  return isRevenue(item) || isDeduction(item);
}

function isCmv(item) {
  const category = categoryOf(item);

  return (
    category.includes('cmv') ||
    category.includes('custo') && !category.includes('variavel') ||
    item.is_cost === true
  );
}

function getRuleContentFallback(searchTerms, fallbackText) {
