    `metricas=${safeJson(table.metric_columns || [])}`,
    `datas=${safeJson(table.date_columns || [])}`,
    `joins=${safeJson(table.join_rules || [])}`
  ];

  return parts.filter(Boolean).join(' | ');
}

function getBrandFiltersFromDetectedEntities() {
