        return entity.sql_filter_hint || entity.canonical_value || null;
      })
      .filter(Boolean)
  );
}

// ============================================================
// Helpers de limite e ranking particionado
// ============================================================

function textIncludesPartitionedRanking(text) {
  const normalized = normalizeText(text);

  const hasRankingFunction =
    normalized.includes('rank() over') ||
    normalized.includes('dense_rank() over') ||
    normalized.includes('row_number() over') ||
    normalized.includes('ranking_na_') ||
    normalized.includes('ranking_no_') ||
    normalized.includes('ranking_por_') ||
    normalized.includes('ranking dentro') ||
    normalized.includes('ranking particionado');

  const hasPartition =
    normalized.includes('partition by') ||
    normalized.includes('por marca') ||
    normalized.includes('por unidade') ||
    normalized.includes('por setor') ||
    normalized.includes('por centro') ||
    normalized.includes('por grupo');

  return hasRankingFunction && hasPartition;
}


function questionHasExplicitTopN() {
  const normalized = normalizeText(perguntaNormalizada || pergunta);

  return (
    /\btop\s+\d+\b/.test(normalized) ||
    /\bprimeir[oa]s?\s+\d+\b/.test(normalized) ||
    /\b\d+\s+(maiores|menores|melhores|piores|principais)\b/.test(normalized) ||
    /\bmaiores\s+\d+\b/.test(normalized) ||
    /\bmenores\s+\d+\b/.test(normalized) ||
    /\bmelhores\s+\d+\b/.test(normalized) ||
    /\bpiores\s+\d+\b/.test(normalized)
  );
}

function planIndicatesPartitionedRanking(plan) {
  if (!plan || typeof plan !== 'object') {
    return false;
  }

  const searchableText = [
    plan.modelo_query,
    plan.subtipo,
    plan.objetivo,
    plan.ordenacao,
    plan.limit_strategy,
    safeJson(plan.metricas),
    safeJson(plan.metricas_obrigatorias_no_select_final),
    safeJson(plan.formulas_obrigatorias),
    safeJson(plan.regras_sql),
    safeJson(plan.validacoes_offline_recomendadas),
    safeJson(plan.ctes_recomendadas),
    safeJson(plan.contexto_semantico_usado?.padrao_sql_contexto),
    safeJson(plan.ranking)
  ].join(' ');

  return textIncludesPartitionedRanking(searchableText);
}

function getExplicitTopNValue() {
  const normalized = normalizeText(perguntaNormalizada || pergunta);

  const patterns = [
    /\btop\s+(\d+)\b/,
    /\bprimeir[oa]s?\s+(\d+)\b/,
    /\b(\d+)\s+(?:maiores|menores|melhores|piores|principais)\b/,
    /\b(?:maiores|menores|melhores|piores)\s+(\d+)\b/
  ];

  for (const pattern of patterns) {
    const match = normalized.match(pattern);
    if (match) {
      const value = Number(match[1]);
      if (Number.isFinite(value) && value > 0) {
        return Math.trunc(value);
      }
    }
  }

  return null;
}

function isPositiveLimitInstruction(value) {
  const text = normalizeText(value);

  if (!text) return false;

  const mentionsLimit =
    text.includes('limit') ||
    text.includes('limite') ||
    text.includes('top_n') ||
    text.includes('bottom_n');

  if (!mentionsLimit) return false;

  const isNegativePolicy =
    text.includes('nao aplicar') ||
    text.includes('não aplicar') ||
    text.includes('nao usar') ||
    text.includes('não usar') ||
    text.includes('nao inventar') ||
    text.includes('não inventar') ||
    text.includes('nao adicionar') ||
    text.includes('não adicionar') ||
    text.includes('nao deve conter') ||
    text.includes('não deve conter') ||
    text.includes('sem top n explicito') ||
    text.includes('sem top n explícito') ||
    text.includes('interface') ||
    text.includes('pdf') ||
    text.includes('csv') ||
    text.includes('markdown');

  if (isNegativePolicy) return false;

  return (
    text.includes('aplicar limit') ||
    text.includes('usar limit') ||
    text.includes('conter limit') ||
    text.includes('limite padrao') ||
    text.includes('limite padrão') ||
    text.includes('limit padrao') ||
    text.includes('limit padrão') ||
    text.includes('ranking_maiores <= top_n') ||
    text.includes('ranking_menores <= bottom_n') ||
    /\blimit\s+\d+\b/.test(text)
  );
}

function removePositiveLimitInstructions(values) {
  return uniqueArray((values || []).filter((value) => !isPositiveLimitInstruction(value)));
}

function applySqlLimitPolicy(plan) {
  if (!plan || typeof plan !== 'object') {
    return plan;
  }

  const hasExplicitTopN = questionHasExplicitTopN();
  const explicitTopN = getExplicitTopNValue();
  const isPartitionedRanking = planIndicatesPartitionedRanking(plan);

  // Nunca transportar limites de interface/PDF/tabela/relatório para o plano SQL.
  delete plan.limit;
  delete plan.operational_limit;
  delete plan.limit_final;
  delete plan.limit_planejado;
  delete plan.max_rows;
  delete plan.row_limit;

  plan.regras_sql = removePositiveLimitInstructions(plan.regras_sql);
  plan.validacoes_offline_recomendadas = removePositiveLimitInstructions(plan.validacoes_offline_recomendadas);
  plan.pontos_de_atencao = removePositiveLimitInstructions(plan.pontos_de_atencao);
  plan.filtros_saida = removePositiveLimitInstructions(plan.filtros_saida);

  if (plan.formulas_obrigatorias && typeof plan.formulas_obrigatorias === 'object') {
    for (const key of Object.keys(plan.formulas_obrigatorias)) {
      if (isPositiveLimitInstruction(plan.formulas_obrigatorias[key])) {
        delete plan.formulas_obrigatorias[key];
      }
    }
  }

  if (plan.ranking && typeof plan.ranking === 'object') {
    delete plan.ranking.top_n;
    delete plan.ranking.bottom_n;
    delete plan.ranking.limit;

    if (typeof plan.ranking.rule === 'string' && isPositiveLimitInstruction(plan.ranking.rule)) {
      plan.ranking.rule = hasExplicitTopN && explicitTopN
        ? `Gerar ranking no grão final e aplicar filtro semântico usando o número explicitamente solicitado pelo usuário (${explicitTopN}); não usar LIMIT global.`
        : 'Gerar ranking no grão final; como o usuário não pediu quantidade explícita, não filtrar por quantidade nem usar LIMIT global.';
    }
  }

  if (hasExplicitTopN && explicitTopN) {
    plan.sql_global_limit_allowed = !isPartitionedRanking;
    plan.limit_strategy = isPartitionedRanking
      ? 'explicit_top_n_inside_partition_from_user_text'
      : 'explicit_top_n_from_user_text_no_interface_limit';
    plan.explicit_top_n = explicitTopN;

    if (plan.ranking && typeof plan.ranking === 'object') {
      plan.ranking.explicit_top_n = explicitTopN;
    }

    plan.regras_sql = uniqueArray([
      ...(plan.regras_sql || []),
      `O usuário pediu explicitamente Top N/quantidade ${explicitTopN}; esse número pode ser usado semanticamente na SQL.`,
      isPartitionedRanking
        ? 'Como há ranking particionado, aplicar o Top N dentro da partição; não usar LIMIT global.'
        : 'Como não há ranking particionado, o Top N explícito pode ser aplicado semanticamente, preferencialmente via ranking/filtro ou LIMIT global se fizer sentido.'
    ]);

    return plan;
  }

  plan.sql_global_limit_allowed = false;
  plan.limit_strategy = isPartitionedRanking
    ? 'no_sql_limit_for_partitioned_ranking_without_explicit_top_n'
    : 'no_sql_limit_without_explicit_top_n';

  plan.regras_sql = uniqueArray([
    ...(plan.regras_sql || []),
    'Não aplicar LIMIT SQL por padrão.',
    'Não usar limite de interface, PDF, markdown, tabela, relatório ou CSV dentro da SQL.',
    'Aplicar limite SQL somente quando o usuário pedir explicitamente Top N ou quantidade específica.',
    'Quando o usuário disser apenas maiores, menores, principais, melhor ou pior sem número, apenas ordenar; não limitar.'
  ]);

  plan.validacoes_offline_recomendadas = uniqueArray([
    ...(plan.validacoes_offline_recomendadas || []),
    'Se não houver Top N explícito na pergunta, a SQL não deve conter LIMIT global nem filtro de quantidade.'
  ]);

  return plan;
}

