function comparativeFactContract(requiredMetricTypes, aggregationCte) {
  return {
    strategy:
      'normalized_fact_union_conditional_aggregation',

    fact_cte:
      'fatos_normalizados',

    aggregation_cte:
      aggregationCte || 'agregado_condicional',

    required_metric_types:
      requiredMetricTypes,

    rule:
      'Unir as fontes fato necessárias em fatos_normalizados com UNION ALL, retornando as mesmas dimensões finais, tipo_metrica e valor; depois consolidar com SUM(CASE WHEN tipo_metrica = ... THEN valor ELSE 0 END). Não juntar CTEs separadas de fatos entre si.'
  };
}

function factGrainContract(dimensions) {
  return {
    dimensions,
    metric_discriminator: 'tipo_metrica',
    value_column: 'valor',
    rule:
      'Cada braço de fatos_normalizados deve retornar exatamente as dimensões finais, tipo_metrica e valor.'
