function planOrcadoVsRealizadoGrupoDre() {
  const includePreviousYear =
    falaAnoAnterior ||
    hasAny(textoPergunta, [
      'comparado com',
      'ano anterior',
      '2025'
    ]);

  const metricTypes = includePreviousYear
    ? [
        'realizado_atual',
        'orcado_atual',
        'realizado_anterior'
      ]
    : [
        'realizado_atual',
        'orcado_atual'
      ];

  const metricas = [
    'grupo_dre',
    'realizado_rs',
    'orcado_rs',
    'variancia_rs',
    'variancia_perc',
    'tipo_variacao'
  ];

  if (falaContaContabil || hasAny(textoPergunta, ['contas maiores', 'contas menores'])) {
    metricas.splice(1, 0, 'conta_contabil');
  }

  if (includePreviousYear) {
    metricas.push(
      'realizado_anterior_rs',
      'variancia_vs_anterior_rs',
      'variancia_vs_anterior_perc'
    );
  }

  return basePlan({
    modelo_query:
      'orcado_vs_realizado_grupo_dre',

    subtipo:
