// ============================================================
// Seleção do plano
// ============================================================

let planoQuery = null;
const motivoPlano = [];

if (
  detectedIntent === 'estouro_orcamento_conta_contabil' ||
  (
    falaContaContabil &&
    falaOrcamento &&
    falaEstouro
  )
) {
  planoQuery = planEstouroOrcamentoContaContabil();

  motivoPlano.push(
    'Selecionado modelo genérico de estouro de orçamento por conta contábil.'
  );
}

else if (
  detectedIntent === 'impacto_setor_marca' ||
  (
    falaMarca &&
    falaCentroCusto &&
    (
      falaOpex ||
      falaImpacto
    )
  )
) {
  planoQuery = planImpactoSetorMarca();

  motivoPlano.push(
    'Selecionado modelo de impacto de setor/centro de custo por marca.'
  );
}

else if (
  detectedIntent === 'opex_por_centro_custo' ||
  (
    falaCentroCusto &&
    (
      falaOpex ||
      falaOrcamento ||
      falaRanking
    )
  )
) {
  planoQuery = planOpexPorCentroCusto();

  motivoPlano.push(
    'Selecionado modelo de OPEX por centro de custo.'
  );
}

else if (
  detectedIntent === 'comparativo_marcas' ||
  (
    falaComparacao &&
    falaMarca
  )
) {
  if (falaOpex) {
    planoQuery = planOpexPorMarca();

    motivoPlano.push(
      'Selecionado comparativo de marcas com foco em OPEX.'
    );
  } else {
    planoQuery = planResultadoMensalPorMarca();

    motivoPlano.push(
      'Selecionado comparativo de marcas com foco em resultado.'
    );
  }
}

else if (
  detectedIntent === 'resultado_por_marca' ||
  (
    falaMarca &&
    (
      falaResultado ||
      falaRol ||
      falaRanking
    )
  )
) {
  planoQuery = planResultadoMensalPorMarca();

  motivoPlano.push(
    'Selecionado modelo de resultado mensal por marca.'
  );
}

else if (
  detectedIntent === 'orcado_vs_realizado' ||
  (
    falaOrcamento &&
    (
      falaDre ||
      falaRealizado ||
      falaImpacto ||
      falaAnoAnterior ||
      !falaCentroCusto
    )
  )
) {
  planoQuery = planOrcadoVsRealizadoGrupoDre();

  motivoPlano.push(
    'Selecionado modelo de orçado versus realizado.'
  );
}

else if (
  detectedIntent === 'opex_por_marca' ||
  (
    falaOpex &&
    falaMarca
  )
) {
  planoQuery = planOpexPorMarca();

  motivoPlano.push(
    'Selecionado modelo de OPEX por marca.'
  );
}

else if (
  detectedIntent === 'dre_mensal'
) {
  planoQuery = planDreMensalAnalitica();

  motivoPlano.push(
    'Selecionado modelo de DRE mensal analítica.'
  );
}

else if (
  falaMarca &&
  falaRol &&
  !falaResultado &&
  !falaRanking
) {
  planoQuery = planRolPorMarca();

  motivoPlano.push(
    'Selecionado modelo de ROL por marca.'
  );
}

else {
  planoQuery = planConsultaGeral();

  motivoPlano.push(
    'Fallback para consulta geral controlada.'
  );
}

// ============================================================
// Ajustes finais de consistência
// ============================================================

planoQuery.motivo_selecao_plano = motivoPlano;

planoQuery.tabelas_requeridas =
  uniqueArray(planoQuery.tabelas_requeridas);

planoQuery.metricas =
  uniqueArray(planoQuery.metricas);

planoQuery.metricas_obrigatorias_no_select_final =
  uniqueArray(
    planoQuery.metricas_obrigatorias_no_select_final ||
    planoQuery.metricas
  );

planoQuery.dimensoes =
  uniqueArray(planoQuery.dimensoes);

planoQuery.dimensoes_obrigatorias_no_select_final =
  uniqueArray(
    planoQuery.dimensoes_obrigatorias_no_select_final ||
    planoQuery.dimensoes
  );

planoQuery.filtros_requeridos =
  uniqueArray(planoQuery.filtros_requeridos);

planoQuery.filtros_saida =
  uniqueArray(planoQuery.filtros_saida);

planoQuery.regras_sql =
  uniqueArray(planoQuery.regras_sql);

planoQuery.validacoes_offline_recomendadas =
  uniqueArray(planoQuery.validacoes_offline_recomendadas);

// Contrato genérico para perguntas que pedem simultaneamente maiores e menores.
// Não é SQL fixa e não depende de pergunta literal.
if (perguntaPedeMaioresEMenores) {
  planoQuery.ranking = {
    ...(planoQuery.ranking || {}),
    strategy: 'single_output_dual_rank_filter',
    required_columns: [
      'ranking_maiores',
      'ranking_menores',
      'tipo_ranking'
    ],
    rule:
      'Gerar uma única saída final com ranking_maiores, ranking_menores e tipo_ranking; se o usuário pedir quantidade explícita, filtrar semanticamente por esse número; se não pedir, não filtrar por quantidade; evitar UNION ALL final para separar maiores e menores.'
  };

  planoQuery.metricas =
    uniqueArray([
      ...(planoQuery.metricas || []),
      'ranking_maiores',
      'ranking_menores',
      'tipo_ranking'
    ]);

  planoQuery.metricas_obrigatorias_no_select_final =
    uniqueArray([
      ...(planoQuery.metricas_obrigatorias_no_select_final || []),
      'ranking_maiores',
      'ranking_menores',
      'tipo_ranking'
    ]);

  planoQuery.regras_sql =
    uniqueArray([
      ...(planoQuery.regras_sql || []),
      'Quando a pergunta pedir maiores e menores, não usar UNION ALL final para duplicar blocos de ranking se uma saída única com ranking_maiores/ranking_menores resolver.',
      'Quando a pergunta pedir maiores e menores, expor ranking_maiores, ranking_menores e tipo_ranking no SELECT final.',
      'tipo_ranking deve ser derivado por CASE a partir dos rankings, por exemplo maior, menor ou ambos, sem depender de UNION ALL final.'
    ]);

  planoQuery.validacoes_offline_recomendadas =
    uniqueArray([
      ...(planoQuery.validacoes_offline_recomendadas || []),
      'SELECT final deve conter ranking_maiores, ranking_menores e tipo_ranking quando a pergunta pedir maiores e menores.',
      'SQL deve evitar UNION ALL final para separar maiores e menores quando uma saída única for suficiente.'
    ]);
}

// Remove chaves com undefined dentro de formulas_obrigatorias.
if (
  planoQuery.formulas_obrigatorias &&
  typeof planoQuery.formulas_obrigatorias === 'object'
) {
  for (const key of Object.keys(planoQuery.formulas_obrigatorias)) {
    if (planoQuery.formulas_obrigatorias[key] === undefined) {
      delete planoQuery.formulas_obrigatorias[key];
    }
  }
}

// Aplica política global de LIMIT SQL.
// Isso deve rodar no final porque remove limites herdados de modelos antigos e patterns.
planoQuery = applySqlLimitPolicy(planoQuery);

// ============================================================
// Retorno
// ============================================================

return [
  {
    json: {
      ...input,

      pergunta,
      pergunta_normalizada: perguntaNormalizada,

      detected_intent: detectedIntent,
      intent_confidence: intentConfidence,
      intent_reasons: intentReasons,

      entidades_detectadas: entidadesDetectadas,
      padrao_sql: padraoSql,
      contexto_ducklake: contextoDuckLake,
      contexto_texto: contextoTexto,

      agent_version: AGENT_VERSION,
      modelo_query_planejado: planoQuery.modelo_query,
      subtipo_query_planejado: planoQuery.subtipo,
      plano_query: planoQuery
    }
  }
];

// ============================================================
// CODE - VALIDAR PLANO QUERY SEMANTICO
// E8-N8N-C — Semantic Plan Guard v6.1
//
// Objetivo:
// - Ajustar o plano_query com base no semantic_request_observado.
// - Não gerar SQL.
// - Não chamar IA.
// - Não mexer no prompt principal.
// - Não afrouxar validador.
// - Corrigir o plano antes de ele virar prompt.
//
// Este node deve ficar entre:
// Code - Montar Plano Query DuckLake
// e
// Code - Montar Prompt SQL DuckLake Offline
//
// v6.1:
// - Corrige bug explicitTopN não definido.
// - Corrige erro de sintaxe no bloco de catálogo DRE.
// - Centraliza detecção genérica de Top N explícito.
// - Não confunde anos, códigos DRE ou meses com Top N.
// - Mantém regra: sem LIMIT SQL padrão.
// - Top N explícito deve virar filtro semântico de ranking, não LIMIT global.
// - Ranking maiores_e_menores usa estratégia single_output_dual_rank_filter.
// - Evita UNION ALL final para rankings duplos quando a saída pode ser única.
// - Adiciona contrato genérico de grão de fatos antes de joins comparativos.
// - Mantém sign_context para despesas negativas.
// - Mantém plano orientado pelo semantic_request_observado.
// ============================================================

const input = $json || {};

// ============================================================
// Helpers
// ============================================================

function deepClone(value) {
  return JSON.parse(JSON.stringify(value == null ? null : value));
}

function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[?!.;,:\"'`´]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeLoose(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^\w\s/-]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function toArray(value) {
  if (!value) return [];
  if (Array.isArray(value)) return value;

  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
      return [];
    }
  }

  return [];
}

function toObject(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return {};
  }

  return value;
}

function uniqueArray(values) {
  return [...new Set((values || []).filter(Boolean))];
}

function ensureArrayField(obj, fieldName) {
  if (!Array.isArray(obj[fieldName])) {
    obj[fieldName] = [];
  }

  return obj[fieldName];
}

function addUnique(obj, fieldName, values) {
  const arr = ensureArrayField(obj, fieldName);

  for (const value of values || []) {
    if (value && !arr.includes(value)) {
      arr.push(value);
    }
  }

  obj[fieldName] = uniqueArray(arr);
}

function includesAny(text, terms) {
  const normalized = normalizeText(text);
  return (terms || []).some((term) => normalized.includes(normalizeText(term)));
}

function parseDreCode(value) {
  const text = String(value || '').trim();
  const match = text.match(/^(\d{1,2})\b/);

  if (!match) {
    return null;
  }

  return match[1].padStart(2, '0');
}

function hasMetric(plano, metricName) {
  return toArray(plano.metricas).includes(metricName);
}

// ============================================================
// Top N explícito — regra genérica, sem hardcode de pergunta
// ============================================================
//
// Aceita:
// - top 5
// - top10
// - 10 maiores
// - 5 menores
// - primeiros 20
// - últimas 15
// - traga 10
// - liste 30
//
// Não aceita como Top N:
// - 09 - GASTOS COM PESSOAL
// - maio de 2026
// - maio de 2025
// - grupo 09
// - mês 05
// ============================================================

function extractExplicitTopN(value) {
  const p = normalizeText(value);

  const patterns = [
    /\btop\s*(\d+)\b/i,
    /\b(primeiros|primeiras|ultimos|ultimas)\s+(\d+)\b/i,
    /\b(\d+)\s+(maiores|menores|principais|melhores|piores|primeiros|primeiras|ultimos|ultimas)\b/i,
    /\b(maiores|menores|principais|melhores|piores)\s+(\d+)\b/i,
    /\b(traga|liste|mostrar|mostre|retorne)\s+(\d+)\b/i
  ];

  for (const pattern of patterns) {
    const match = p.match(pattern);

    if (!match) {
      continue;
    }

    const numericValue = match
      .slice(1)
      .map((part) => Number(part))
      .find((part) => Number.isFinite(part) && part > 0);

    if (Number.isFinite(numericValue) && numericValue > 0) {
      return {
        hasExplicitTopN: true,
        value: Math.trunc(numericValue),
        matched_text: match[0]
      };
    }
  }

  return {
    hasExplicitTopN: false,
    value: null,
    matched_text: null
  };
}

// ============================================================
// Entrada base
// ============================================================

const pergunta = input.pergunta || (input.body && input.body.pergunta) || '';
const perguntaNormalizada = input.pergunta_normalizada || pergunta;
const texto = normalizeText(perguntaNormalizada || pergunta);

const explicitTopNInfo = extractExplicitTopN(perguntaNormalizada || pergunta);
const hasExplicitTopN = explicitTopNInfo.hasExplicitTopN;
const explicitTopN = explicitTopNInfo.value;

const semanticRequest = toObject(input.semantic_request_observado);
const semanticDimensions = toArray(semanticRequest.dimensions);
const semanticOutputGrain = toArray(semanticRequest.output_grain);
const semanticPeriods = toArray(semanticRequest.periods);
const semanticComparison = toObject(semanticRequest.comparison);
const semanticFilters = toObject(semanticRequest.filters);
const semanticRawFilters = toArray(semanticFilters.raw);

const contextoDucklake = toObject(input.contexto_ducklake);
const dreCatalog = toArray(contextoDucklake.dre);

const planoOriginal = toObject(input.plano_query);
const planoQuery = deepClone(planoOriginal) || {};

const guardWarnings = [];
const guardActions = [];

// ============================================================
// Validação mínima
// ============================================================

if (!planoQuery || typeof planoQuery !== 'object') {
  throw new Error('plano_query não encontrado para validação semântica.');
}

if (!planoQuery.modelo_query) {
  planoQuery.modelo_query =
    input.modelo_query_planejado ||
    input.detected_intent ||
    'consulta_geral';

  guardWarnings.push('plano_query.modelo_query estava ausente e foi preenchido com fallback.');
}

// ============================================================
// Conta contábil
// ============================================================

const semanticAsksAccount =
  semanticDimensions.includes('conta_contabil') ||
  semanticOutputGrain.includes('conta_contabil') ||
  includesAny(texto, [
    'conta',
    'contas',
    'conta contabil',
    'contas contabeis',
    'contas maiores',
    'contas menores',
    'maiores e menores'
  ]);

if (semanticAsksAccount) {
  addUnique(planoQuery, 'dimensoes', ['conta_contabil']);
  addUnique(planoQuery, 'granularidade', ['conta_contabil']);
  addUnique(planoQuery, 'colunas_obrigatorias', ['conta_contabil']);
  addUnique(planoQuery, 'aliases_obrigatorios', ['conta_contabil']);

  guardActions.push('Adicionada dimensão/granularidade conta_contabil ao plano_query.');
}

// ============================================================
// Grupo DRE
// ============================================================

function getDetectedGrupoDre() {
  const grupoFromSemantic = toArray(semanticFilters.grupo_dre).find(Boolean);

  if (grupoFromSemantic) {
    return String(grupoFromSemantic);
  }

  const rawGrupo = semanticRawFilters.find((item) => {
    return item && item.type === 'grupo_dre' && (item.canonical_value || item.value || item.code);
  });

  if (rawGrupo) {
    return String(rawGrupo.canonical_value || rawGrupo.value || rawGrupo.code);
  }

  const matchQuestion = String(pergunta || '').match(/\b(\d{1,2})\s*-\s*([A-ZÀ-Úa-zà-ú0-9\s]+)/);

  if (matchQuestion) {
    return `${matchQuestion[1].padStart(2, '0')} - ${matchQuestion[2].trim()}`;
  }

  return null;
}

const grupoDreDetectado = getDetectedGrupoDre();
const dreCodeDetectado = parseDreCode(grupoDreDetectado);

if (grupoDreDetectado) {
  if (
    !planoQuery.filtros_requeridos ||
    typeof planoQuery.filtros_requeridos !== 'object' ||
    Array.isArray(planoQuery.filtros_requeridos)
  ) {
    planoQuery.filtros_requeridos = {};
  }

  planoQuery.filtros_requeridos.grupo_dre = grupoDreDetectado;

  addUnique(planoQuery, 'dimensoes', ['grupo_dre']);
  addUnique(planoQuery, 'granularidade', ['grupo_dre']);
  addUnique(planoQuery, 'colunas_obrigatorias', ['grupo_dre']);
  addUnique(planoQuery, 'aliases_obrigatorios', ['grupo_dre']);

  guardActions.push(`Filtro semântico de grupo_dre aplicado ao plano_query: ${grupoDreDetectado}.`);
}

if (grupoDreDetectado && semanticAsksAccount) {
  planoQuery.modelo_query = planoQuery.modelo_query || 'orcado_vs_realizado_grupo_dre';

  addUnique(planoQuery, 'dimensoes', ['grupo_dre', 'conta_contabil']);
  addUnique(planoQuery, 'granularidade', ['grupo_dre', 'conta_contabil']);
  addUnique(planoQuery, 'colunas_obrigatorias', ['grupo_dre', 'conta_contabil']);
  addUnique(planoQuery, 'aliases_obrigatorios', ['grupo_dre', 'conta_contabil']);

  guardActions.push('Plano ajustado para análise por conta_contabil dentro do grupo_dre filtrado.');
}

// ============================================================
// Períodos comparativos
// ============================================================

function periodKey(period) {
  return [
    (period && period.source) || 'unknown',
    (period && period.year) || '',
    (period && period.month) || '',
    (period && period.start) || ''
  ].join('|');
}

const uniquePeriods = [];
const seenPeriods = new Set();

for (const period of semanticPeriods) {
  const key = periodKey(period);

  if (!seenPeriods.has(key)) {
    seenPeriods.add(key);
    uniquePeriods.push(period);
  }
}

const realizedPeriods = uniquePeriods.filter((p) => p && p.source === 'realizado');
const budgetPeriods = uniquePeriods.filter((p) => p && p.source === 'orcado');

const hasBudgetComparison =
  budgetPeriods.length > 0 ||
  includesAny(texto, ['orcamento', 'orçamento', 'orcado', 'orçado', 'budget']);

const hasPriorPeriodComparison =
  realizedPeriods.length >= 2 ||
  includesAny(texto, [
    'comparado com',
    'comparando com',
    'mes anterior',
    'mês anterior',
    'ano anterior',
    'ano passado',
    'periodo anterior',
    'período anterior'
  ]);

if (uniquePeriods.length > 0) {
  planoQuery.periodos_detectados = uniquePeriods;
  guardActions.push(`Períodos semânticos anexados ao plano_query: ${uniquePeriods.length}.`);
}

// ============================================================
// Métricas obrigatórias
// ============================================================

const metricasBase = [];

if (hasBudgetComparison) {
  metricasBase.push(
    'realizado_rs',
    'orcado_rs',
    'variancia_rs',
    'variancia_perc',
    'tipo_variacao'
  );
}

if (hasPriorPeriodComparison) {
  metricasBase.push(
    'realizado_anterior_rs',
    'variancia_vs_anterior_rs',
    'variancia_vs_anterior_perc'
  );
}

if (metricasBase.length > 0) {
  addUnique(planoQuery, 'metricas', metricasBase);
  addUnique(planoQuery, 'aliases_obrigatorios', metricasBase);

  guardActions.push(`Métricas comparativas obrigatórias adicionadas: ${metricasBase.join(', ')}.`);
}

// ============================================================
// Ranking maiores e menores
// ============================================================

const asksMaioresMenores =
  semanticComparison.direction === 'maiores_e_menores' ||
  semanticComparison.ranking === true ||
  includesAny(texto, [
    'maiores e menores',
    'maior e menor',
    'maiores menores',
    'contas maiores e menores',
    'contas maiores',
    'contas menores'
  ]);

if (asksMaioresMenores) {
  const baseMetric = hasMetric(planoQuery, 'variancia_rs') ? 'variancia_rs' : 'realizado_rs';

  planoQuery.ranking = {
    ...(planoQuery.ranking || {}),
    type: 'maiores_e_menores',
    strategy: 'single_output_dual_rank_filter',
    base_metric: baseMetric,
    ...(hasExplicitTopN ? { explicit_top_n: explicitTopN } : {}),
    requires_two_sides: true,
    requires_union_all: false,
    output_label_alias: 'tipo_ranking',
    ranking_aliases: ['ranking_maiores', 'ranking_menores'],
    output_strategy: hasExplicitTopN
      ? 'single_select_with_explicit_quantity_filter'
      : 'single_select_without_quantity_filter',
    overlap_behavior: 'single_row_with_tipo_ranking_maiores_e_menores_when_both_conditions_match'
  };

  addUnique(planoQuery, 'metricas', [
    'tipo_ranking',
    'ranking_maiores',
    'ranking_menores'
  ]);

  addUnique(planoQuery, 'aliases_obrigatorios', [
    'tipo_ranking',
    'ranking_maiores',
    'ranking_menores'
  ]);

  const rankingInstructions = [
    'Calcular ranking_maiores e ranking_menores em uma CTE analítica no grão final da análise.',
    'Gerar uma única saída final, sem UNION ALL final para separar maiores e menores quando a saída única atender à pergunta.',
    'Gerar tipo_ranking por CASE com base nos aliases ranking_maiores e ranking_menores.',
    'Ordenar somente por aliases expostos no mesmo SELECT/CTE do ORDER BY, como tipo_ranking, ranking_maiores, ranking_menores ou a métrica base exposta.',
    'Evitar ORDER BY final que dependa de coluna auxiliar escondida em consulta composta.',
    'Usar UNION/UNION ALL final apenas se houver necessidade estrutural real; nesse caso, toda coluna usada pelo ORDER BY final precisa estar exposta no resultado composto ou em uma camada externa válida.',
    'Não usar LIMIT global para controlar visualização.'
  ];

  if (hasExplicitTopN) {
    rankingInstructions.push(
      `Como existe Top N explícito (${explicitTopN}), aplicar filtro semântico no ranking: ranking_maiores <= ${explicitTopN} OR ranking_menores <= ${explicitTopN}.`
    );
  } else {
    rankingInstructions.push(
      'Como não existe Top N explícito, não aplicar filtro de quantidade; expor os rankings e ordenar o resultado para permitir leitura de maiores e menores sem cortar linhas.'
    );
  }

  planoQuery.ordenacao = {
    type: 'ranking_maiores_e_menores',
    strategy: 'single_output_dual_rank_filter',
    base_metric: planoQuery.ranking.base_metric,
    instruction: rankingInstructions.join(' '),
    ...(hasExplicitTopN ? { top_n: explicitTopN, bottom_n: explicitTopN } : {}),
    preferred_filter: hasExplicitTopN
      ? `ranking_maiores <= ${explicitTopN} OR ranking_menores <= ${explicitTopN}`
      : null,
    preferred_order_by: [
      "CASE tipo_ranking WHEN 'maiores' THEN 1 WHEN 'maiores_e_menores' THEN 2 WHEN 'menores' THEN 3 ELSE 4 END",
      'ranking_maiores ASC',
      'ranking_menores ASC'
    ]
  };

  planoQuery.filtros_saida = {
    ...toObject(planoQuery.filtros_saida),
    ranking_maiores_e_menores: hasExplicitTopN
      ? `Preferir saída única: selecionar linhas onde ranking_maiores <= ${explicitTopN} OR ranking_menores <= ${explicitTopN}; expor tipo_ranking, ranking_maiores e ranking_menores; não duplicar a mesma linha por UNION ALL quando ela puder ser representada uma única vez.`
      : 'Preferir saída única sem filtro de quantidade: expor tipo_ranking, ranking_maiores e ranking_menores; ordenar por rankings e métrica base; não aplicar LIMIT e não duplicar a mesma linha por UNION ALL quando ela puder ser representada uma única vez.'
  };

  guardActions.push(
    hasExplicitTopN
      ? `Ranking semântico maiores_e_menores adicionado com Top N explícito ${explicitTopN}.`
      : 'Ranking semântico maiores_e_menores adicionado sem filtro de quantidade por ausência de Top N explícito.'
  );
}

// ============================================================
// Contexto de sinal por DRE
// ============================================================

function findDreCatalogRow(code, grupoValue) {
  const grupoNorm = normalizeLoose(grupoValue);

  for (const row of dreCatalog) {
    const rowCode = parseDreCode(row.dre_code || row.nivel_1_bi);
    const rowNivelNorm = normalizeLoose(row.nivel_1_bi);

    if (code && rowCode === code) {
      return row;
    }

    if (grupoNorm && rowNivelNorm && rowNivelNorm.includes(grupoNorm)) {
      return row;
    }

    if (grupoNorm && rowNivelNorm && grupoNorm.includes(rowNivelNorm)) {
      return row;
    }
  }

  return null;
}

function inferSignContext(code, grupoValue) {
  const row = findDreCatalogRow(code, grupoValue);

  const category = normalizeText((row && row.category) || '');
  const nivel = normalizeText((row && row.nivel_1_bi) || grupoValue || '');

  const isRevenue =
    (row && row.is_revenue === true) ||
    category.includes('receita') ||
    ['01'].includes(code);

  const isDeductionOrExpense =
    (row && row.is_deduction === true) ||
    (row && row.is_cost === true) ||
    (row && row.is_opex === true) ||
    category.includes('deducao') ||
    category.includes('custo') ||
    category.includes('despesa') ||
    category.includes('opex') ||
    includesAny(nivel, [
      'deducao',
      'deducoes',
      'cmv',
      'custo',
      'custos',
      'gastos',
      'despesa',
      'despesas',
      'opex',
      'imposto',
      'jcp',
      'royalties'
    ]) ||
    ['02', '03', '05', '06', '09', '10', '12', '14', '16'].includes(code);

  if (isRevenue) {
    return {
      natureza: 'receita',
      valores_positivos: true,
      despesa_negativa: false,
      variancia_negativa_significa: 'abaixo_do_orcamento',
      variancia_positiva_significa: 'acima_do_orcamento',
      tipo_variacao_negativa: 'Receita abaixo do orçamento',
      tipo_variacao_positiva: 'Receita acima do orçamento'
    };
  }

  if (isDeductionOrExpense) {
    return {
      natureza: 'despesa_ou_custo',
      valores_positivos: false,
      despesa_negativa: true,
      variancia_negativa_significa: 'acima_do_orcamento',
      variancia_positiva_significa: 'abaixo_do_orcamento',
      tipo_variacao_negativa: 'Despesa acima do orçamento',
      tipo_variacao_positiva: 'Despesa abaixo do orçamento'
    };
  }

  return {
    natureza: 'neutra',
    valores_positivos: null,
    despesa_negativa: null,
    variancia_negativa_significa: 'impacto_negativo',
    variancia_positiva_significa: 'impacto_positivo',
    tipo_variacao_negativa: 'Impacto negativo versus orçamento',
    tipo_variacao_positiva: 'Impacto positivo versus orçamento'
  };
}

if (grupoDreDetectado || dreCodeDetectado) {
  const inferredSign = inferSignContext(dreCodeDetectado, grupoDreDetectado);

  planoQuery.sign_context = {
    grupo_dre: grupoDreDetectado || null,
    dre_code: dreCodeDetectado || null,
    ...inferredSign
  };

  guardActions.push(`Contexto de sinal aplicado ao plano_query: natureza=${planoQuery.sign_context.natureza}.`);
}

// ============================================================
// Contrato genérico de grão de fatos
// ============================================================

if (hasBudgetComparison || hasPriorPeriodComparison) {
  planoQuery.fact_grain_contract = {
    version: 'fact-grain-safety-v1',
    applies_when: [
      'consulta combina fontes diretas e rateadas com UNION ALL',
      'consulta compara realizado, orçamento, período anterior ou outras bases fato'
    ],
    grain_dimensions: uniqueArray(
      toArray(planoQuery.granularidade).length
        ? toArray(planoQuery.granularidade)
        : toArray(planoQuery.dimensoes)
    ),
    required_sequence: [
      'montar bases de fatos por origem preservando apenas dimensões do grão e métricas necessárias',
      'agregar cada base de fato no grão final antes de qualquer join com outra base fato',
      'fazer joins comparativos apenas entre CTEs já agregadas no mesmo grão',
      'não fazer FULL OUTER JOIN diretamente entre CTEs de fatos que ainda contêm múltiplas linhas por origem direta/rateada no mesmo grão'
    ],
    purpose: 'evitar multiplicação de valores por join entre fatos antes da consolidação do grão'
  };

  guardActions.push('Contrato genérico de grão de fatos adicionado ao plano_query.');
}

// ============================================================
// Fórmulas obrigatórias dinâmicas
// ============================================================

if (
  !planoQuery.formulas_obrigatorias ||
  typeof planoQuery.formulas_obrigatorias !== 'object' ||
  Array.isArray(planoQuery.formulas_obrigatorias)
) {
  planoQuery.formulas_obrigatorias = {};
}

if (hasBudgetComparison) {
  planoQuery.formulas_obrigatorias.variancia_rs =
    'COALESCE(realizado_rs, 0) - COALESCE(orcado_rs, 0) AS variancia_rs';

  planoQuery.formulas_obrigatorias.variancia_perc =
    '(COALESCE(realizado_rs, 0) - COALESCE(orcado_rs, 0)) / NULLIF(ABS(COALESCE(orcado_rs, 0)), 0) * 100 AS variancia_perc';

  if (planoQuery.sign_context && planoQuery.sign_context.despesa_negativa === true) {
    planoQuery.formulas_obrigatorias.tipo_variacao =
      "CASE WHEN variancia_rs < 0 THEN 'Despesa acima do orçamento' WHEN variancia_rs > 0 THEN 'Despesa abaixo do orçamento' ELSE 'Sem variação' END AS tipo_variacao";
  } else if (planoQuery.sign_context && planoQuery.sign_context.natureza === 'receita') {
    planoQuery.formulas_obrigatorias.tipo_variacao =
      "CASE WHEN variancia_rs < 0 THEN 'Receita abaixo do orçamento' WHEN variancia_rs > 0 THEN 'Receita acima do orçamento' ELSE 'Sem variação' END AS tipo_variacao";
  } else {
    planoQuery.formulas_obrigatorias.tipo_variacao =
      "CASE WHEN variancia_rs < 0 THEN 'Impacto negativo versus orçamento' WHEN variancia_rs > 0 THEN 'Impacto positivo versus orçamento' ELSE 'Sem variação' END AS tipo_variacao";
  }
}

if (hasPriorPeriodComparison) {
  planoQuery.formulas_obrigatorias.variancia_vs_anterior_rs =
    'COALESCE(realizado_rs, 0) - COALESCE(realizado_anterior_rs, 0) AS variancia_vs_anterior_rs';

  planoQuery.formulas_obrigatorias.variancia_vs_anterior_perc =
    '(COALESCE(realizado_rs, 0) - COALESCE(realizado_anterior_rs, 0)) / NULLIF(ABS(COALESCE(realizado_anterior_rs, 0)), 0) * 100 AS variancia_vs_anterior_perc';
}

if (asksMaioresMenores) {
  planoQuery.formulas_obrigatorias.ranking_maiores =
    'ROW_NUMBER() OVER (ORDER BY variancia_rs DESC) AS ranking_maiores';

  planoQuery.formulas_obrigatorias.ranking_menores =
    'ROW_NUMBER() OVER (ORDER BY variancia_rs ASC) AS ranking_menores';

  if (hasExplicitTopN) {
    planoQuery.formulas_obrigatorias.tipo_ranking =
      `CASE WHEN ranking_maiores <= ${explicitTopN} AND ranking_menores <= ${explicitTopN} THEN 'maiores_e_menores' WHEN ranking_maiores <= ${explicitTopN} THEN 'maiores' WHEN ranking_menores <= ${explicitTopN} THEN 'menores' ELSE 'fora_do_recorte' END AS tipo_ranking`;

    planoQuery.formulas_obrigatorias.ranking_maiores_e_menores_saida =
      `Saída única sem UNION ALL final: aplicar filtro semântico de quantidade explícita ${explicitTopN} sobre ranking_maiores/ranking_menores; expor tipo_ranking, ranking_maiores e ranking_menores no SELECT final; não usar LIMIT global.`;
  } else {
    planoQuery.formulas_obrigatorias.tipo_ranking =
      "CASE WHEN ranking_maiores = 1 AND ranking_menores = 1 THEN 'maior_e_menor' WHEN ranking_maiores = 1 THEN 'maior' WHEN ranking_menores = 1 THEN 'menor' ELSE 'intermediario' END AS tipo_ranking";

    planoQuery.formulas_obrigatorias.ranking_maiores_e_menores_saida =
      'Saída única sem UNION ALL final: expor tipo_ranking, ranking_maiores e ranking_menores no SELECT final; não aplicar filtro de quantidade quando o usuário não pedir número explícito; não usar LIMIT global.';
  }

  guardActions.push('Fórmulas obrigatórias de ranking maiores/menores adicionadas com saída única.');
}

// ============================================================
// Política de LIMIT no plano
// ============================================================
// Não injetar LIMIT padrão no plano.
// Limite de interface/PDF/tabela/relatório não pertence à SQL.
// Se houver Top N explícito, o próprio ranking/contrato semântico deve tratar
// o filtro dentro do ranking, não como LIMIT global automático.
// ============================================================

if (!hasExplicitTopN) {
  delete planoQuery.limit;
  delete planoQuery.operational_limit;
  delete planoQuery.limit_final;
  delete planoQuery.limit_planejado;
  delete planoQuery.max_rows;
  delete planoQuery.row_limit;

  if (planoQuery.ranking && typeof planoQuery.ranking === 'object') {
    delete planoQuery.ranking.top_n;
    delete planoQuery.ranking.bottom_n;
    delete planoQuery.ranking.limit;
    delete planoQuery.ranking.explicit_top_n;
  }

  if (
    planoQuery.filtros_saida &&
    typeof planoQuery.filtros_saida === 'object' &&
    !Array.isArray(planoQuery.filtros_saida)
  ) {
    for (const key of Object.keys(planoQuery.filtros_saida)) {
      const normalized = normalizeText(planoQuery.filtros_saida[key]);

      if (
        normalized.includes('top_n') ||
        normalized.includes('bottom_n') ||
        normalized.includes('limit global') ||
        normalized.includes('limit sql')
      ) {
        delete planoQuery.filtros_saida[key];
      }
    }
  }

  if (
    planoQuery.formulas_obrigatorias &&
    typeof planoQuery.formulas_obrigatorias === 'object'
  ) {
    for (const key of Object.keys(planoQuery.formulas_obrigatorias)) {
      const normalized = normalizeText(planoQuery.formulas_obrigatorias[key]);

      if (
        normalized.includes('top_n') ||
        normalized.includes('bottom_n') ||
        normalized.includes('limit global') ||
        normalized.includes('limit sql')
      ) {
        delete planoQuery.formulas_obrigatorias[key];
      }
    }
  }

  planoQuery.sql_global_limit_allowed = false;
  planoQuery.limit_strategy = 'no_sql_limit_without_explicit_top_n';

  guardActions.push('LIMIT removido do plano: ausência de Top N explícito; visualização fica na interface.');
} else {
  delete planoQuery.limit;
  delete planoQuery.operational_limit;
  delete planoQuery.limit_final;
  delete planoQuery.limit_planejado;
  delete planoQuery.max_rows;
  delete planoQuery.row_limit;

  planoQuery.sql_global_limit_allowed = false;
  planoQuery.limit_strategy = 'explicit_top_n_must_be_applied_semantically_not_as_global_limit';
  planoQuery.explicit_top_n = explicitTopN;

  guardActions.push(`Top N explícito detectado (${explicitTopN}): limite deve ser aplicado semanticamente no ranking/filtro, nunca por configuração de interface nem LIMIT global.`);
}

// ============================================================
// Guard rails finais do plano
// ============================================================

if (semanticAsksAccount && !toArray(planoQuery.granularidade).includes('conta_contabil')) {
  guardWarnings.push('Plano ainda não contém conta_contabil na granularidade após guard.');
}

if (asksMaioresMenores && !planoQuery.ranking) {
  guardWarnings.push('Pergunta pede maiores/menores, mas ranking não foi estruturado.');
}

if (
  asksMaioresMenores &&
  planoQuery.ranking &&
  planoQuery.ranking.strategy !== 'single_output_dual_rank_filter'
) {
  guardWarnings.push('Ranking maiores/menores deveria usar strategy single_output_dual_rank_filter.');
}

if (hasBudgetComparison && !toArray(planoQuery.metricas).includes('tipo_variacao')) {
  guardWarnings.push('Comparação com orçamento detectada, mas tipo_variacao não está em metricas.');
}

if (
  grupoDreDetectado &&
  !(planoQuery.filtros_requeridos && planoQuery.filtros_requeridos.grupo_dre)
) {
  guardWarnings.push('Grupo DRE detectado semanticamente, mas filtro não ficou no plano_query.');
}

if (!hasExplicitTopN && planoQuery.sql_global_limit_allowed !== false) {
  guardWarnings.push('Plano sem Top N explícito deveria bloquear LIMIT global.');
}

if (hasExplicitTopN && planoQuery.limit) {
  guardWarnings.push('Top N explícito detectado, mas plano ainda contém limit global.');
}

// ============================================================
// Saída
// ============================================================

const semanticPlanGuard = {
  version: 'e8-n8n-c-semantic-plan-guard-v6-1-sem-limit-padrao-explicit-topn-safe',
  status: guardWarnings.length > 0 ? 'warning' : 'ok',
  actions: guardActions,
  warnings: guardWarnings,
  detected: {
    grupo_dre: grupoDreDetectado || null,
    dre_code: dreCodeDetectado || null,
    asks_account: semanticAsksAccount,
    asks_maiores_menores: asksMaioresMenores,
    has_budget_comparison: hasBudgetComparison,
    has_prior_period_comparison: hasPriorPeriodComparison,
    has_explicit_top_n: hasExplicitTopN,
    explicit_top_n: explicitTopN,
    explicit_top_n_matched_text: explicitTopNInfo.matched_text,
    semantic_periods_count: uniquePeriods.length
  },
  before: {
    modelo_query: planoOriginal.modelo_query || null,
    granularidade: planoOriginal.granularidade || [],
    dimensoes: planoOriginal.dimensoes || [],
    metricas: planoOriginal.metricas || [],
    limit: planoOriginal.limit || null
  },
  after: {
    modelo_query: planoQuery.modelo_query || null,
    granularidade: planoQuery.granularidade || [],
    dimensoes: planoQuery.dimensoes || [],
    metricas: planoQuery.metricas || [],
    limit: planoQuery.limit || null,
    explicit_top_n: planoQuery.explicit_top_n || null,
    ranking: planoQuery.ranking || null,
    sign_context: planoQuery.sign_context || null,
    limit_strategy: planoQuery.limit_strategy || null
  }
};

return [
  {
    json: {
      ...input,
      plano_query_original: planoOriginal,
      plano_query: planoQuery,
      modelo_query_planejado: planoQuery.modelo_query,
