const input = $json || {};

function getInputValue(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null && value !== '') {
      return value;
    }
  }

  return null;
}

function compactSql(value) {
  return String(value || '')
    .replace(/```sql/gi, '')
    .replace(/```/g, '')
    .replace(/--.*$/gm, '')
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .replace(/;\s*$/g, '')
    .trim();
}

function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function uniqueArray(values) {
  return [...new Set((values || []).filter(Boolean))];
}

function extractSql(data) {
  return compactSql(
    getInputValue(
      data.sql_query,
      data.sql,
      data.cleaned_sql,
      data.sql_gerada,
      data.sql_executed,
      data.query,
      data.body?.sql,
      data.body?.sql_query,
      ''
    )
  );
}

function extractReferencedTables(sqlText) {
  const tables = [];
  const re = /\b(?:from|join)\s+([`"a-zA-Z0-9_\.\-]+)/gi;

  let match;

  while ((match = re.exec(sqlText)) !== null) {
    const raw = String(match[1] || '')
      .replace(/[`"]/g, '')
      .trim();

    if (!raw || raw === '(') continue;

    tables.push(raw);
  }

  return uniqueArray(tables);
}

function classifyTableRef(tableName) {
  const table = String(tableName || '')
    .replace(/[`"]/g, '')
    .trim();

  if (!table) {
    return {
      allowed: true,
      kind: 'empty'
    };
  }

  // CTEs e aliases não possuem ponto.
  if (!table.includes('.')) {
    return {
      allowed: true,
      kind: 'cte_or_alias',
      table
    };
  }

  const allowedPrefix = 'dev_lakehouse.main_gold.';

  if (!table.startsWith(allowedPrefix)) {
    return {
      allowed: false,
      kind: 'physical_table',
      table,
      reason: 'Tabela física fora do schema autorizado.',
      expected_prefix: allowedPrefix
    };
  }

  const allowedTables = new Set([
    'dev_lakehouse.main_gold.gold_lancamentos_contabeis',
    'dev_lakehouse.main_gold.gold_rateios_lancamentos_contabeis',
    'dev_lakehouse.main_gold.gold_orcamento',
    'dev_lakehouse.main_gold.gold_rateios_orcamentos',
    'dev_lakehouse.main_gold.gold_plano_contas',
    'dev_lakehouse.main_gold.gold_centro_custo',
    'dev_lakehouse.main_gold.gold_unidade_negocio',
    'dev_lakehouse.main_gold.gold_mascaras_demonstrativos'
  ]);

  if (!allowedTables.has(table)) {
    return {
      allowed: false,
      kind: 'physical_table',
      table,
      reason: 'Tabela física não está na lista de tabelas Gold permitidas.'
    };
  }

  return {
    allowed: true,
    kind: 'physical_table',
    table
  };
}

const pergunta = String(
  getInputValue(
