  );
}

// ============================================================
// 4. Comandos proibidos
// ============================================================

const forbiddenCommands = [
  'insert',
  'update',
  'delete',
  'drop',
  'truncate',
  'alter',
  'create',
  'grant',
  'revoke',
  'comment',
  'vacuum',
  'analyze',
  'execute',
  'call',
  'copy',
  'merge',
  'replace',
  'upsert',
  'refresh',
  'materialized',
  'set',
  'reset',
  'show',
  'describe',
  'explain',
  'attach',
  'detach'
];

for (const command of forbiddenCommands) {
  const re = new RegExp(`\\b${command}\\b`, 'i');

  if (re.test(sql)) {
    pushError(
      'COMANDO_SQL_PROIBIDO',
      `Comando SQL bloqueado por segurança: ${command}.`,
      { command },
      'security'
    );
  }
}

// ============================================================
// 5. Placeholders ou padrões proibidos
// ============================================================

const forbiddenPatterns = [
  '{{ducklake_alias}}',
  'public.',
  'information_schema',
  'pg_catalog',
  'auth.',
  'storage.',
  'vault.',
  'extensions.',
  'supabase_',
  'ai_marca_unidade',
  'vw_'
];

for (const pattern of forbiddenPatterns) {
