      'PADRAO_SQL_PROIBIDO',
      `Objeto, termo ou padrão proibido detectado: ${pattern}`,
      { pattern },
      'security'
    );
  }
}

if (/\{\{|\}\}|<\s*sql|<\s*query|todo|placeholder/i.test(sql)) {
  pushError(
    'PLACEHOLDER_NAO_RESOLVIDO',
