    );
  }

  if (finalLimit > 5000) {
    pushError(
      'LIMIT_ACIMA_DO_LIMITE_SEGURANCA',
      'O LIMIT informado na SQL está acima do limite máximo de segurança.',
      {
        limit: finalLimit,
        limite_maximo_seguranca: 5000
      },
      'security'
    );
  }

  pushWarning(
    'LIMIT_PRESENTE_NA_SQL',
    'A SQL contém LIMIT explícito. Isso é permitido quando for semântico, por exemplo Top N solicitado pelo usuário.',
    {
      sql_limit: finalLimit,
      interface_limit: input.limit || null
    }
