// ============================================================
// Compactação segura exclusivamente para transporte
//
// - Preserva strings entre aspas simples.
// - Preserva identificadores entre aspas duplas.
// - Preserva aspas escapadas.
// - Remove comentários externos.
// - Remove apenas whitespace desnecessário fora de aspas.
// - Não troca colunas, aliases, filtros, datas ou operadores.
// ============================================================

function isIdentifierCharacter(character) {
  if (!character) {
    return false;
  }

  const code = character.charCodeAt(0);

  const isNumber =
    code >= 48 && code <= 57;

  const isUppercaseLetter =
    code >= 65 && code <= 90;

  const isLowercaseLetter =
    code >= 97 && code <= 122;

  return (
    isNumber ||
    isUppercaseLetter ||
    isLowercaseLetter ||
    character === '_' ||
    character === '$'
  );
}

function requiresSeparator(
  previousCharacter,
  nextCharacter
) {
  if (!previousCharacter || !nextCharacter) {
    return false;
  }

  // Evita juntar palavras, números, aliases e keywords.
  if (
    isIdentifierCharacter(previousCharacter) &&
    isIdentifierCharacter(nextCharacter)
  ) {
    return true;
  }

  // Exemplos:
  // DATE '2026-05-01'
  // THEN 'maiores'
  if (
    isIdentifierCharacter(previousCharacter) &&
    (
      nextCharacter === "'" ||
      nextCharacter === '"'
    )
  ) {
    return true;
  }

  // Exemplos:
  // 'realizado' AS tipo_metrica
  // "coluna" AS alias
  if (
    (
      previousCharacter === "'" ||
      previousCharacter === '"'
    ) &&
    isIdentifierCharacter(nextCharacter)
  ) {
    return true;
  }

  // Exemplos:
  // ) AS alias
  // ) SELECT
  if (
    previousCharacter === ')' &&
    isIdentifierCharacter(nextCharacter)
  ) {
    return true;
  }

  return false;
}

function compactSqlForTransport(sql) {
  const output = [];

  let state = 'normal';
  let pendingWhitespace = false;
  let index = 0;

  while (index < sql.length) {
    const character = sql[index];

    const nextCharacter =
      index + 1 < sql.length
        ? sql[index + 1]
        : '';

    // ========================================================
    // Fora de strings
    // ========================================================

    if (state === 'normal') {
      // Início de string.
      if (character === "'") {
        if (
          pendingWhitespace &&
          output.length > 0 &&
          requiresSeparator(
            output[output.length - 1],
            character
          )
        ) {
          output.push(' ');
        }

        pendingWhitespace = false;
        output.push(character);
        state = 'single_quote';
        index += 1;
        continue;
      }

      // Início de identificador delimitado.
      if (character === '"') {
        if (
          pendingWhitespace &&
          output.length > 0 &&
          requiresSeparator(
            output[output.length - 1],
            character
          )
        ) {
          output.push(' ');
        }

        pendingWhitespace = false;
        output.push(character);
        state = 'double_quote';
        index += 1;
        continue;
      }

      // Comentário de linha.
      if (
        character === '-' &&
        nextCharacter === '-'
      ) {
        pendingWhitespace = true;
        index += 2;

        while (
          index < sql.length &&
          sql[index] !== '\n' &&
          sql[index] !== '\r'
        ) {
          index += 1;
        }

        continue;
      }

      // Comentário de bloco.
      if (
        character === '/' &&
        nextCharacter === '*'
      ) {
        pendingWhitespace = true;
        index += 2;

        while (
          index + 1 < sql.length &&
          !(
            sql[index] === '*' &&
            sql[index + 1] === '/'
          )
        ) {
          index += 1;
        }

        if (index + 1 < sql.length) {
          index += 2;
        }

        continue;
      }

      // Whitespace externo.
      if (
        character === ' ' ||
        character === '\t' ||
        character === '\n' ||
        character === '\r' ||
        character === '\f'
      ) {
        pendingWhitespace = true;
        index += 1;
        continue;
      }

      // Recoloca espaço somente quando necessário
      // para impedir a junção de tokens.
      if (
        pendingWhitespace &&
        output.length > 0 &&
        requiresSeparator(
          output[output.length - 1],
          character
        )
      ) {
        output.push(' ');
      }

      pendingWhitespace = false;
      output.push(character);
      index += 1;
      continue;
    }

    // ========================================================
    // Dentro de string com aspas simples
    // ========================================================

    if (state === 'single_quote') {
      output.push(character);

      if (character === "'") {
        // Escape SQL: ''
        if (nextCharacter === "'") {
          output.push(nextCharacter);
          index += 2;
          continue;
        }

        state = 'normal';
      }

      index += 1;
      continue;
    }

    // ========================================================
    // Dentro de identificador com aspas duplas
    // ========================================================

    if (state === 'double_quote') {
      output.push(character);

      if (character === '"') {
        // Escape SQL: ""
        if (nextCharacter === '"') {
          output.push(nextCharacter);
          index += 2;
          continue;
        }

        state = 'normal';
      }

      index += 1;
      continue;
    }
  }

  if (state !== 'normal') {
    throw new Error(
      'Não foi possível compactar a SQL: aspas não foram encerradas.'
    );
  }

  return output.join('').trim();
}

