    json: {
      success: Boolean(pick(payload, ['success', 'result.success', 'output.success'], true)),
      query_id: pick(payload, ['query_id', 'queryId', 'id', 'result.query_id', 'output.query_id'], null),
      execution_time_ms: pick(payload, [
        'execution_time_ms',
        'executionTimeMs',
        'elapsed_ms',
        'result.execution_time_ms',
        'output.execution_time_ms'
      ], null),
      row_count: rowCount,
      columns,
      data,
      truncated: Boolean(pick(payload, ['truncated', 'result.truncated', 'output.truncated'], false)),
      error_message: pick(payload, ['error_message', 'error', 'message', 'result.error_message', 'output.error_message'], null),

      pergunta: context.pergunta || '',
      sql: context.sql || context.sql_query || '',
      agent_version: context.agent_version || 'v2.0.6.5-router-watson-flow',
      detected_intent: context.detected_intent || 'execucao_sql',
      executor_mode: 'watson_flow',
      executor_version: 'v2.0.6.5',
      raw_result: payload
    }
  }
];

const input = $input.first().json || {};

return [
  {
    json: {
      success: false,
      query_id: null,
      execution_time_ms: null,
      row_count: 0,
      columns: [],
      data: [],
      truncated: false,
      error_message: input.error_message || 'SQL reprovada na validação de segurança antes da execução no Watson Flow.',
      pergunta: input.pergunta || '',
      sql: input.sql || '',
      executor_mode: 'watson_flow',
      executor_version: 'v2.0.6.5'
    }
  }
];

// ============================================================
// CODE - MONTAR RELATÓRIO EXECUTIVO
// Agente SQL Financeiro DuckLake
// v2.0.7.1-relatorio-executivo-backend-metadata-intencao
//
// Onde usar:
// Inserir este node depois de:
//   Code - Normalizar Resultado Flow
// e antes de:
//   Respond to Webhook
//
// Objetivo:
// - Montar o relatório executivo no backend/n8n.
// - Não deixar a interface interpretar regras financeiras.
// - A interface deve apenas renderizar response.relatorio_executivo
//   e/ou response.relatorio_executivo_markdown.
//
// Ajuste v2.0.7.1:
// - Corrige metadado do markdown quando o modo de execução retorna
//   detected_intent = execucao_sql.
// - O relatório passa a mostrar a intenção analítica inferida
//   pelo resultado, por exemplo: estouro_orcamento.
// - Validação passa a mostrar "execução aprovada" quando success = true
//   e não houver validacao_offline.status.
//
// Entrada esperada:
// - success
// - pergunta
// - sql
// - columns
// - data
// - row_count
// - query_id
// - execution_time_ms
// - detected_intent / intencao, quando disponível
//
// Saída:
// - preserva todos os campos originais
// - adiciona:
//   relatorio_executivo
//   relatorio_executivo_markdown
//   executive_summary
// ============================================================

const input = $json || {};

// ============================================================
// Helpers básicos
// ============================================================

function asArray(value) {
  return Array.isArray(value) ? value : [];
}

function normalizeText(value) {
  return String(value ?? "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizeColumn(column) {
  return normalizeText(column);
}

function hasColumns(columns, required) {
  const available = new Set(asArray(columns).map(normalizeColumn));
  return required.every((column) => available.has(normalizeColumn(column)));
}

function hasAnyColumn(columns, candidates) {
  const available = new Set(asArray(columns).map(normalizeColumn));
  return candidates.some((column) => available.has(normalizeColumn(column)));
}

function getValue(row, column) {
  if (!row || typeof row !== "object") return null;

  if (Object.prototype.hasOwnProperty.call(row, column)) {
    return row[column];
  }

  const lower = String(column).toLowerCase();
  if (Object.prototype.hasOwnProperty.call(row, lower)) {
    return row[lower];
  }

  const foundKey = Object.keys(row).find((key) => normalizeColumn(key) === normalizeColumn(column));
  return foundKey ? row[foundKey] : null;
}

function text(row, column, fallback = "não informado") {
  const raw = getValue(row, column);
  return raw === null || raw === undefined || raw === "" ? fallback : String(raw);
}

function numberValue(row, column) {
  const raw = getValue(row, column);

  if (typeof raw === "number" && Number.isFinite(raw)) {
    return raw;
  }

  if (typeof raw === "string") {
    const trimmed = raw.trim();

    if (!trimmed) return 0;

    const parsedBr = Number(trimmed.replace(/\./g, "").replace(",", "."));
    if (Number.isFinite(parsedBr)) return parsedBr;

    const parsed = Number(trimmed);
    if (Number.isFinite(parsed)) return parsed;
  }

  return 0;
}

function byNumber(data, column, direction = "desc") {
  return [...asArray(data)].sort((a, b) => {
    const diff = numberValue(a, column) - numberValue(b, column);
    return direction === "asc" ? diff : -diff;
  });
}

function topLabels(rows, labelColumn, limit = 3) {
  return asArray(rows)
    .slice(0, limit)
    .map((row) => text(row, labelColumn, ""))
    .filter(Boolean);
}

function uniqueLabels(rows, labelColumn, limit = 5) {
  const labels = asArray(rows)
    .map((row) => text(row, labelColumn, ""))
    .filter(Boolean);

  return [...new Set(labels)].slice(0, limit);
}

function formatNumber(value, decimals = 2) {
  const n = Number(value);

  if (!Number.isFinite(n)) {
    return "0,00";
  }

  return n.toLocaleString("pt-BR", {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals
  });
}

function formatBRL(value) {
  const n = Number(value);

  if (!Number.isFinite(n)) {
    return "R$ 0,00";
  }

  return n.toLocaleString("pt-BR", {
    style: "currency",
    currency: "BRL",
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
}

function formatPercent(value) {
  const n = Number(value);

  if (!Number.isFinite(n)) {
    return "0,00%";
  }

  return `${formatNumber(n, 2)}%`;
}

function isMetricColumn(column) {
  const normalized = normalizeColumn(column);

  const blockedDimensionColumns = new Set([
    "conta",
    "conta_contabil",
    "nk_conta_contabil",
    "grupo_dre",
    "subgrupo",
    "marca",
    "setor",
    "centro_custo",
    "tipo_impacto",
    "tipo_variacao",
    "status_orcamento",
    "status_rol",
    "query_id"
  ]);

  if (blockedDimensionColumns.has(normalized)) {
    return false;
  }

  return (
    normalized.endsWith("_rs") ||
    normalized.endsWith("_perc") ||
    normalized.startsWith("perc_") ||
    normalized.startsWith("ranking_") ||
    normalized.includes("variancia") ||
    normalized.includes("realizado") ||
    normalized.includes("orcado") ||
    normalized.includes("opex") ||
    normalized.includes("rol") ||
    normalized.includes("resultado") ||
    normalized.includes("margem") ||
    normalized.includes("lucro") ||
    normalized.includes("cmv")
  );
}

// ============================================================
// Captura de contexto
// ============================================================

const columns = asArray(input.columns || input.raw_result?.columns);
const data = asArray(input.data || input.raw_result?.data);
const pergunta = input.pergunta || input.question || "";
const sql = input.sql || input.query_para_copiar || input.query || "";

const detectedIntentRaw =
  input.intencao ||
  input.detected_intent ||
  input.metadata?.detected_intent ||
  input.modelo_query_planejado ||
  input.modelo_query ||
  "";

const detectedIntent = normalizeText(detectedIntentRaw);
const perguntaNorm = normalizeText(pergunta);

function inferIntent() {
  // Prioridade: estrutura de colunas, porque ela reflete o resultado executado.
  if (
    hasColumns(columns, [
      "tipo_impacto",
      "grupo_dre",
      "subgrupo",
      "conta_contabil",
      "realizado_rs",
      "orcado_rs",
      "variancia_rs",
      "variancia_perc"
    ]) &&
    hasAnyColumn(columns, ["ranking_geral", "ranking_no_tipo"])
  ) {
    return "estouro_orcamento";
  }

  if (
    hasColumns(columns, [
      "grupo_dre",
      "realizado_rs",
      "orcado_rs",
      "variancia_rs",
      "variancia_perc",
      "tipo_variacao"
    ])
  ) {
    return "orcado_vs_realizado";
  }

  if (
    hasColumns(columns, [
      "marca",
      "rol_rs",
      "cmv_rs",
      "lucro_bruto_rs",
      "margem_contribuicao_rs",
      "opex_rs",
      "resultado_liquido_rs",
      "resultado_perc_rol",
      "ranking_por_valor",
      "ranking_por_perc_rol"
    ])
  ) {
    return "comparativo_marcas";
  }

  if (
    hasColumns(columns, [
      "centro_custo",
      "opex_realizado_rs",
      "opex_orcado_rs",
      "variancia_rs",
      "perc_orcado_consumido",
      "status_orcamento",
      "ranking_desempenho"
    ])
  ) {
    return "opex_por_centro_custo";
  }

  if (
    hasColumns(columns, [
      "marca",
      "setor",
      "opex_rs",
      "total_opex_marca_rs",
      "perc_representatividade",
      "ranking_na_marca"
    ])
  ) {
    return "impacto_setor_marca";
  }

  // Fallback pela pergunta.
  if (perguntaNorm.includes("estouro")) return "estouro_orcamento";
  if (perguntaNorm.includes("orcado") || perguntaNorm.includes("orcamento") || perguntaNorm.includes("realizado")) return "orcado_vs_realizado";
  if (perguntaNorm.includes("marca") || perguntaNorm.includes("rol")) return "comparativo_marcas";
  if (perguntaNorm.includes("centro de custo") || perguntaNorm.includes("centros de custo")) return "opex_por_centro_custo";
  if (perguntaNorm.includes("setor") && perguntaNorm.includes("marca")) return "impacto_setor_marca";

  return detectedIntent || "consulta_geral";
}

const reportIntent = inferIntent();

function metadataIntent() {
  const raw = String(detectedIntentRaw || "").trim();

  // Quando o endpoint é chamado em modo executar_sql, o detected_intent operacional
  // vem como execucao_sql. Para o relatório executivo, isso não é útil.
  // O correto é mostrar a intenção analítica inferida a partir do resultado.
  if (!raw || normalizeText(raw) === "execucao_sql") {
    return reportIntent || "não informada";
  }

  return raw;
}

function metadataValidation() {
  const validation =
    input.validacao_offline?.status ||
    input.validacao ||
    input.validation_status ||
    "";

  if (validation) {
    return validation;
  }

  if (input.success === true) {
    return "execução aprovada";
  }

  if (input.success === false) {
    return "execução com erro";
  }

  return "não informada";
}

// ============================================================
// Montadores de relatório por intenção
// ============================================================

function emptyOrErrorReport() {
  if (input.success === false) {
    return {
      title: "Resumo executivo",
      paragraphs: [
        "A execução não retornou resultado válido para análise executiva.",
        input.error_message ? `Mensagem de erro: ${input.error_message}` : "Não há mensagem de erro detalhada disponível."
      ],
      highlights: [],
      warnings: ["Verifique a SQL, os filtros da consulta e o retorno do Watson Flow."]
    };
  }

  return {
    title: "Resumo executivo",
    paragraphs: ["Nenhum dado foi carregado para gerar uma interpretação executiva."],
    highlights: [],
    warnings: ["Carregue um resultado do Watson antes de gerar o resumo."]
  };
}

function genericSummary() {
  const firstRow = data[0];

  const numericColumns = columns.filter((column) =>
    isMetricColumn(column) && data.some((row) => Math.abs(numberValue(row, column)) > 0)
  );

  const topNumericHighlights = numericColumns.slice(0, 3).map((column) => {
    const topRow = byNumber(data, column, "desc")[0];
    return `${column}: maior valor observado foi ${formatNumber(numberValue(topRow, column))}.`;
  });

  return {
    title: "Resumo executivo",
    paragraphs: [
      `Com base no resultado carregado, a tabela possui ${data.length} linhas e ${columns.length} colunas.`,
      "Não foi identificado um modelo executivo específico para esta estrutura de dados; por isso, a leitura abaixo destaca apenas métricas numéricas reconhecidas."
    ],
    highlights: [
      firstRow
        ? `A primeira linha traz ${columns
            .slice(0, 4)
            .map((column) => `${column}: ${text(firstRow, column)}`)
            .join(", ")}.`
        : "Nenhuma linha disponível para análise.",
      ...(topNumericHighlights.length
        ? topNumericHighlights
        : ["Nenhuma métrica numérica relevante foi identificada para destaque automático."])
    ],
    warnings: ["Evite interpretar causalidade sem validar o contexto de negócio e os filtros da consulta."]
  };
}

function accountOverrunSummary() {
  const main = data[0];
  const negativeRows = data.filter((row) => numberValue(row, "variancia_rs") < 0);
  const rankedOverruns = byNumber(negativeRows.length ? negativeRows : data, "variancia_rs", "asc");
  const topAccounts = topLabels(rankedOverruns, "conta_contabil", 5);
  const topGroups = uniqueLabels(rankedOverruns, "grupo_dre", 5);
  const rankingColumn = hasAnyColumn(columns, ["ranking_geral"]) ? "ranking_geral" : "ranking_no_tipo";

  const hasRevenueInResult = data.some((row) => normalizeText(text(row, "grupo_dre", "")).startsWith("01 -"));

  const warnings = [
    "Receita de Vendas não deve entrar nesta leitura de estouro de orçamento; receita abaixo do orçamento pertence à análise de variação geral do resultado."
  ];

  if (hasRevenueInResult) {
    warnings.unshift("Atenção: foi identificada Receita de Vendas no resultado. Isso deve ser revisado, pois estouro de orçamento deve excluir Receita.");
  }

  return {
    title: "Resumo executivo",
    paragraphs: [
      "A análise identifica os maiores estouros de orçamento do mês, excluindo Receita de Vendas e priorizando as maiores variações negativas em ranking global.",
      `O maior estouro foi na conta ${text(main, "conta_contabil")}, no grupo ${text(main, "grupo_dre")} / ${text(main, "subgrupo")}, com variação de ${formatBRL(numberValue(main, "variancia_rs"))} frente ao orçamento.`
    ],
    highlights: [
      `Contas com maior estouro: ${topAccounts.join(", ") || "não identificadas"}.`,
      `Principais grupos DRE afetados: ${topGroups.join(", ") || "não identificados"}.`,
      `Tipo de impacto do maior estouro: ${text(main, "tipo_impacto", "não informado")}.`,
      `Ranking utilizado: ${rankingColumn}.`
    ],
    warnings
  };
}

function dreBudgetSummary() {
  const main = data[0];
  const negative = byNumber(data, "variancia_rs", "asc")[0];
  const positive = byNumber(data, "variancia_rs", "desc")[0];

  return {
    title: "Resumo executivo",
    paragraphs: [
      `Com base no resultado carregado, a principal variação observada foi em ${text(main, "grupo_dre")}, com variação de ${formatBRL(numberValue(main, "variancia_rs"))}, equivalente a ${formatPercent(numberValue(main, "variancia_perc"))} frente ao orçamento.`,
      "A leitura executiva prioriza as maiores variações absolutas, separando efeitos negativos e positivos no resultado."
    ],
    highlights: [
      `Maior variação negativa: ${text(negative, "grupo_dre")} com ${formatBRL(numberValue(negative, "variancia_rs"))}.`,
      `Maior variação positiva: ${text(positive, "grupo_dre")} com ${formatBRL(numberValue(positive, "variancia_rs"))}.`,
      `${text(main, "tipo_variacao", "Tipo de variação não informado")} aparece como classificação do principal impacto.`
    ]
  };
}

function brandResultSummary() {
  const bestByValue = byNumber(data, "resultado_liquido_rs", "desc")[0];

  const validPercentRows = data.filter((row) => {
    const status = normalizeText(text(row, "status_rol", ""));
    return !status || status.includes("elegivel");
  });

  const bestByPercent = byNumber(validPercentRows.length ? validPercentRows : data, "resultado_perc_rol", "desc")[0];

  const attentionRows = data.filter((row) => {
    const status = normalizeText(text(row, "status_rol", ""));
    return (
      status.includes("fora") ||
      status.includes("baixo") ||
      status.includes("zero") ||
      status.includes("negativo") ||
      status.includes("negativa")
    );
  });

  return {
    title: "Resumo executivo",
    paragraphs: [
      `O melhor desempenho em valor aparece em ${text(bestByValue, "marca")}, com resultado líquido de ${formatBRL(numberValue(bestByValue, "resultado_liquido_rs"))}.`,
      `Em percentual sobre ROL, o destaque é ${text(bestByPercent, "marca")}, com ${formatPercent(numberValue(bestByPercent, "resultado_perc_rol"))}.`
    ],
    highlights: [
      "O ranking por valor mostra quem mais contribuiu em reais; o ranking percentual mostra eficiência relativa sobre a ROL.",
      attentionRows.length
        ? `Marcas fora do ranking percentual ou com ROL que exige atenção: ${topLabels(attentionRows, "marca").join(", ")}.`
        : "Não foram identificadas marcas fora do ranking percentual por restrição de ROL.",
      `Margem de contribuição do destaque em valor: ${formatBRL(numberValue(bestByValue, "margem_contribuicao_rs"))}.`
    ]
  };
}

function costCenterSummary() {
  const best = byNumber(data, "ranking_desempenho", "asc").slice(0, 3);
  const worst = byNumber(data, "ranking_desempenho", "desc").slice(0, 3);
  const withoutBudget = data.filter(
    (row) => numberValue(row, "opex_orcado_rs") === 0 && numberValue(row, "opex_realizado_rs") !== 0
  );

  return {
    title: "Resumo executivo",
    paragraphs: [
      "A leitura de centros de custo compara consumo realizado contra orçamento e prioriza o ranking de desempenho.",
      "Variância positiva indica economia frente ao orçamento; variância negativa indica estouro."
    ],
    highlights: [
      `Melhores centros de custo: ${topLabels(best, "centro_custo").join(", ") || "não identificados"}.`,
      `Piores centros de custo: ${topLabels(worst, "centro_custo").join(", ") || "não identificados"}.`,
      withoutBudget.length
        ? `Centros sem orçamento com gasto realizado: ${topLabels(withoutBudget, "centro_custo").join(", ")}.`
        : "Não foram identificados centros sem orçamento com gasto realizado."
    ]
  };
}

function opexByBrandSectorSummary() {
  const brands = [...new Set(data.map((row) => text(row, "marca", "")).filter(Boolean))];

  const topByBrand = brands.map((brand) => {
    const rows = data.filter((row) => text(row, "marca", "") === brand);
    return byNumber(rows, "perc_representatividade", "desc")[0] ?? rows[0];
  });

  const concentrated = topByBrand.filter((row) => numberValue(row, "perc_representatividade") > 50);
  const sectorCounts = new Map();

  for (const row of topByBrand) {
    const sector = text(row, "setor", "");
    if (sector) {
      sectorCounts.set(sector, (sectorCounts.get(sector) ?? 0) + 1);
    }
  }

  const recurring = [...sectorCounts.entries()]
    .sort((a, b) => b[1] - a[1])
    .slice(0, 3)
    .map(([sector]) => sector);

  return {
    title: "Resumo executivo",
    paragraphs: [
      "A análise mostra o peso de cada setor no OPEX de sua respectiva marca.",
      "Maior representatividade significa maior concentração do gasto de OPEX dentro da marca."
    ],
    highlights: [
      `Principais setores por marca: ${topByBrand.map((row) => `${text(row, "marca")}: ${text(row, "setor")}`).join("; ")}.`,
      concentrated.length
        ? `Marcas com setor acima de 50% do OPEX: ${concentrated.map((row) => `${text(row, "marca")} (${text(row, "setor")})`).join(", ")}.`
        : "Nenhuma marca apresentou setor concentrando mais de 50% do OPEX.",
      `Setores recorrentes entre os maiores impactos: ${recurring.join(", ") || "não identificados"}.`
    ]
  };
}

function buildExecutiveReport() {
  if (!data.length || !columns.length || input.success === false) {
    return emptyOrErrorReport();
  }

  if (reportIntent === "estouro_orcamento") {
    return accountOverrunSummary();
  }

  if (reportIntent === "orcado_vs_realizado") {
    return dreBudgetSummary();
  }

  if (
    reportIntent === "comparativo_marcas" ||
    reportIntent === "resultado_por_marca" ||
    reportIntent === "resultado_mensal_por_marca"
  ) {
    return brandResultSummary();
  }

  if (reportIntent === "opex_por_centro_custo") {
    return costCenterSummary();
  }

  if (reportIntent === "impacto_setor_marca") {
    return opexByBrandSectorSummary();
  }

  return genericSummary();
}

// ============================================================
// Markdown para exportação/cópia
// ============================================================

function buildMarkdown(report) {
  const metadataLines = [
    `- Versão: ${input.agent_version || input.executor_version || "não informada"}`,
    `- Intenção: ${metadataIntent()}`,
    `- Validação: ${metadataValidation()}`,
    `- Query ID: ${input.query_id || "não informado"}`,
    `- Tempo: ${input.execution_time_ms === null || input.execution_time_ms === undefined ? "não informado" : `${input.execution_time_ms} ms`}`,
    `- Linhas: ${input.row_count ?? data.length}`
  ];

  const paragraphs = asArray(report.paragraphs).join("\n\n");
  const highlights = asArray(report.highlights).map((item) => `- ${item}`).join("\n");
  const warnings = asArray(report.warnings).length
    ? `\n## Observações e alertas\n${asArray(report.warnings).map((item) => `- ${item}`).join("\n")}\n`
    : "";

  const sqlBlock = sql
    ? `\n## SQL\n\`\`\`sql\n${sql}\n\`\`\`\n`
    : "";

  return [
    "# Agente SQL Financeiro DuckLake — Relatório Executivo",
    "",
    "## Pergunta",
    pergunta || "Pergunta não informada",
    "",
    "## Metadados",
    ...metadataLines,
    "",
    "## Resumo executivo",
    paragraphs || "Resumo não disponível.",
    "",
    "## Destaques",
    highlights || "- Nenhum destaque disponível.",
    warnings,
    sqlBlock,
    "## Observação",
    "Resultado completo disponível na tabela da interface."
  ]
    .join("\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

const relatorioExecutivo = buildExecutiveReport();
const relatorioExecutivoMarkdown = buildMarkdown(relatorioExecutivo);

return [
  {
    json: {
      ...input,

      relatorio_executivo: {
        ...relatorioExecutivo,
        intent: reportIntent,
        generated_by: "n8n",
        version: "v2.0.7.1-relatorio-executivo-backend-metadata-intencao"
      },

      executive_summary: {
        ...relatorioExecutivo,
        intent: reportIntent,
        generated_by: "n8n",
        version: "v2.0.7.1-relatorio-executivo-backend-metadata-intencao"
      },

