const questionHash = fnv1a([
  questionNormalized,
  intent,
  periodKey,
  rulesVersion,
  schemaVersionCache,
  promptVersion,
].join('|'));

return [
  {
    json: {
      ...$json,
      question_original: questionOriginal,
