// ============================================================
// CODE - CRIAR RUN CONTEXT
// Agente SQL Financeiro DuckLake
// Objetivo:
// - Padronizar contexto de execução
// - Preservar usuário/perfil vindo do Next.js
// - Criar run_id rastreável
// - Preparar auditoria/observabilidade
//
// Importante:
// - NÃO valida token aqui.
// - O token já é validado pelo Header Auth do Webhook.
// - Não usa process.env, porque isso quebra no Code node do n8n.
// ============================================================

function isObject(value) {
  return value && typeof value === 'object' && !Array.isArray(value);
}

function cleanString(value, fallback = '') {
  if (value === undefined || value === null) return fallback;
  return String(value).trim();
}

function createId(prefix) {
  return `${prefix}_${Date.now()}_${Math.random().toString(36).slice(2, 14)}`;
}

function getHeader(headers, name) {
  if (!isObject(headers)) return '';

  const target = String(name || '').toLowerCase();

  for (const key of Object.keys(headers)) {
    if (String(key).toLowerCase() === target) {
      return cleanString(headers[key]);
    }
  }

  return '';
}

function sanitizeHeaders(headers) {
  if (!isObject(headers)) return {};

  const sanitized = { ...headers };

  for (const key of Object.keys(sanitized)) {
    if (String(key).toLowerCase() === 'x-agent-internal-token') {
      sanitized[key] = '[REDACTED]';
    }
  }

  return sanitized;
}

const items = $input.all();

return items.map((item) => {
  const input = item.json || {};
  const body = isObject(input.body) ? input.body : input;
  const headers = isObject(input.headers) ? input.headers : {};

  const pergunta =
    cleanString(body.pergunta) ||
    cleanString(input.pergunta);

  const options =
    isObject(body.options)
      ? body.options
      : isObject(input.options)
        ? input.options
        : {};

  const requestId =
    cleanString(body.request_id) ||
    cleanString(input.request_id) ||
    createId('req');

  const runId =
    cleanString(body.run_id) ||
    cleanString(input.run_id) ||
    createId('run');

  const userId =
    cleanString(body.user_id) ||
    cleanString(input.user_id) ||
    'anonymous';

  const userEmail =
    cleanString(body.user_email) ||
    cleanString(input.user_email) ||
    '';

  const userName =
    cleanString(body.user_name) ||
    cleanString(input.user_name) ||
    '';

  const userProfile =
    cleanString(body.user_profile) ||
    cleanString(input.user_profile) ||
    'anonymous';

  const authSource =
    cleanString(body.auth_source) ||
    cleanString(input.auth_source) ||
    'unknown';

  const forwardedFor = getHeader(headers, 'x-forwarded-for');
  const realIp = getHeader(headers, 'x-real-ip');

  const ipAddress =
    cleanString(forwardedFor.split(',')[0]) ||
    cleanString(realIp) ||
    cleanString(input.ip) ||
    'unknown';

  const startedAt =
    cleanString(body.started_at) ||
    cleanString(input.started_at) ||
    new Date().toISOString();

  const runContext = {
    run_id: runId,
    request_id: requestId,
    user_id: userId,
    user_email: userEmail,
    user_name: userName,
    user_profile: userProfile,
    auth_source: authSource,
    ip_address: ipAddress,
    started_at: startedAt,
    source: 'nextjs_interface'
  };

  const sanitizedHeaders = sanitizeHeaders(headers);

  return {
    json: {
      ...input,

      headers: sanitizedHeaders,

      pergunta,
      options,

      run_id: runId,
      request_id: requestId,
      user_id: userId,
      user_email: userEmail,
      user_name: userName,
      user_profile: userProfile,
      auth_source: authSource,
      ip_address: ipAddress,
      started_at: startedAt,

      run_context: runContext,

      body: {
        ...body,
        pergunta,
        options,
        run_id: runId,
        request_id: requestId,
        user_id: userId,
        user_email: userEmail,
        user_name: userName,
        user_profile: userProfile,
        auth_source: authSource,
        ip_address: ipAddress,
        started_at: startedAt,
        run_context: runContext
      }
    }
  };
});

// ============================================================
// CODE - ANEXAR USO LLM
// Objetivo:
// Anexar métricas de uso do Gemini ao payload final retornado
// para o Next.js, sem expor segredos.
// ============================================================

const input = $json || {};

function toNumberOrNull(value) {
  if (value === null || value === undefined || value === '') {
    return null;
  }

  const numberValue = Number(value);

  if (!Number.isFinite(numberValue) || numberValue < 0) {
    return null;
  }

  return Math.trunc(numberValue);
}

function getNodeJsonSafe(nodeName) {
  try {
    return $(nodeName).first().json || {};
  } catch (error) {
    return {};
  }
}

function pickUsageMetadata(payload) {
  if (!payload || typeof payload !== 'object') {
    return null;
  }

  return (
    payload.usageMetadata ||
    payload.raw?.usageMetadata ||
    payload.response?.usageMetadata ||
    payload.data?.usageMetadata ||
    payload.body?.usageMetadata ||
    null
  );
}

const cache = input.cache || {};
const isCacheHit =
  cache.hit === true ||
  cache.status === 'hit' ||
  cache.status === 'hit_found' ||
  cache.status === 'hit_validated' ||
  cache.source === 'cache' ||
  cache.source === 'sql_generation_cache';

// Quando veio do cache, o Gemini não foi chamado para gerar a SQL.
if (isCacheHit) {
  const llmUsage = {
    provider: 'gemini',
    model: 'gemini-2.5-flash',
    prompt_tokens: 0,
    completion_tokens: 0,
    total_tokens: 0,
    source: 'sql_cache'
  };

  return [
    {
      json: {
        ...input,
        llm_usage: llmUsage,
        entrega_watson: {
          ...(input.entrega_watson || {}),
          llm_usage: llmUsage,
          cache: {
            ...(input.entrega_watson?.cache || {}),
            ...(input.cache || {})
          }
        }
      }
    }
  ];
}

// Caminho normal: tenta capturar usageMetadata do retorno do Gemini.
// Primeiro tenta no próprio input, pois Code - Limpar SQL preserva ...respostaGemini.
// Depois tenta buscar diretamente no node Gemini - Gerar SQL.
const geminiNode = getNodeJsonSafe('Gemini - Gerar SQL');

const usageMetadata =
  pickUsageMetadata(input) ||
  pickUsageMetadata(geminiNode);

const promptTokens = toNumberOrNull(
  usageMetadata?.promptTokenCount ??
  usageMetadata?.prompt_tokens ??
  usageMetadata?.promptTokens
);

const completionTokens = toNumberOrNull(
  usageMetadata?.candidatesTokenCount ??
  usageMetadata?.completion_tokens ??
  usageMetadata?.completionTokens
);

let totalTokens = toNumberOrNull(
  usageMetadata?.totalTokenCount ??
  usageMetadata?.total_tokens ??
  usageMetadata?.totalTokens
);

if (
  totalTokens === null &&
  promptTokens !== null &&
  completionTokens !== null
) {
  totalTokens = promptTokens + completionTokens;
}

const model =
  input.modelVersion ||
  geminiNode.modelVersion ||
  input.llm_model ||
  'gemini-2.5-flash';

const llmUsage = {
  provider: 'gemini',
  model,
  prompt_tokens: promptTokens,
  completion_tokens: completionTokens,
  total_tokens: totalTokens,
  source: usageMetadata ? 'gemini_usage_metadata' : 'not_available'
};

return [
  {
    json: {
      ...input,
      llm_usage: llmUsage,
      entrega_watson: {
        ...(input.entrega_watson || {}),
        llm_usage: llmUsage
      }
    }
  }
];

// ============================================================
// CODE - MONTAR SEMANTIC REQUEST OBSERVADO
// E8-N8N-A — modo observação
//
// Objetivo:
// - Criar um semantic_request_observado determinístico.
// - Não gerar SQL.
// - Não alterar prompt.
// - Não alterar cache.
