const items = $input.all();
const input = items[0]?.json || {};

function normalizeText(value) {
  return String(value || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[?!.;,:\"'`´]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizeLoose(value) {
  return String(value || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^\w\s/-]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function uniqueArray(values) {
  return [...new Set((values || []).filter(Boolean))];
}

function toArray(value) {
  if (!value) return [];
  if (Array.isArray(value)) return value;

  if (typeof value === "string") {
    try {
      const parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
      return [];
    }
  }

  return [];
}

function includesAny(text, terms) {
  const normalized = normalizeText(text);
  return (terms || []).some((term) => normalized.includes(normalizeText(term)));
}

function pad2(value) {
  return String(value).padStart(2, "0");
}

function nextMonth(year, month) {
  if (month === 12) {
    return { year: year + 1, month: 1 };
  }

  return { year, month: month + 1 };
}

function buildMonthPeriod(source, year, month, rawText) {
  const next = nextMonth(year, month);

  return {
    label: `${source}_${year}_${pad2(month)}`,
    source,
    start: `${year}-${pad2(month)}-01`,
    end_exclusive: `${next.year}-${pad2(next.month)}-01`,
    year,
    month,
    is_accumulated: false,
    raw_text: rawText
  };
}

function inferSource(rawText, fullText) {
  const raw = normalizeText(rawText);
  const full = normalizeText(fullText);

  if (includesAny(raw, ["orcado", "orcamento", "budget"])) {
    return "orcado";
  }

  if (includesAny(raw, ["realizado", "executado"])) {
    return "realizado";
  }

  if (includesAny(full, ["orcado", "orcamento", "budget"])) {
    return "realizado";
  }

  return "unknown";
}

function detectDimensions(text, inputData) {
