function detectMetrics(text, detectedIntent) {
  const metrics = [];

  if (includesAny(text, ["opex", "despesas operacionais", "gastos operacionais"])) {
    metrics.push("opex");
  }

  if (includesAny(text, ["gastos com pessoal", "despesas com pessoal", "09 - gastos com pessoal"])) {
