  }

  if (includesAny(text, ["cmv", "custo da mercadoria", "05 - cmv"])) {
    metrics.push("cmv");
  }

  if (includesAny(text, ["rol", "receita operacional liquida", "receita operacional líquida"])) {
    metrics.push("rol");
  }

  if (includesAny(text, ["receita", "faturamento", "vendas"])) {
    metrics.push("receita");
  }

  if (includesAny(text, ["resultado liquido", "resultado líquido", "resultado"])) {
    metrics.push("resultado_liquido");
  }

  if (includesAny(text, ["orcado", "orçado", "orcamento", "orçamento", "budget"])) {
    metrics.push("total_orcado");
  }

  if (includesAny(text, ["realizado", "executado"])) {
    metrics.push("total_realizado");
  }

  if (
    includesAny(text, [
      "variacao",
      "variação",
      "variancia",
      "variância",
      "diferenca",
      "diferença",
      "desvio",
      "comparado",
      "comparando"
    ])
  ) {
