  }

  if (detectedIntent === "orcado_vs_realizado" || detectedIntent === "estouro_orcamento") {
    metrics.push("total_realizado", "total_orcado", "variancia");
  }

  if (detectedIntent === "resultado_por_marca") {
    metrics.push("resultado_liquido");
  }

  return uniqueArray(metrics);
}

function detectDreFilters(text, dreRows) {
  const filters = [];
  const normalizedQuestion = normalizeLoose(text);

  for (const row of dreRows || []) {
    const code = String(row.dre_code || "").trim();
    const nivel = String(row.nivel_1_bi || "").trim();
    const hint = String(row.sql_filter_hint || "").trim();

    const normalizedCode = normalizeLoose(code);
    const normalizedNivel = normalizeLoose(nivel);

    const codeMatches =
      normalizedCode &&
      (
        normalizedQuestion.includes(` ${normalizedCode} `) ||
        normalizedQuestion.startsWith(`${normalizedCode} `) ||
        normalizedQuestion.includes(`${normalizedCode} -`) ||
        normalizedQuestion.includes(` ${normalizedCode}-`)
      );

    const nivelMatches =
      normalizedNivel &&
      normalizedQuestion.includes(normalizedNivel);

    if (codeMatches || nivelMatches) {
      filters.push({
        type: "grupo_dre",
        code,
        value: nivel || code,
        canonical_value: nivel || code,
        sql_filter_hint: hint || null
      });
    }
  }

  if (
    filters.length === 0 &&
    includesAny(text, ["09 - gastos com pessoal", "gastos com pessoal"])
  ) {
    filters.push({
      type: "grupo_dre",
      code: "09",
      value: "09 - GASTOS COM PESSOAL",
      canonical_value: "09 - GASTOS COM PESSOAL",
      sql_filter_hint: "pc.nivel_1_bi LIKE '09 -%'"
    });
  }

  if (
    filters.length === 0 &&
    includesAny(text, ["10 - gastos gerais", "gastos gerais", "despesas gerais"])
  ) {
    filters.push({
      type: "grupo_dre",
      code: "10",
      value: "10 - GASTOS GERAIS",
      canonical_value: "10 - GASTOS GERAIS",
      sql_filter_hint: "pc.nivel_1_bi LIKE '10 -%'"
    });
  }

  if (
    filters.length === 0 &&
    includesAny(text, ["05 - cmv", "cmv"])
  ) {
    filters.push({
      type: "grupo_dre",
      code: "05",
      value: "05 - CMV",
      canonical_value: "05 - CMV",
      sql_filter_hint: "pc.nivel_1_bi LIKE '05 -%'"
    });
  }

  return filters;
}

function detectPeriods(text) {
  const periods = [];
  const warnings = [];

  const monthMap = {
    janeiro: 1,
    jan: 1,
    fevereiro: 2,
    fev: 2,
    marco: 3,
    mar: 3,
    abril: 4,
    abr: 4,
    maio: 5,
    mai: 5,
    junho: 6,
    jun: 6,
    julho: 7,
    jul: 7,
    agosto: 8,
    ago: 8,
    setembro: 9,
    set: 9,
    outubro: 10,
    out: 10,
    novembro: 11,
    nov: 11,
    dezembro: 12,
    dez: 12
  };

  const normalized = normalizeText(text);

  const monthNames = [
    "janeiro",
    "jan",
    "fevereiro",
    "fev",
    "marco",
    "mar",
    "abril",
    "abr",
    "maio",
    "mai",
    "junho",
    "jun",
    "julho",
    "jul",
    "agosto",
    "ago",
    "setembro",
    "set",
    "outubro",
    "out",
    "novembro",
    "nov",
    "dezembro",
    "dez"
  ].join("|");

  const monthNameRegex = new RegExp(
    `((?:orcado|orcamento|budget|realizado|executado)\\s+de\\s+)?\\b(${monthNames})\\s+de\\s+(20\\d{2})\\b`,
    "gi"
  );

  let match;
  while ((match = monthNameRegex.exec(normalized)) !== null) {
    const rawText = match[0];
    const monthName = match[2];
    const year = Number(match[3]);
    const month = monthMap[monthName];

    if (month && year) {
      const source = inferSource(rawText, normalized);
      periods.push(buildMonthPeriod(source, year, month, rawText));
    }
  }

  const numericRegex = /\b(0?[1-9]|1[0-2])\/(20\d{2})\b/g;
  while ((match = numericRegex.exec(normalized)) !== null) {
    const rawText = match[0];
    const month = Number(match[1]);
    const year = Number(match[2]);
    const source = inferSource(rawText, normalized);

    periods.push(buildMonthPeriod(source, year, month, rawText));
  }

  const isoRegex = /\b(20\d{2})-(0[1-9]|1[0-2])\b/g;
  while ((match = isoRegex.exec(normalized)) !== null) {
    const rawText = match[0];
    const year = Number(match[1]);
    const month = Number(match[2]);
    const source = inferSource(rawText, normalized);

    periods.push(buildMonthPeriod(source, year, month, rawText));
  }

  const seen = new Set();
  const uniquePeriods = [];

  for (const period of periods) {
    const key = `${period.source}|${period.start}|${period.end_exclusive}`;
    if (!seen.has(key)) {
      seen.add(key);
      uniquePeriods.push(period);
    }
  }

  if (
    uniquePeriods.length === 0 &&
    includesAny(text, [
      "mes",
      "mês",
      "periodo",
      "período",
      "ano",
      "acumulado",
      "comparado",
      "comparando"
    ])
  ) {
    warnings.push(
      "A pergunta menciona período/comparação, mas nenhum período explícito foi estruturado nesta etapa observacional."
    );
  }

  return {
    periods: uniquePeriods,
    warnings
  };
}

function detectComparison(text) {
  const comparison = {
    type: null,
    direction: null,
    raw_terms: []
  };

  if (
    includesAny(text, [
      "orcado vs realizado",
      "orçado vs realizado",
      "orcamento x realizado",
      "orçamento x realizado",
      "orcado e realizado",
      "orçado e realizado"
    ])
  ) {
    comparison.type = "actual_vs_budget";
    comparison.raw_terms.push("orcado_vs_realizado");
  }

  if (
    includesAny(text, [
      "comparado com",
      "comparando com",
      "contra",
      "versus",
      " vs "
    ])
  ) {
    comparison.type = comparison.type || "period_vs_period";
    comparison.raw_terms.push("comparacao_periodos");
  }

  if (
    includesAny(text, [
      "maiores e menores",
      "maior e menor",
      "melhor e pior",
      "ranking"
    ])
  ) {
    comparison.direction = "maiores_e_menores";
    comparison.raw_terms.push("ranking");
  }

  if (
    includesAny(text, [
      "estouro",
      "acima do orcamento",
      "acima do orçamento",
      "abaixo do orcamento",
      "abaixo do orçamento",
      "variacao",
      "variação"
    ])
  ) {
    comparison.type = comparison.type || "variance";
    comparison.raw_terms.push("variancia");
  }

  return comparison;
}

function buildSemanticRequestObservado(inputData) {
  const pergunta = inputData.pergunta || "";
  const perguntaNormalizada = inputData.pergunta_normalizada || pergunta;
  const detectedIntent = inputData.detected_intent || "consulta_geral";
  const ctx = inputData.contexto_ducklake || {};
  const dreRows = toArray(ctx.dre);

  const warnings = [];
  const text = perguntaNormalizada || pergunta;

  const dimensions = detectDimensions(text, inputData);
  const metrics = detectMetrics(text, detectedIntent);
  const dreFilters = detectDreFilters(text, dreRows);
  const periodResolution = detectPeriods(text);
  const comparison = detectComparison(text);

  warnings.push(...periodResolution.warnings);

  const outputGrain = uniqueArray([
    ...dreFilters.map(() => "grupo_dre"),
    ...dimensions
  ]);

  const filters = {
    grupo_dre: dreFilters.map((f) => f.canonical_value),
    marca: Array.isArray(inputData.marcas_detectadas) ? inputData.marcas_detectadas : [],
    centro_custo: [],
    raw: dreFilters
  };

  const needsClarification =
    metrics.includes("receita") &&
    includesAny(text, ["faturamento"]) &&
    !includesAny(text, [
      "rol",
      "receita liquida",
      "receita líquida",
      "receita bruta",
      "receita de vendas"
    ]);

  if (needsClarification) {
    warnings.push(
      "Termo 'faturamento' pode exigir definição de negócio: receita bruta, receita líquida, receita de vendas ou ROL."
    );
  }

  return {
    status: warnings.length > 0 ? "warning" : "observacao",
    source: "n8n_deterministic_observation",
    version: "e8-n8n-a-observado-v2",
    intent_family: detectedIntent,
    intent_confidence: inputData.intent_confidence || null,
    metrics,
    dimensions,
    filters,
    periods: periodResolution.periods,
    output_grain: outputGrain,
    comparison,
    needs_clarification: needsClarification,
    warnings,
    metadata: {
      generated_by: "Code - Montar Semantic Request Observado",
      mode: "observation_only",
      does_not_block_flow: true,
      does_not_generate_sql: true,
      contexto_contabil_permitido: inputData.contexto_contabil_permitido,
      dre_filters_detected: dreFilters.length,
      periods_detected: periodResolution.periods.length,
      marcas_detectadas: Array.isArray(inputData.marcas_detectadas)
        ? inputData.marcas_detectadas
        : []
    }
  };
}

try {
  const semanticRequestObservado = buildSemanticRequestObservado(input);

  return [
    {
      json: {
        ...input,
        semantic_request_observado: semanticRequestObservado
      }
    }
  ];
} catch (error) {
  return [
    {
      json: {
        ...input,
        semantic_request_observado: {
          status: "warning",
          source: "n8n_deterministic_observation",
          version: "e8-n8n-a-observado-v2",
          error_detail: String(
            error?.message || error || "Erro inesperado ao montar semantic_request_observado."
          ),
          warnings: [
            "Falha na observação semântica. Fluxo principal preservado."
          ],
          metadata: {
            generated_by: "Code - Montar Semantic Request Observado",
            mode: "observation_only",
            does_not_block_flow: true,
            does_not_generate_sql: true,
            observation_failed: true
          }
        }
      }
    }
  ];
}

// ============================================================
// CODE - AVALIAR REPARO SQL
// v2.2.41-generic-repair-router-state-safe
//
// Objetivo:
// - Decidir se uma SQL deve ir para reparo.
// - Não corrigir SQL.
// - Não usar hardcode de cliente, benchmark, marca, mês, tabela ou coluna.
// - Não usar $runIndex.
// - Controlar loop apenas por estado do item:
//   repair_attempts / sql_repair_attempt / repair_history.
// ============================================================

const input = $json || $input.first()?.json || {};

function safeString(value) {
  if (value === null || value === undefined) return '';

  if (typeof value === 'string') return value;

  try {
    return JSON.stringify(value);
  } catch (error) {
    return String(value);
  }
}

function normalizeText(value) {
  return safeString(value)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function cleanSql(value) {
  return safeString(value)
    .replace(/```sql/gi, '')
    .replace(/```/g, '')
    .replace(/;\s*$/g, '')
    .trim();
}

function firstNonEmpty(...values) {
  for (const value of values) {
    const text = cleanSql(value);
    if (text) return text;
  }

  return '';
}

function safeArray(value) {
  if (value === null || value === undefined) return [];

  if (Array.isArray(value)) return value;

  if (typeof value === 'string') {
    const text = value.trim();

    if (!text) return [];

    try {
      const parsed = JSON.parse(text);
      return Array.isArray(parsed) ? parsed : [parsed];
    } catch (error) {
      return [text];
    }
  }

  return [value];
}

function uniqueStrings(values) {
  return [
    ...new Set(
      values
        .filter((value) => value !== null && value !== undefined)
        .map((value) => String(value).trim())
        .filter(Boolean)
    )
  ];
}

function toNumber(value, fallback) {
  const number = Number(value);
  return Number.isFinite(number) ? number : fallback;
}

function unwrapPreflightSql(value) {
  const sql = cleanSql(value);

  if (!sql) return '';

  const match = sql.match(
    /^\s*select\s+\*\s+from\s*\(\s*([\s\S]*?)\s*\)\s+as\s+_ducklake_preflight\s+limit\s+0\s*;?\s*$/i
  );

  if (match && match[1]) {
    return cleanSql(match[1]);
  }

  return sql;
}

function extractSql(payload) {
  if (!payload || typeof payload !== 'object') return '';

  const direct = firstNonEmpty(
    payload.sql,
    payload.cleaned_sql,
    payload.sql_tentativa,
    payload.sql_original_aprovada_offline,
    payload.sql_gerada,
    payload.sql_limpa,
    payload.sql_reparada,
    payload.sql_corrigida,
    payload.sql_reparada_limpa,
    payload.generated_sql,
    payload.current_sql,
    payload.query,
    payload.query_executada_watson,
    payload.output,
    payload.text,
    payload.result,
    payload.candidates?.[0]?.content?.parts?.[0]?.text
  );

  if (direct) return unwrapPreflightSql(direct);

  const fromValidation = firstNonEmpty(
    payload.first_validation_error?.details?.preflight_sql,
    payload.validation_errors?.[0]?.details?.preflight_sql,
    payload.validacao_offline?.first_error?.details?.preflight_sql,
    payload.validacao_offline?.errors?.[0]?.details?.preflight_sql,
    payload.engine_preflight_result?.preflight_sql,
    payload.preflight_result?.preflight_sql,
    payload.sql_engine_preflight_sql
  );

  return unwrapPreflightSql(fromValidation);
}

function collectErrors(payload) {
  const errors = [];

  errors.push(...safeArray(payload.errors));
  errors.push(...safeArray(payload.error));
  errors.push(...safeArray(payload.validation_errors));
  errors.push(...safeArray(payload.first_validation_error));
  errors.push(...safeArray(payload.validacao_offline?.errors));
  errors.push(...safeArray(payload.validacao_offline?.validation_errors));
  errors.push(...safeArray(payload.validacao_offline?.first_error));
  errors.push(...safeArray(payload.engine_preflight_result?.errors));
  errors.push(...safeArray(payload.engine_preflight_result?.first_error));
  errors.push(...safeArray(payload.preflight_result?.errors));
  errors.push(...safeArray(payload.preflight_result?.first_error));

  return errors.filter(Boolean);
}

function collectErrorCodes(errors, payload) {
  const codes = [];

  for (const error of errors) {
    if (error && typeof error === 'object') {
      codes.push(error.code);
      codes.push(error.error_code);
      codes.push(error.type);
      codes.push(error.error_type);
    }
  }

  codes.push(...safeArray(payload.error_codes));
  codes.push(...safeArray(payload.validation_error_codes));
  codes.push(...safeArray(payload.validacao_offline?.error_codes));
  codes.push(...safeArray(payload.engine_preflight_result?.error_codes));
  codes.push(...safeArray(payload.preflight_result?.error_codes));

  return uniqueStrings(codes);
}

function collectErrorText(errors, payload) {
  const parts = [];

  for (const error of errors) {
    if (typeof error === 'string') {
      parts.push(error);
      continue;
    }

    if (error && typeof error === 'object') {
      parts.push(error.code);
      parts.push(error.error_code);
      parts.push(error.type);
      parts.push(error.error_type);
      parts.push(error.message);
      parts.push(error.error);
      parts.push(error.details?.message);
      parts.push(error.details?.error);
      parts.push(error.details?.engine_error_message);
      parts.push(error.details?.raw_result_preview);
      parts.push(error.details?.repair_goal);
    }
  }

  parts.push(payload.error);
  parts.push(payload.erro);
  parts.push(payload.message);
  parts.push(payload.detalhe);
  parts.push(payload.error_message);
  parts.push(payload.engine_error_message);
  parts.push(payload.status_operacional);
  parts.push(payload.tipo_entrega);

  parts.push(payload.validacao_offline?.message);
  parts.push(payload.validacao_offline?.error);
  parts.push(payload.validacao_offline?.engine_error_message);
  parts.push(payload.validacao_offline?.first_error?.message);
  parts.push(payload.validacao_offline?.first_error?.details?.engine_error_message);

  parts.push(payload.engine_preflight_result?.message);
  parts.push(payload.engine_preflight_result?.error);
  parts.push(payload.engine_preflight_result?.engine_error_message);

  parts.push(payload.preflight_result?.message);
  parts.push(payload.preflight_result?.error);
  parts.push(payload.preflight_result?.engine_error_message);

  return parts
    .filter((part) => part !== null && part !== undefined)
    .map(safeString)
    .filter(Boolean)
    .join(' | ');
}

function isWorkflowOrPayloadError(errorTextRaw) {
  const errorText = normalizeText(errorTextRaw);

  const patterns = [
    'flow input data does not match',
    'root value is missing the required field',
    'missing the required field',
    'parameter argument/count mismatch',
    'identifiers of the excess parameters',
    'json parameter needs to be valid json',
    'response body is not valid json',
    'response format'
  ];

  return patterns.some((pattern) =>
    errorText.includes(normalizeText(pattern))
  );
}

function isRepairableSqlEngineError(errorTextRaw, errorCodes) {
  const errorText = normalizeText(errorTextRaw);
  const codeText = normalizeText(errorCodes.join(' '));

  if (codeText.includes('sql_engine_preflight_failed')) {
    return true;
  }

  const patterns = [
    /binder error/i,
    /parser error/i,
    /syntax error/i,
    /catalog error/i,

    /does not have a column named/i,
    /table .* does not have .* column/i,
    /values list .* does not have .* column/i,
    /column .* not found/i,
    /referenced column .* not found/i,
    /no column named/i,
    /missing column/i,

    /ambiguous reference/i,
    /ambiguous column/i,
    /column reference .* ambiguous/i,

    /cannot be referenced before it is defined/i,
    /referenced .* before .* defined/i,
    /exists in the select clause .* cannot be referenced/i,

    /must appear in the group by clause/i,
    /not part of an aggregate function/i,

    /syntax error at or near/i,
    /unexpected token/i
  ];

  return patterns.some((pattern) => pattern.test(errorTextRaw));
}

// ============================================================
// SQL e erro
// ============================================================

const sql = extractSql(input);
const sqlNorm = normalizeText(sql);

const errors = collectErrors(input);
const errorCodes = collectErrorCodes(errors, input);
const errorText = collectErrorText(errors, input);

const workflowOrPayloadError = isWorkflowOrPayloadError(errorText);
const repairableSqlEngineError =
  isRepairableSqlEngineError(errorText, errorCodes);

const motivos = [];
const warnings = [];

if (!sql) {
  motivos.push('SQL ausente para avaliação/reparo.');
}

if (sql && !sqlNorm.startsWith('select') && !sqlNorm.startsWith('with')) {
  motivos.push('SQL não começa com SELECT ou WITH.');
}

if (workflowOrPayloadError) {
  motivos.push('Erro de workflow/payload detectado. Não é reparo de SQL.');
}

if (repairableSqlEngineError && !workflowOrPayloadError) {
  motivos.push('Erro técnico reparável detectado pelo motor SQL durante validação/preflight.');
}

if (/\blimit\s+\d+\b/i.test(sql)) {
  warnings.push('SQL contém LIMIT explícito. Este node apenas registra o aviso.');
}

// ============================================================
// Controle de tentativas por estado do item
// ============================================================

const previousRepairHistory = Array.isArray(input.repair_history)
  ? input.repair_history
  : [];

const attemptsFromPayload = toNumber(
  input.repair_attempts ??
  input.sql_repair_attempt ??
  input.repair_count ??
  input.current_repair_attempt ??
  0,
  0
);

const attemptsFromHistory = previousRepairHistory.length;

const repairAttemptsBefore = Math.max(
  attemptsFromPayload,
  attemptsFromHistory
);

const maxRepairAttempts = toNumber(
  input.max_repair_attempts ??
  input.options?.max_repair_attempts ??
  2,
  2
);

const hasRepairReason =
  motivos.length > 0 &&
  !workflowOrPayloadError;

const attemptsAvailable =
  repairAttemptsBefore < maxRepairAttempts;

const deveRepararSql =
  Boolean(hasRepairReason && attemptsAvailable);

const repairAttemptsAfter =
  deveRepararSql
    ? repairAttemptsBefore + 1
    : repairAttemptsBefore;

const repairExhausted =
  Boolean(hasRepairReason && !attemptsAvailable);

const currentHistoryEntry = hasRepairReason
  ? {
      attempt_before: repairAttemptsBefore,
      attempt_after: repairAttemptsAfter,
      max_repair_attempts: maxRepairAttempts,
      repair_will_run: deveRepararSql,
      repair_exhausted: repairExhausted,
      reason: motivos.join(' | '),
      error_codes: errorCodes,
      error_text: errorText || null,
      repairable_sql_engine_error: repairableSqlEngineError,
      workflow_or_payload_error: workflowOrPayloadError,
      evaluator_version: 'v2.2.41-generic-repair-router-state-safe'
    }
  : null;

const repairHistory = currentHistoryEntry
  ? [...previousRepairHistory, currentHistoryEntry]
  : previousRepairHistory;

// ============================================================
// Retorno
// ============================================================

return [
  {
    json: {
      ...input,

      sql,
      cleaned_sql: sql,
      sql_tentativa: sql,
      sql_gerada: sql,
      sql_original_gemini:
        input.sql_original_gemini ||
        input.sql_bruta ||
        input.sql_raw ||
        sql,

      deve_reparar_sql: deveRepararSql,
      repair_required: deveRepararSql,

      motivos_reparo_sql: motivos,
      motivo_reparo_sql: motivos.join(' | '),
      warnings_reparo_sql: warnings,

      repair_attempts_before: repairAttemptsBefore,
      repair_attempts: repairAttemptsAfter,
      repair_count: repairAttemptsAfter,
      current_repair_attempt: repairAttemptsAfter,
      sql_repair_attempt: repairAttemptsAfter,
      max_repair_attempts: maxRepairAttempts,
      repair_exhausted: repairExhausted,
      repair_history: repairHistory,

      repairable_sql_engine_error_detected:
        repairableSqlEngineError,

      workflow_or_payload_error_detected:
        workflowOrPayloadError,

      repair_attempts_available:
        attemptsAvailable,

      preflight_error_codes: errorCodes,
      preflight_error_text: errorText || null,

      repair_evaluator_version:
        'v2.2.41-generic-repair-router-state-safe',

      output_items_emitidos: 1
    }
  }
];

