  }
}

function safeJson(value) {
  try {
    return JSON.stringify(value ?? null, null, 2);
  } catch (error) {
    return 'null';
  }
}

function compactSql(value) {
  return safeString(value)
    .replace(/```sql/gi, '')
    .replace(/```/g, '')
    .replace(/;\s*$/g, '')
    .trim();
}

function firstNonEmpty(...values) {
