function isIdentifierCharacter(character) {
  if (!character) return false;

  const code = character.charCodeAt(0);

  return (
    (code >= 48 && code <= 57) ||
    (code >= 65 && code <= 90) ||
    (code >= 97 && code <= 122) ||
    character === '_' ||
    character === '$'
  );
}

function requiresSeparator(previousCharacter, nextCharacter) {
  if (!previousCharacter || !nextCharacter) return false;

  if (
    isIdentifierCharacter(previousCharacter) &&
    isIdentifierCharacter(nextCharacter)
  ) {
    return true;
  }

  if (
    isIdentifierCharacter(previousCharacter) &&
    (nextCharacter === "'" || nextCharacter === '"')
  ) {
    return true;
  }

  if (
    (previousCharacter === "'" || previousCharacter === '"') &&
    isIdentifierCharacter(nextCharacter)
  ) {
    return true;
  }

  if (
    previousCharacter === ')' &&
    isIdentifierCharacter(nextCharacter)
  ) {
    return true;
  }

  return false;
}

function compactSqlForTransport(sql) {
  const output = [];

  let state = 'normal';
  let pendingWhitespace = false;
  let index = 0;

  while (index < sql.length) {
    const character = sql[index];
    const nextCharacter =
      index + 1 < sql.length ? sql[index + 1] : '';

    if (state === 'normal') {
      if (character === "'") {
        if (
          pendingWhitespace &&
          output.length > 0 &&
          requiresSeparator(output[output.length - 1], character)
        ) {
          output.push(' ');
        }

        pendingWhitespace = false;
        output.push(character);
        state = 'single_quote';
        index += 1;
        continue;
      }

      if (character === '"') {
        if (
          pendingWhitespace &&
          output.length > 0 &&
          requiresSeparator(output[output.length - 1], character)
        ) {
          output.push(' ');
        }

        pendingWhitespace = false;
        output.push(character);
        state = 'double_quote';
        index += 1;
        continue;
      }

      if (character === '-' && nextCharacter === '-') {
        pendingWhitespace = true;
        index += 2;

        while (
          index < sql.length &&
          sql[index] !== '\n' &&
          sql[index] !== '\r'
        ) {
          index += 1;
        }

        continue;
      }

      if (character === '/' && nextCharacter === '*') {
        pendingWhitespace = true;
        index += 2;

        while (
          index + 1 < sql.length &&
          !(sql[index] === '*' && sql[index + 1] === '/')
        ) {
          index += 1;
        }

        if (index + 1 < sql.length) {
          index += 2;
        }

        continue;
      }

      if (
        character === ' ' ||
        character === '\t' ||
        character === '\n' ||
        character === '\r' ||
        character === '\f'
      ) {
        pendingWhitespace = true;
        index += 1;
        continue;
      }

      if (
        pendingWhitespace &&
        output.length > 0 &&
        requiresSeparator(output[output.length - 1], character)
      ) {
        output.push(' ');
      }

      pendingWhitespace = false;
      output.push(character);
      index += 1;
      continue;
    }

    if (state === 'single_quote') {
      output.push(character);

      if (character === "'") {
        if (nextCharacter === "'") {
          output.push(nextCharacter);
          index += 2;
          continue;
        }

        state = 'normal';
      }

      index += 1;
      continue;
    }

    if (state === 'double_quote') {
      output.push(character);

      if (character === '"') {
        if (nextCharacter === '"') {
          output.push(nextCharacter);
          index += 2;
          continue;
        }

        state = 'normal';
      }

      index += 1;
      continue;
    }
  }

  if (state !== 'normal') {
    throw new Error('Não foi possível compactar a SQL de preflight: aspas não foram encerradas.');
  }

  return output.join('').trim();
}

