    if (Array.isArray(allItems) && allItems.length > 1) {
      throw new Error(
        `Não foi possível recuperar item pareado de ${nodeName}; o node possui múltiplos itens.`
      );
    }
  } catch (error) {
    throw new Error(
      `Falha ao recuperar contexto pareado de ${nodeName}: ${error.message}`
    );
  }

  return {};
}

const contextFromInput = raw.preflight_payload_context || {};

const context = (
  contextFromInput &&
  contextFromInput.body &&
  contextFromInput.body.sql_query
)
  ? contextFromInput
  : getPairedNodeJson('Code - Montar Payload Preflight Watson');

function pick(obj, paths, fallback = undefined) {
  for (const path of paths) {
    const parts = path.split('.');
    let current = obj;

    for (const part of parts) {
      if (
        current &&
        Object.prototype.hasOwnProperty.call(current, part)
      ) {
        current = current[part];
      } else {
        current = undefined;
        break;
      }
    }

    if (current !== undefined && current !== null) {
      return current;
    }
  }

  return fallback;
}

function toArray(value) {
  return Array.isArray(value) ? value : [];
}

function uniqueArray(values) {
  return [...new Set((values || []).filter(Boolean))];
}

function parseJsonIfString(value) {
  if (typeof value !== 'string') return value;

  const text = value.trim();

  if (!text) return value;

  if (
    !text.startsWith('{') &&
    !text.startsWith('[')
  ) {
    return value;
  }

  try {
    return JSON.parse(text);
  } catch (error) {
    return value;
  }
}

function extractPayload(rawValue) {
  const parsedBody = parseJsonIfString(rawValue.body);
  const parsedData = parseJsonIfString(rawValue.data);
  const parsedResult = parseJsonIfString(rawValue.result);
  const parsedOutput = parseJsonIfString(rawValue.output);

  return (
    parsedBody?.result?.output ||
    parsedBody?.output?.result ||
    parsedBody?.result ||
    parsedBody?.output ||
    parsedBody ||

    parsedData?.result?.output ||
    parsedData?.output?.result ||
    parsedData?.result ||
    parsedData?.output ||
    parsedData ||

    parsedResult?.output ||
    parsedResult ||

    parsedOutput?.result ||
    parsedOutput ||

    rawValue.result?.output ||
    rawValue.output?.result ||
    rawValue.result ||
    rawValue.output ||
    rawValue.data ||
    rawValue
  );
}

function stringifyErrorValue(item) {
  if (typeof item === 'string') return item;

  if (item && typeof item === 'object') {
    try {
      return JSON.stringify(item);
    } catch (error) {
      return String(item);
    }
  }

  return String(item || '');
}

function extractErrorMessage(payload) {
  const value = pick(payload, [
    'error_message',
    'error',
    'message',
    'result.error_message',
    'result.error',
    'result.message',
    'output.error_message',
    'output.error',
    'output.message'
  ], null);

  if (Array.isArray(value)) {
    return value
      .map(stringifyErrorValue)
      .filter(Boolean)
      .join('\n');
  }

  return stringifyErrorValue(value);
}

const payload = extractPayload(raw);

const successValue = pick(payload, [
  'success',
  'result.success',
  'output.success'
], undefined);

const errorMessage = extractErrorMessage(payload);

const hasExplicitSuccess =
  successValue === true ||
  successValue === 'true';

const hasExplicitFailure =
  successValue === false ||
  successValue === 'false';

const preflightOk =
  hasExplicitSuccess &&
  !errorMessage;

const originalSql = String(
  context.sql_original_aprovada_offline ||
  context.sql ||
  context.cleaned_sql ||
  context.sql_tentativa ||
  ''
).trim();

const preflightSql = String(
  context.sql_engine_preflight_sql ||
  ''
).trim();

if (preflightOk) {
  return [
    {
      json: {
        ...context,

        sql: originalSql,
        sql_query: originalSql,
        sql_tentativa: originalSql,
        cleaned_sql: originalSql,

        success: true,
        is_valid: true,
        sql_aprovada: true,

        validation_status: 'aprovado',
        validation_errors: [],
        validation_error_codes: [],
        first_validation_error: null,

        sql_engine_preflight: {
          requested: true,
          success: true,
          status: 'aprovado',
          mode: 'limit_zero_compile_check',
          row_count: pick(payload, [
            'row_count',
            'rowCount',
            'result.row_count',
            'output.row_count'
          ], 0),
          execution_time_ms: pick(payload, [
            'execution_time_ms',
            'executionTimeMs',
            'elapsed_ms',
            'result.execution_time_ms',
            'output.execution_time_ms'
          ], null),
          query_id: pick(payload, [
            'query_id',
            'queryId',
            'id',
            'result.query_id',
            'output.query_id'
          ], null)
        },

        status_operacional:
          'sql_validada_offline_e_preflight_watson',

        observacao:
          'A SQL foi validada offline e compilou no motor SQL real via preflight LIMIT 0. Pode ser entregue para execução manual no Watson.',

        preflight_normalizer_version:
          'v2.2.38-paired-state-retry-context-safe'
      }
    }
  ];
}

const syntheticErrorMessage =
  errorMessage ||
  (
    hasExplicitFailure
      ? 'Watson/DuckLake retornou success=false sem mensagem textual.'
      : 'Watson/DuckLake não retornou success=true no preflight.'
  );

const previousErrors = toArray(context.validation_errors);

const engineError = {
  code: 'SQL_ENGINE_PREFLIGHT_FAILED',
  message:
    'O motor SQL rejeitou a query durante o preflight técnico. A consulta não foi aprovada para entrega.',
  details: {
    engine_error_message: syntheticErrorMessage,
    preflight_mode: 'limit_zero_compile_check',
    preflight_sql: preflightSql.slice(0, 12000),
    raw_result_preview: JSON.stringify(payload).slice(0, 4000),
    repair_goal:
      'Corrigir genericamente apenas o erro técnico apontado pelo motor SQL nesta execução, preservando filtros, métricas, datas, granularidade e semântica.'
  }
};

const validationErrors = [
  engineError,
  ...previousErrors
];

const codes = uniqueArray([
  ...toArray(context.validation_error_codes),
  ...validationErrors.map((err) =>
    err.code ||
    err.error_code ||
    'VALIDATION_ERROR_SEM_CODIGO'
  )
]);

return [
  {
    json: {
      ...context,

      sql: originalSql,
      sql_query: originalSql,
      sql_tentativa: originalSql,
      cleaned_sql: originalSql,

      success: false,
      is_valid: false,
      sql_aprovada: false,

      validation_status: 'reprovado',
      validation_errors: validationErrors,
      validation_error_codes: codes,
      first_validation_error: engineError,

      sql_engine_preflight: {
        requested: true,
        success: false,
        status: 'reprovado',
        mode: 'limit_zero_compile_check',
        error_message: syntheticErrorMessage,
        raw_result_preview: JSON.stringify(payload).slice(0, 4000)
      },

      status_operacional:
        'erro_preflight_sql_engine',

      observacao:
        'A query não foi entregue porque o motor SQL real rejeitou a compilação no preflight. O erro foi enviado ao loop de reparo.',

      preflight_normalizer_version:
        'v2.2.38-paired-state-retry-context-safe'
    }
  }
];

// ============================================================
// CODE - DIAGNOSTICAR RETORNO PREFLIGHT SQL
// v1.2-preflight-diagnostic-compact-safe
//
// Não aprova SQL.
// Não reprova SQL.
// Não repara SQL.
// Apenas classifica o retorno do HTTP Preflight.
// ============================================================

const httpOutput = $json || {};

function getNodeJsonSafe(nodeName) {
  try {
    const paired = $(nodeName).item?.json;
    if (paired && Object.keys(paired).length > 0) {
      return paired;
    }
  } catch (error) {}

  try {
    const all = $(nodeName).all();
    if (Array.isArray(all) && all.length === 1) {
      return all[0].json || {};
    }
  } catch (error) {}

  return {};
}

function parseJsonIfString(value) {
  if (typeof value !== 'string') return value;

  const text = value.trim();
  if (!text) return value;

  if (!text.startsWith('{') && !text.startsWith('[')) {
    return value;
  }

  try {
    return JSON.parse(text);
  } catch (error) {
    return value;
  }
}

function asText(value) {
  if (value === null || value === undefined) return '';

  if (typeof value === 'string') return value;

  try {
    return JSON.stringify(value);
  } catch (error) {
    return String(value);
  }
}

function normalizeText(value) {
  return asText(value)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function keysOf(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return [];
  }

  return Object.keys(value);
}

function extractPayload(output) {
  const body = parseJsonIfString(output.body);
  const data = parseJsonIfString(output.data);
  const result = parseJsonIfString(output.result);
  const outputField = parseJsonIfString(output.output);

  return (
    body?.result?.output ||
    body?.output?.result ||
    body?.result ||
    body?.output ||
    body ||

    data?.result?.output ||
    data?.output?.result ||
    data?.result ||
    data?.output ||
    data ||

    result?.output ||
    result ||

    outputField?.result ||
    outputField ||

    output.result?.output ||
    output.output?.result ||
    output.result ||
    output.output ||
    output
  );
}

function extractError(payload) {
  const candidates = [
    payload?.error,
    payload?.error_message,
    payload?.message,
    payload?.result?.error,
    payload?.result?.error_message,
    payload?.result?.message,
    payload?.output?.error,
    payload?.output?.error_message,
    payload?.output?.message
  ];

  return candidates
    .map(asText)
    .filter(Boolean)
    .join(' | ');
}

function classify(errorText, payload, output) {
  const text = normalizeText(errorText);

  const statusRaw =
    payload?.http_status ||
    payload?.status ||
    output?.http_status ||
    output?.status ||
    null;

  const status = Number(statusRaw);

  const isHttp5xx =
    Number.isFinite(status) &&
    status >= 500 &&
    status <= 599;

  const isTimeout =
    text.includes('timeout') ||
    text.includes('timed out') ||
    text.includes('etimedout') ||
    text.includes('econnreset') ||
    text.includes('socket hang up') ||
    text.includes('connection reset');

  const isParameterMismatch =
    text.includes('parameter argument/count mismatch') ||
    text.includes('identifiers of the excess parameters') ||
    text.includes('excess parameters');

  const mentionsSqlQuery = text.includes('sql_query');
  const mentionsLimit = text.includes('limit');

  const isBinderError =
    text.includes('binder error') ||
    (
      text.includes('column') &&
      (
        text.includes('not found') ||
        text.includes('does not have') ||
        text.includes('referenced') ||
        text.includes('cannot be referenced')
      )
    );

  const isCatalogError =
    text.includes('catalog error') ||
    text.includes('table with name') ||
    text.includes('does not exist');

  const isParserError =
    text.includes('parser error') ||
    text.includes('syntax error');

  const isRealSqlEngineError =
    isBinderError ||
    isCatalogError ||
    isParserError;

  const isTransportOrParameterError =
    !isRealSqlEngineError &&
    (
      isHttp5xx ||
      isTimeout ||
      (isParameterMismatch && mentionsSqlQuery)
    );

  let category = 'unknown_preflight_error';

  if (payload?.success === true || output?.success === true) {
    category = 'preflight_success';
  } else if (isTransportOrParameterError) {
    category = 'preflight_transport_or_parameter_error';
  } else if (isRealSqlEngineError) {
    category = 'real_sql_engine_error';
  }

  return {
    category,
    http_status: Number.isFinite(status) ? status : null,
    is_http_5xx: isHttp5xx,
    is_timeout: isTimeout,
    is_parameter_mismatch: isParameterMismatch,
    mentions_sql_query: mentionsSqlQuery,
    mentions_limit_parameter: mentionsLimit,
    is_transport_or_parameter_error: isTransportOrParameterError,
    is_real_sql_engine_error: isRealSqlEngineError,
    is_binder_error: isBinderError,
    is_catalog_error: isCatalogError,
    is_parser_error: isParserError
  };
}

let preflightContext = getNodeJsonSafe('Code - Preparar Retry Preflight SQL');

if (!preflightContext?.body?.sql_query) {
  preflightContext = getNodeJsonSafe('Code - Montar Payload Preflight Watson');
}

const configuredBody = preflightContext.body || {};
const bodyKeys = keysOf(configuredBody);

const httpPayload = extractPayload(httpOutput);
const errorMessage = extractError(httpPayload);
const classification = classify(errorMessage, httpPayload, httpOutput);

const retryAttempts = Number(
  preflightContext.preflight_transport_retry_attempts || 0
);

const diagnostic = {
  diagnostic_version: 'v1.2-preflight-diagnostic-compact-safe',

  payload_version: preflightContext.payload_version || null,
  preflight_payload_policy: preflightContext.preflight_payload_policy || null,

  configured_http_body_keys: bodyKeys,
  configured_http_body_has_only_sql_query:
    bodyKeys.length === 1 && bodyKeys[0] === 'sql_query',

  configured_http_body_has_sql_query:
    Object.prototype.hasOwnProperty.call(configuredBody, 'sql_query'),

  configured_http_body_has_limit:
    Object.prototype.hasOwnProperty.call(configuredBody, 'limit'),

  preflight_payload_top_level_keys: keysOf(preflightContext),

  preflight_payload_top_level_has_sql_query:
    Object.prototype.hasOwnProperty.call(preflightContext, 'sql_query'),

  preflight_payload_top_level_has_limit:
    Object.prototype.hasOwnProperty.call(preflightContext, 'limit'),

  sql_transport_chars:
    String(preflightContext.sql_engine_preflight_sql_transport || '').length,

  preflight_transport_retry_attempts: retryAttempts,

  http_output_keys: keysOf(httpOutput),
  extracted_http_payload_keys: keysOf(httpPayload),

  http_success_value:
    httpPayload?.success ??
    httpOutput?.success ??
    null,

  error_message_preview: errorMessage.slice(0, 2000),

  error_classification: classification
};

return [
  {
    json: {
      ...httpOutput,

      preflight_payload_context: preflightContext,
      preflight_http_diagnostic: diagnostic,

      preflight_diag_category:
        diagnostic.error_classification.category,

      preflight_diag_body_keys:
        diagnostic.configured_http_body_keys,

      preflight_diag_body_has_only_sql_query:
        diagnostic.configured_http_body_has_only_sql_query,

      preflight_diag_body_has_limit:
        diagnostic.configured_http_body_has_limit,

      preflight_diag_top_level_has_limit:
        diagnostic.preflight_payload_top_level_has_limit,

      preflight_diag_top_level_has_sql_query:
        diagnostic.preflight_payload_top_level_has_sql_query,

      preflight_diag_retry_attempts:
        diagnostic.preflight_transport_retry_attempts,

      preflight_diag_error_preview:
        diagnostic.error_message_preview
    }
  }
];

// ============================================================
// CODE - AVALIAR RETRY PREFLIGHT TRANSPORTE
// v1.0-preflight-transport-retry-evaluator
//
// Objetivo:
// - Decidir retry apenas para falhas transitórias de preflight.
// - Não repara SQL.
// - Não aprova SQL.
// - Não usa benchmark_id, cliente, schema, tabela ou pergunta.
// ============================================================

const input = $json || {};

const diagnostic = input.preflight_http_diagnostic || {};
const classification = diagnostic.error_classification || {};
const context = input.preflight_payload_context || {};

const maxRetries = Number(
  context.max_preflight_transport_retries ??
  input.max_preflight_transport_retries ??
  2
);

const currentAttempts = Number(
  context.preflight_transport_retry_attempts ??
  diagnostic.preflight_transport_retry_attempts ??
  input.preflight_transport_retry_attempts ??
  0
);

const bodyHasOnlySqlQuery =
  diagnostic.configured_http_body_has_only_sql_query === true;

const bodyHasLimit =
  diagnostic.configured_http_body_has_limit === true;

const topLevelHasLimit =
  diagnostic.preflight_payload_top_level_has_limit === true;

const isTransportOrParameterError =
  classification.is_transport_or_parameter_error === true ||
  classification.category === 'preflight_transport_or_parameter_error';

const isRealSqlEngineError =
  classification.is_real_sql_engine_error === true ||
  classification.category === 'real_sql_engine_error';

const preflightSuccess =
  classification.category === 'preflight_success' ||
  diagnostic.http_success_value === true;

const retryAvailable =
  Number.isFinite(currentAttempts) &&
  Number.isFinite(maxRetries) &&
  currentAttempts < maxRetries;

const deveRetry =
  !preflightSuccess &&
  isTransportOrParameterError &&
  !isRealSqlEngineError &&
  bodyHasOnlySqlQuery &&
  !bodyHasLimit &&
  !topLevelHasLimit &&
  retryAvailable;

let retryReason = null;

if (deveRetry) {
  retryReason =
    'Falha transitória de transporte/parâmetro no preflight; repetir o mesmo preflight com o mesmo body limpo.';
} else if (preflightSuccess) {
  retryReason =
    'Preflight retornou sucesso; não há retry.';
} else if (isRealSqlEngineError) {
  retryReason =
    'Erro real do motor SQL; não deve usar retry de transporte.';
} else if (!isTransportOrParameterError) {
  retryReason =
    'Erro não classificado como transporte/parâmetro transitório.';
} else if (!bodyHasOnlySqlQuery || bodyHasLimit || topLevelHasLimit) {
  retryReason =
    'Payload não está limpo para retry seguro.';
} else if (!retryAvailable) {
  retryReason =
    'Limite máximo de retries de preflight atingido.';
}

return [
  {
    json: {
      ...input,

      deve_retry_preflight_transporte: deveRetry,
      preflight_transport_retry_required: deveRetry,

      preflight_transport_retry_attempts: currentAttempts,
      preflight_transport_retry_max_attempts: maxRetries,
      preflight_transport_retry_available: retryAvailable,

      preflight_transport_retry_reason: retryReason,

      preflight_transport_retry_policy:
        'retry_somente_para_falha_transitoria_de_preflight_sem_alterar_sql',

      preflight_transport_retry_evaluator_version:
        'v1.0-preflight-transport-retry-evaluator'
    }
  }
];

// ============================================================
// CODE - PREPARAR RETRY PREFLIGHT SQL
// v1.0-prepare-preflight-transport-retry
//
// Objetivo:
// - Reemitir o payload original do preflight.
// - Incrementar contador de retry.
// - Não alterar SQL.
// - Não alterar body.
// - Não alterar prompt.
// - Não aplicar hardcode.
// ============================================================

const input = $json || {};

const context = input.preflight_payload_context || {};

if (
  !context ||
  !context.body ||
  !context.body.sql_query
) {
  throw new Error(
    'Não foi possível preparar retry: preflight_payload_context.body.sql_query ausente.'
  );
}

const previousAttempts = Number(
  context.preflight_transport_retry_attempts ??
  input.preflight_transport_retry_attempts ??
  0
);

const nextAttempt = previousAttempts + 1;

const retryHistory = Array.isArray(context.preflight_transport_retry_history)
  ? context.preflight_transport_retry_history
  : [];

const retryEvent = {
  attempt: nextAttempt,
  reason:
    input.preflight_transport_retry_reason ||
    'Retry de preflight por falha transitória de transporte/parâmetro.',
  previous_error_category:
    input.preflight_diag_category ||
    input.preflight_http_diagnostic?.error_classification?.category ||
    null,
  previous_error_preview:
    input.preflight_diag_error_preview ||
    input.preflight_http_diagnostic?.error_message_preview ||
    null,
  created_at: new Date().toISOString()
};

return [
  {
    json: {
      ...context,

      body: context.body,

      preflight_transport_retry_attempts: nextAttempt,
      preflight_transport_retry_history: [
        ...retryHistory,
        retryEvent
      ],

      preflight_transport_retry_last_reason:
        retryEvent.reason,

      preflight_transport_retry_prepare_version:
        'v1.0-prepare-preflight-transport-retry'
    }
  }
];
